  ('official_bank_ent211', 'add', 1, $official_bank_source${"itemId":"1b066ad4-39f8-5b5a-9283-9679eb06fbd6","questionId":"98007bd1-5d41-5417-9181-a12e0e1e46d5","sourceKey":"bank:ENT211:ENT211-W01-001","payload":{"prompt":"Aliko Dangote, used as an introductory example of entrepreneurship, started his small trading business at what age?","options":["25 years old","18 years old","30 years old","21 years old"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Dangote started his small trading business as a young man of 21. Options B, A and C give other ages, but his story begins at 21, showing that entrepreneurship can start early with modest means."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 2, $official_bank_source${"itemId":"62935105-ca40-5223-a208-1661568d409b","questionId":"f9d347dd-7604-519a-8df8-63293aaace85","sourceKey":"bank:ENT211:ENT211-W01-002","payload":{"prompt":"Aliko Dangote, who started a small trading business as a young man, came from which Nigerian state?","options":["Lagos State","Kano State","Kaduna State","Kogi State"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Dangote is described as a young man from Kano State who began by trading. Options A, C and D are other Nigerian states that do not feature in his story."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 3, $official_bank_source${"itemId":"32e98b8e-b12c-5e1e-bf84-acbebac220b3","questionId":"8b511794-86af-5c61-8306-4618363a1f00","sourceKey":"bank:ENT211:ENT211-W01-003","payload":{"prompt":"How did Aliko Dangote fund the small trading business he started at 21?","options":["With a loan from his uncle","With savings from a salaried job","With a loan from a commercial bank","With a grant from the government"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Dangote started his trading business with a loan from his uncle, a good example of mobilising whatever resources are available. Options D, C and B sound like common ways to fund a business, but none of them is how his story began."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 4, $official_bank_source${"itemId":"bf43ebb0-bcd8-5c17-92ab-4ca7c5ab5210","questionId":"13cead98-ef3c-5659-ae4b-692fc3dbb33b","sourceKey":"bank:ENT211:ENT211-W01-004","payload":{"prompt":"Which goods did the young Aliko Dangote buy and sell in his early trading business?","options":["Sugar, rice and cement","Cocoa, groundnut and cotton","Salt, pasta and fertilizer","Petroleum, gas and diesel"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"As a trader, Dangote bought and sold sugar, rice and cement, delivering the goods himself. Option C lists products his companies make today, not what he traded at the start, while B and D are not part of his story."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 5, $official_bank_source${"itemId":"39b29bdf-aa3f-5d0b-8cd6-2bc1232fd374","questionId":"fe1e777a-2f63-5283-ba05-1cf5248fad48","sourceKey":"bank:ENT211:ENT211-W01-005","payload":{"prompt":"Aliko Dangote noticed that Nigeria imported almost every product it consumed. What bigger opportunity did he see in this?","options":["Export Nigerian raw produce to other countries","Import the same goods more cheaply than others","Open retail shops to sell imported goods","Produce locally what the country was importing"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Seeing that Nigeria imported almost everything it consumed, Dangote saw the bigger opportunity to produce locally what the country was importing. Options B and C would keep him dependent on imports, and A is about exporting raw produce, which is not the gap he spotted."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 6, $official_bank_source${"itemId":"4a19bac0-3d27-56a5-892a-45662fb19509","questionId":"567f4fb6-4193-5bd0-88c0-08a1100a1124","sourceKey":"bank:ENT211:ENT211-W01-006","payload":{"prompt":"When Aliko Dangote took the bold step from trading into manufacturing, which product did he start with?","options":["Fertilizer","Sugar","Cement","Pasta"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Dangote's bold step into manufacturing started with cement. Options B, D and A are products his companies make today, but they were not where his manufacturing journey began."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 7, $official_bank_source${"itemId":"5bc31177-dba4-5307-8ce2-e85238352fa7","questionId":"1908f55e-bb7e-5f96-a107-c284f65c478e","sourceKey":"bank:ENT211:ENT211-W01-007","payload":{"prompt":"Aliko Dangote's companies today produce several products. Which of the following is NOT one of the products listed for his companies?","options":["Pasta","Petroleum products","Purified bottled water","Salt"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Dangote's companies produce cement, sugar, salt, pasta, fertilizer and petroleum products. Purified bottled water is the business of Tunde in a different case study, so C is the odd one out, while D, A and B are all on Dangote's list."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 8, $official_bank_source${"itemId":"0ae6d569-1ab4-56b1-8918-e43811a1e3cf","questionId":"644f48c7-2400-5b2f-8bcd-24e467672583","sourceKey":"bank:ENT211:ENT211-W01-008","payload":{"prompt":"What does the story of Aliko Dangote show about where entrepreneurship begins?","options":["With copying successful foreign businesses without changes","With spotting opportunities, taking risks and creating value that meets national needs","With securing government contracts before starting any business","With inheriting a large family fortune and a ready market"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Dangote's journey shows that entrepreneurship begins with spotting opportunities, taking risks and creating value that meets national needs. He started small with a loan, so D is wrong, and his story says nothing about C or A."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 9, $official_bank_source${"itemId":"25014ff1-5db4-5151-9ea5-8de79fb13c0b","questionId":"5e0a8abf-a5f4-51b2-b676-503585db98fe","sourceKey":"bank:ENT211:ENT211-W01-009","payload":{"prompt":"Besides producing goods, what wider impact are Aliko Dangote's companies described as having?","options":["Increasing Nigeria's dependence on imports","Creating jobs and transforming industries","Replacing the need for small traders","Reducing the number of local manufacturers"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Dangote's companies are described as creating jobs and transforming industries. Option A is the opposite of his aim of producing locally, and D and C are not claims made about his companies."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 10, $official_bank_source${"itemId":"ca4fe6d4-d128-51a7-ae4c-6863a36c3027","questionId":"c4e6ad00-2300-517c-af92-adb0ba1965ea","sourceKey":"bank:ENT211:ENT211-W01-010","payload":{"prompt":"The process of identifying opportunities, mobilizing resources, creating innovative products or services and taking risks to generate value and achieve profit is called","options":["Resource mobilisation","Corporate management","Entrepreneurship","Value creation"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"This is the definition of entrepreneurship: it brings together opportunities, resources, innovation and risk to generate value and profit. Options A and D are only single parts of that process (they appear as dimensions of entrepreneurship), and B is not defined this way."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 11, $official_bank_source${"itemId":"262f90ba-6ad3-5053-95ac-5efab48403b7","questionId":"83793cf1-2d91-5e0f-b3fa-5c5a5333432a","sourceKey":"bank:ENT211:ENT211-W01-011","payload":{"prompt":"In the definition of entrepreneurship as a process, entrepreneurs identify opportunities, mobilize resources, create innovative products or services and take risks in order to","options":["Generate value and achieve profit","Secure government jobs and grants","Copy existing products at lower cost","Avoid competition and reduce taxes"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Entrepreneurship ends in generating value and achieving profit; that is the reason for taking on all the effort and risk. Options D, B and C are not part of the definition."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 12, $official_bank_source${"itemId":"032a5fcf-c28a-56f8-a0a4-1affa32e082c","questionId":"6d70890d-52f7-5666-9208-bd5aad1ef8bd","sourceKey":"bank:ENT211:ENT211-W01-012","payload":{"prompt":"Which of the following is NOT part of the definition of entrepreneurship as the process of creating value and profit?","options":["Creating innovative products or services","Mobilizing resources","Identifying opportunities","Delegating all risks to the government"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"The definition includes identifying opportunities, mobilizing resources, creating innovative products or services and taking risks. Entrepreneurs take risks themselves, so D does not belong, while C, B and A are all in the definition."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 13, $official_bank_source${"itemId":"4284b06f-cad5-5a11-895a-6291c4d32548","questionId":"d35204cf-1e2f-5503-810c-a8a3dc9b036a","sourceKey":"bank:ENT211:ENT211-W01-013","payload":{"prompt":"Apart from being a process of creating value and profit, entrepreneurship is also described as the mindset and process of","options":["Avoiding risks, saving money and waiting for stability","Importing goods, reselling them and keeping the margin","Following instructions, meeting targets and earning wages","Discovering problems, designing innovative solutions and delivering value"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Entrepreneurship as a mindset means discovering problems, designing innovative solutions and delivering value. Option A avoids risk, which entrepreneurs embrace, C describes an employee, and B is simple trading without innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 14, $official_bank_source${"itemId":"a99cda53-16ec-5082-a0e1-79ab9ce200a5","questionId":"e5d295a0-7f67-5e37-9a4a-01added51285","sourceKey":"bank:ENT211:ENT211-W01-014","payload":{"prompt":"When entrepreneurship is described as a mindset and process, to whom is value delivered?","options":["Family members and friends only","Government agencies only","Shareholders only","Society, markets or organisations"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"The mindset view says entrepreneurs deliver value to society, markets or organisations, which is a broad set of beneficiaries. Options C, B and A are too narrow because each limits value to only one small group."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 15, $official_bank_source${"itemId":"8ff6d447-19c5-52b9-b175-6843d5ae21c4","questionId":"daad7404-d0c8-5e08-8635-5d1ea8d861e8","sourceKey":"bank:ENT211:ENT211-W01-015","payload":{"prompt":"In simple terms, entrepreneurship can be expressed by which formula?","options":["Innovation + Autonomy + Networking + Profit","Opportunity + Capital + Labour + Profit","Idea + Money + Marketing + Profit","Opportunity + Innovation + Value Creation + Risk"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"The simple formula is Entrepreneurship = Opportunity + Innovation + Value Creation + Risk. Options B, C and A each swap in elements like capital, money, autonomy or profit that are not part of this formula."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 16, $official_bank_source${"itemId":"d8d68920-29ee-5d5d-a417-dd494cdbc0c6","questionId":"ffb745db-7637-5696-92ef-2a6f785c4359","sourceKey":"bank:ENT211:ENT211-W01-016","payload":{"prompt":"Complete the formula: Entrepreneurship = Opportunity + Innovation + ________ + Risk","options":["Value Creation","Autonomy","Resource Mobilisation","Profit"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"The missing element is Value Creation, giving Opportunity + Innovation + Value Creation + Risk. Option D is mentioned in the full definition but is not in the formula, and C and B are dimensions of entrepreneurship, not formula elements."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 17, $official_bank_source${"itemId":"b55fd398-c68f-567a-a157-ae278a7478c8","questionId":"502502e8-247f-507c-840f-22f9dae96ce1","sourceKey":"bank:ENT211:ENT211-W01-017","payload":{"prompt":"Which of the following is NOT one of the four elements in the simple formula for entrepreneurship?","options":["Opportunity","Autonomy","Risk","Innovation"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"The four elements are Opportunity, Innovation, Value Creation and Risk. Autonomy is one of the dimensions of entrepreneurship, not part of the formula, while A, D and C are all in it."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 18, $official_bank_source${"itemId":"9f46f8a5-8702-5d42-88b5-98d19fe4c1ff","questionId":"1ade77c1-c6b5-5598-b10d-820a687d41aa","sourceKey":"bank:ENT211:ENT211-W01-018","payload":{"prompt":"Paystack and Flutterwave revolutionizing digital payments in Nigeria are examples of which scope of entrepreneurship?","options":["Public sector entrepreneurship","Creative entrepreneurship","Technological entrepreneurship","Corporate entrepreneurship"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Technological entrepreneurship is about tech-driven solutions, and Paystack and Flutterwave changed digital payments with technology. Option D happens inside large existing organisations, A is innovation in government agencies, and B relies on talent and culture."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 19, $official_bank_source${"itemId":"a7a71610-88d0-5f0e-bdfd-0d71c0b124d9","questionId":"0e49393d-6448-53ea-87b5-be2cdf0470ea","sourceKey":"bank:ENT211:ENT211-W01-019","payload":{"prompt":"The scope of entrepreneurship described simply as 'tech-driven solutions' is","options":["Educational","International","Technological","Agricultural"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Technological entrepreneurship is described as tech-driven solutions. Option A is about teaching and learning, D applies innovative ideas to farming for profit, and B involves activities across national borders."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 20, $official_bank_source${"itemId":"573edf22-dbc9-55d0-ad10-8901d1bac8e5","questionId":"4d1dcb12-a298-5d1b-a2b2-6a191dde84d4","sourceKey":"bank:ENT211:ENT211-W01-020","payload":{"prompt":"Leap Africa tackling youth development challenges is an example of which scope of entrepreneurship?","options":["Social entrepreneurship","Corporate entrepreneurship","Green/Environmental entrepreneurship","International entrepreneurship"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Social entrepreneurship means innovative solutions to social problems, and youth development is a social challenge. Option B takes place inside large firms, D crosses national borders, and C focuses on protecting the environment."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 21, $official_bank_source${"itemId":"11d35853-2dd2-5ede-bf6e-e2c574cb9492","questionId":"d49c5001-dc23-5811-a8ec-87427fc42ae1","sourceKey":"bank:ENT211:ENT211-W01-021","payload":{"prompt":"Social entrepreneurship is best described as","options":["Tech-driven solutions such as digital payments","Innovating within public agencies to improve service delivery","Innovative activities inside a large organisation","Innovative solutions to solving social problems"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Social entrepreneurship provides innovative solutions to social problems. Option A describes technological entrepreneurship, C is corporate entrepreneurship, and B is public sector entrepreneurship."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 22, $official_bank_source${"itemId":"690c4845-5de7-5dc2-a996-fbb3c1d724bd","questionId":"4a677abd-e0e9-5474-9b0c-e4e5315c9b5e","sourceKey":"bank:ENT211:ENT211-W01-022","payload":{"prompt":"Leap Africa, an example of social entrepreneurship, is known for tackling which challenge?","options":["Renewable energy challenges","Funding challenges of farmers","Digital payment challenges","Youth development challenges"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Leap Africa tackles youth development challenges, which is why it illustrates social entrepreneurship. Option C matches Paystack and Flutterwave, B matches FarmCrowdy, and A matches the Sahara Energy Renewable Project."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 23, $official_bank_source${"itemId":"6d5fef44-31dc-5a5e-96b8-d49fbae19cce","questionId":"2cf95a09-0b94-5e45-afe0-a0daeae0cf85","sourceKey":"bank:ENT211:ENT211-W01-023","payload":{"prompt":"FarmCrowdy is an example of agricultural entrepreneurship because it","options":["Exports cement to African countries","Uses crowdfunding for farming","Runs a digital tax collection system","Provides online lessons to students"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"FarmCrowdy uses crowdfunding for farming, bringing an innovative funding idea into agriculture. Option A relates to Dangote Cement, D sounds like educational entrepreneurship, and C is a public sector example."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 24, $official_bank_source${"itemId":"505f9d4d-498a-5656-b96f-5c0f32d8171d","questionId":"2034f47f-645b-57d4-bfca-8963a2d32717","sourceKey":"bank:ENT211:ENT211-W01-024","payload":{"prompt":"Agricultural entrepreneurship is described as","options":["Creativity and cultural expressions to produce value","Innovative ideas to agriculture for profit","Activities across national borders","Solutions that protect the environment"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Agricultural entrepreneurship brings innovative ideas to agriculture for profit. Option D describes green entrepreneurship, C is international entrepreneurship, and A is creative entrepreneurship."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 25, $official_bank_source${"itemId":"a7e099dc-a245-5332-8233-bdaf01cd2971","questionId":"e564a860-4542-5ad8-8d95-1d1cb2f74693","sourceKey":"bank:ENT211:ENT211-W01-025","payload":{"prompt":"uLesson is given as an example of which scope of entrepreneurship?","options":["Public sector","Educational","Agricultural","Social"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"uLesson is the example of educational entrepreneurship, which is innovation in teaching, learning and educational services. Option C is illustrated by FarmCrowdy, D by Leap Africa, and A by online passport portals and digital tax systems."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 26, $official_bank_source${"itemId":"4a407b74-4192-552c-9916-a04252091cd9","questionId":"6f73e7e0-eeef-570c-80fe-a9026648d019","sourceKey":"bank:ENT211:ENT211-W01-026","payload":{"prompt":"Educational entrepreneurship involves","options":["Innovative activities inside large organisations","Innovation in teaching, learning and educational services","Innovative solutions to youth development problems","Tech-driven solutions to digital payments"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Educational entrepreneurship is innovation in teaching, learning and educational services. Option C describes social entrepreneurship such as Leap Africa, D is technological entrepreneurship, and A is corporate entrepreneurship."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 27, $official_bank_source${"itemId":"73462b15-bd97-52dd-9a5f-040bceed11ad","questionId":"4faeaa9d-b3b4-51d1-88dc-c6495b3dd34d","sourceKey":"bank:ENT211:ENT211-W01-027","payload":{"prompt":"Which of the following is given as an example of agricultural entrepreneurship?","options":["FarmCrowdy","Paystack","Leap Africa","uLesson"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"FarmCrowdy uses crowdfunding for farming, making it the agricultural example. Option D is educational, C is social, and B is technological entrepreneurship."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 28, $official_bank_source${"itemId":"707c1dbc-4b4e-569c-a43b-93dc84114728","questionId":"2835de80-36a9-56c3-a7ca-9a07e7f6e32d","sourceKey":"bank:ENT211:ENT211-W01-028","payload":{"prompt":"Nollywood films, music and fashion brands are examples of which scope of entrepreneurship?","options":["Creative entrepreneurship","Public sector entrepreneurship","Corporate entrepreneurship","Technological entrepreneurship"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Creative entrepreneurship uses creativity, talent and cultural expressions to produce value, which is exactly what Nollywood, music and fashion brands do. Option C happens inside large organisations, D is tech-driven, and B is innovation within government agencies."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 29, $official_bank_source${"itemId":"c2771603-b4b0-572d-9f4f-1e632601b664","questionId":"8b301ba3-1768-5a69-b893-eb328cc13c13","sourceKey":"bank:ENT211:ENT211-W01-029","payload":{"prompt":"Creative entrepreneurship is described as using","options":["Exporting, expansion and foreign partnerships","Renewable energy to promote sustainability","Creativity, talent and cultural expressions to produce value","Crowdfunding and digital tools to support farmers"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Creative entrepreneurship turns creativity, talent and cultural expressions into value. Option D describes FarmCrowdy in agricultural entrepreneurship, A is international entrepreneurship, and B fits green entrepreneurship."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 30, $official_bank_source${"itemId":"0851b956-4635-5975-a5b0-504799d2cec7","questionId":"4f32d8b4-1afb-5a44-b4fb-85ecfdb66382","sourceKey":"bank:ENT211:ENT211-W01-030","payload":{"prompt":"MTN MoMo and Gmail at Google are examples of which scope of entrepreneurship?","options":["Creative entrepreneurship","International entrepreneurship","Social entrepreneurship","Corporate entrepreneurship"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Corporate entrepreneurship is innovation carried out inside large organisations to create new products, services or processes, as MTN did with MoMo and Google did with Gmail. Option B is about crossing borders, C solves social problems, and A relies on talent and culture."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 31, $official_bank_source${"itemId":"f2794ba3-0024-5197-a565-a73aa75b42ec","questionId":"35e3fb7e-1185-56f4-9444-fc3971396bbb","sourceKey":"bank:ENT211:ENT211-W01-031","payload":{"prompt":"Innovative activities carried out inside a large organisation to create new products, services or processes are known as","options":["International entrepreneurship","Social entrepreneurship","Public sector entrepreneurship","Corporate entrepreneurship"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"This is corporate entrepreneurship: innovation that happens inside a large existing organisation. Option C is innovation within government agencies, A involves activities across national borders, and B solves social problems."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 32, $official_bank_source${"itemId":"dd77a333-5d06-55e7-80fe-db39bf938280","questionId":"7280793a-b666-59ea-99fb-0d9ba3789218","sourceKey":"bank:ENT211:ENT211-W01-032","payload":{"prompt":"Entrepreneurial activities across national borders, such as exporting, expansion and foreign partnerships, are called","options":["Green/Environmental entrepreneurship","Public sector entrepreneurship","International entrepreneurship","Corporate entrepreneurship"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"International entrepreneurship covers activities across national borders, including exporting, expansion and foreign partnerships. Option D is innovation inside a large organisation, B is innovation in government agencies, and A protects the environment."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 33, $official_bank_source${"itemId":"208681e5-bced-5f7d-a4bc-13478946699a","questionId":"9369f451-0b4e-521d-92a0-e44ad5aeff6d","sourceKey":"bank:ENT211:ENT211-W01-033","payload":{"prompt":"Dangote Cement operating in 10 African countries illustrates which scope of entrepreneurship?","options":["Corporate entrepreneurship","Social entrepreneurship","International entrepreneurship","Public sector entrepreneurship"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"International entrepreneurship involves activities across national borders, and Dangote Cement operating in 10 African countries is the example. Option A is about innovation inside a large firm, like MTN MoMo, D happens in government agencies, and B solves social problems."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 34, $official_bank_source${"itemId":"f6191f3b-bb04-5a4d-9975-0715acbb2bd8","questionId":"92c9b2c4-a675-5b88-8d1b-0dc0b9c9742c","sourceKey":"bank:ENT211:ENT211-W01-034","payload":{"prompt":"As an example of international entrepreneurship, Dangote Cement is described as operating in how many African countries?","options":["5","20","15","10"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Dangote Cement is said to operate in 10 African countries, showing entrepreneurship across national borders. Options A, C and B are not the number given in the example."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 35, $official_bank_source${"itemId":"30176684-04c1-533b-8169-d95ee24360dd","questionId":"c95b54d8-cc7f-588c-9381-8a7dbd804e26","sourceKey":"bank:ENT211:ENT211-W01-035","payload":{"prompt":"Digital tax collection systems and online passport application portals are examples of which scope of entrepreneurship?","options":["Corporate entrepreneurship","Creative entrepreneurship","Public sector (government) entrepreneurship","Social entrepreneurship"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Public sector entrepreneurship means innovating within government agencies to improve service delivery, and digital tax collection and online passport portals are government services. Option B, creative entrepreneurship, uses creativity, talent and culture to produce value, as in Nollywood, music and fashion brands. Option A happens inside large private organisations, and D focuses on solving social problems."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 36, $official_bank_source${"itemId":"6e546aa5-f389-5a67-884e-a1932891ab4a","questionId":"df436cf8-afab-529b-ae38-2bc04647dce1","sourceKey":"bank:ENT211:ENT211-W01-036","payload":{"prompt":"Public sector (government) entrepreneurship refers to","options":["Innovative activities inside large private organisations","Innovating within public agencies to improve service delivery","Innovative solutions to solving social problems","Activities across national borders such as exporting"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Public sector entrepreneurship is about innovating within public agencies to improve service delivery. Option D describes international entrepreneurship, C is social entrepreneurship, and A is corporate entrepreneurship."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 37, $official_bank_source${"itemId":"5c68e68b-65f4-5743-8946-5de3ac83a034","questionId":"9e729a1e-ff9f-552e-9b67-020d3f541f73","sourceKey":"bank:ENT211:ENT211-W01-037","payload":{"prompt":"The Sahara Energy Renewable Project is an example of which scope of entrepreneurship?","options":["Green/Environmental entrepreneurship","International entrepreneurship","Agricultural entrepreneurship","Creative entrepreneurship"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Green or environmental entrepreneurship develops solutions that protect the environment or promote sustainability, and a renewable energy project does that. Option B is about operating across borders, C applies innovation to farming, and D uses talent and culture."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 38, $official_bank_source${"itemId":"7aad42a9-6c12-500a-aac6-67ed5b053297","questionId":"640b364d-8766-566b-aca6-3f474738c5a3","sourceKey":"bank:ENT211:ENT211-W01-038","payload":{"prompt":"Developing solutions that protect the environment or promote sustainability is known as","options":["Green/Environmental entrepreneurship","Agricultural entrepreneurship","Public sector entrepreneurship","Social entrepreneurship"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"This describes green or environmental entrepreneurship. Option D solves social problems, B brings innovative ideas to agriculture for profit, and C improves service delivery in government agencies."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 39, $official_bank_source${"itemId":"9ff18d9b-bf27-59c0-ac75-1c737c63e86f","questionId":"d06c94dd-eff3-5e18-867a-69e99fa910c2","sourceKey":"bank:ENT211:ENT211-W01-039","payload":{"prompt":"Which of the following is an example of green/environmental entrepreneurship?","options":["uLesson","Sahara Energy Renewable Project","Nollywood films","MTN MoMo"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"The Sahara Energy Renewable Project is the green entrepreneurship example because it promotes sustainability. Option D is corporate entrepreneurship, A is educational, and C is creative entrepreneurship."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 40, $official_bank_source${"itemId":"550033c0-fea3-569a-a96b-4e378518d979","questionId":"06a7a9c4-1bff-5571-b02f-0bfb18347be5","sourceKey":"bank:ENT211:ENT211-W01-040","payload":{"prompt":"Which of the following is an example of public sector (government) entrepreneurship?","options":["Leap Africa","FarmCrowdy","Online passport application portals","Gmail at Google"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Online passport application portals are innovation within government agencies to improve service delivery. Option D is corporate entrepreneurship, A is social, and B is agricultural."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 41, $official_bank_source${"itemId":"a8e6e590-ebbb-5eb1-82ad-0a4c0c8c28a1","questionId":"3a78a11c-4f00-5c5c-b5ad-0a195b9036ac","sourceKey":"bank:ENT211:ENT211-W01-041","payload":{"prompt":"Which of the following is an example of corporate entrepreneurship?","options":["Gmail at Google","Sahara Energy Renewable Project","Leap Africa","Digital tax collection systems"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Gmail was created inside Google, a large organisation, which makes it corporate entrepreneurship. Option C is social, B is green, and D is public sector entrepreneurship."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 42, $official_bank_source${"itemId":"bdc14912-f649-584f-887a-540ef72a38ac","questionId":"7fc468c4-ffee-51f1-9c41-1912109a7aaf","sourceKey":"bank:ENT211:ENT211-W01-042","payload":{"prompt":"Which of the following is NOT one of the scopes of entrepreneurship?","options":["Proactiveness","Technological","Creative","Green/Environmental"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Proactiveness is a dimension of entrepreneurship, describing how entrepreneurs act ahead of competitors; it is not a scope. Options B, C and D are all scopes of entrepreneurship."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 43, $official_bank_source${"itemId":"1484fa16-8057-544e-b68d-27f909f0dc91","questionId":"64b7f44a-49b6-5cdf-8a17-29e39d43d777","sourceKey":"bank:ENT211:ENT211-W01-043","payload":{"prompt":"Which of the following is one of the scopes of entrepreneurship?","options":["Vision","Resourceful","Agricultural","Autonomy"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Agricultural entrepreneurship, bringing innovative ideas to farming for profit, is one of the scopes. Option D is a dimension of entrepreneurship, while A and B are characteristics of an entrepreneur."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 44, $official_bank_source${"itemId":"fe51571e-d137-5916-8da4-0e9d0c4dd03d","questionId":"1d0624c9-3a9b-5e35-91f9-523e1694e589","sourceKey":"bank:ENT211:ENT211-W01-044","payload":{"prompt":"Which of the following is NOT a scope of entrepreneurship?","options":["International","Risk Taker","Educational","Public Sector (Government)"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Risk Taker is a characteristic of an entrepreneur, not a scope of entrepreneurship. Options A, D and C are all scopes."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 45, $official_bank_source${"itemId":"c39f0c6f-9c1e-5c99-a652-7295184f34a2","questionId":"d77b7207-6e4a-5f9a-abf6-b8368552b82a","sourceKey":"bank:ENT211:ENT211-W01-045","payload":{"prompt":"A state ministry in Nigeria introduces an online portal where residents can renew their driver's licences without visiting an office, improving service delivery. This is an example of","options":["Corporate entrepreneurship","Creative entrepreneurship","Public sector (government) entrepreneurship","Social entrepreneurship"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Innovating within a public agency to improve service delivery is public sector entrepreneurship, just like online passport portals. Option A happens inside large private firms, B uses talent and culture, and D tackles social problems through ventures like Leap Africa."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 46, $official_bank_source${"itemId":"6aa4dfea-4941-5f0d-bed5-763ba41f7656","questionId":"1f470572-eb3c-5384-8bea-f3ad114b7f13","sourceKey":"bank:ENT211:ENT211-W01-046","payload":{"prompt":"A team of staff inside a large Nigerian bank develops a brand-new mobile savings product for the bank's customers. This is best described as","options":["Public sector entrepreneurship","Corporate entrepreneurship","Social entrepreneurship","International entrepreneurship"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Innovation carried out inside a large organisation to create a new product is corporate entrepreneurship, like MTN MoMo or Gmail at Google. Option A would need a government agency, D would need activity across borders, and C focuses on social problems."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 47, $official_bank_source${"itemId":"19f4f8b1-d0ca-5f35-a919-ae407306d57d","questionId":"22c93acc-130f-52ac-94e5-29a24650d018","sourceKey":"bank:ENT211:ENT211-W01-047","payload":{"prompt":"A shoe maker in Aba begins exporting shoes to Ghana and forms a partnership with a distributor in Senegal. Which scope of entrepreneurship does this illustrate?","options":["International entrepreneurship","Creative entrepreneurship","Corporate entrepreneurship","Agricultural entrepreneurship"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Exporting and forming foreign partnerships are activities across national borders, which is international entrepreneurship. Option B centres on talent and culture, C happens inside a large organisation, and D concerns farming."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 48, $official_bank_source${"itemId":"9e80012b-1c77-541e-bdce-fece8ada2a1a","questionId":"ef7beb3c-f562-501b-bb65-089f2e583030","sourceKey":"bank:ENT211:ENT211-W01-048","payload":{"prompt":"A young Lagos musician builds a profitable brand from her songs and performances that celebrate Yoruba culture. Which scope of entrepreneurship is this?","options":["Green/Environmental entrepreneurship","Creative entrepreneurship","Corporate entrepreneurship","Public sector entrepreneurship"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Using talent and cultural expression to produce value is creative entrepreneurship, like Nollywood and music brands. Option C needs a large existing organisation, D needs a government agency, and A is about protecting the environment."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 49, $official_bank_source${"itemId":"6b5c2293-17d5-5942-bcf7-c632e166ad0a","questionId":"261652be-a081-5255-82ac-4c2a5cdbc23e","sourceKey":"bank:ENT211:ENT211-W01-049","payload":{"prompt":"An entrepreneur in Port Harcourt sets up a business that installs solar power systems to cut pollution from diesel generators and promote sustainability. This fits which scope of entrepreneurship?","options":["Green/Environmental entrepreneurship","Corporate entrepreneurship","International entrepreneurship","Creative entrepreneurship"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"A business that protects the environment and promotes sustainability is green or environmental entrepreneurship, like the Sahara Energy Renewable Project. Option D uses talent and culture, B takes place inside a large organisation, and C involves activities across borders."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 50, $official_bank_source${"itemId":"0ed30e95-d802-5a7d-9420-538bc67e9dd9","questionId":"04ae5f20-968a-5792-be8d-2c01532f05d0","sourceKey":"bank:ENT211:ENT211-W01-050","payload":{"prompt":"Which of the following is NOT listed among the characteristics of an entrepreneur?","options":["Self Confidence","Passion","Autonomy","Vision"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Autonomy is one of the dimensions of entrepreneurship, not one of the listed characteristics of an entrepreneur. Options D, B and A are all characteristics."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 51, $official_bank_source${"itemId":"07e7aa9f-bcd3-5cd7-9194-745655d799f1","questionId":"ef116e67-31af-5c4b-b100-1e7b105028d5","sourceKey":"bank:ENT211:ENT211-W01-051","payload":{"prompt":"Which of the following is one of the characteristics of an entrepreneur?","options":["Ability to Network","Value Creation","Proactiveness","Opportunity Recognition"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Ability to Network is one of the eight characteristics of an entrepreneur. Options B, D and C are dimensions of entrepreneurship rather than items on the list of characteristics."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 52, $official_bank_source${"itemId":"557d85bb-5940-5f60-beac-4fdf4d68a448","questionId":"e5051c32-d220-515f-aa92-ba112dab8e58","sourceKey":"bank:ENT211:ENT211-W01-052","payload":{"prompt":"Which of the following is NOT one of the characteristics of an entrepreneur?","options":["Risk Taker","Creativity","Resourceful","Technological"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Technological is a scope of entrepreneurship, not a characteristic of the entrepreneur. Options B, A and C are all on the list of characteristics."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 53, $official_bank_source${"itemId":"1e5c0d43-2363-597b-a1f0-6fdad764d4bc","questionId":"da34b8a9-b426-5be1-899d-8cc6b1b6158d","sourceKey":"bank:ENT211:ENT211-W01-053","payload":{"prompt":"Among the characteristics of an entrepreneur, 'Never Give-up' is also referred to as","options":["Passion","Vision","Self Confidence","Grit"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Never Give-up is shown as Grit, meaning the determination to keep going despite setbacks. Options A, B and C are separate characteristics on the same list."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 54, $official_bank_source${"itemId":"ff0f7bdb-9990-51e0-8bd5-7bd50fcf2ef2","questionId":"17909474-4d2b-50c5-8941-b5a5616ad2e6","sourceKey":"bank:ENT211:ENT211-W01-054","payload":{"prompt":"How many characteristics of an entrepreneur are listed (Vision, Creativity, Passion and so on)?","options":["Seven","Eight","Nine","Five"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"There are eight characteristics: Vision, Creativity, Passion, Ability to Network, Self Confidence, Risk Taker, Resourceful and Never Give-up (Grit). Option A is the number of dimensions of entrepreneurship, which students often mix up with the characteristics."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 55, $official_bank_source${"itemId":"b14e457b-03b5-53be-952b-c940f74de72c","questionId":"81cf2d76-f9d7-5493-9d5c-f6096c67da4f","sourceKey":"bank:ENT211:ENT211-W01-055","payload":{"prompt":"Kemi's catering business failed twice, but each time she learned from her mistakes and started again until the third attempt succeeded. Which characteristic of an entrepreneur does she show most clearly?","options":["Never Give-up (Grit)","Creativity","Ability to Network","Vision"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Refusing to quit after repeated failure is Never Give-up, also called Grit. Option C is about building connections, D is about seeing the future clearly, and B is about new ideas, none of which is the main point of her story."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 56, $official_bank_source${"itemId":"2c7ccd1a-d0bc-5eba-bde7-9514c2400c3a","questionId":"ce611f79-00f7-55a0-aef7-768b03c90e68","sourceKey":"bank:ENT211:ENT211-W01-056","payload":{"prompt":"Chidi attends business events, keeps in touch with mentors and builds relationships that later bring him partners and customers. Which characteristic of an entrepreneur is he showing?","options":["Risk Taker","Passion","Ability to Network","Resourceful"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Building and using relationships with mentors, partners and customers is the Ability to Network. Option D is about making the most of limited resources, B is deep love for the work, and A is about taking chances, which are not what the scenario stresses."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 57, $official_bank_source${"itemId":"96bb71c2-e79d-581b-b983-2e1fd4871eac","questionId":"36007395-6280-59dd-924d-6fb26373144a","sourceKey":"bank:ENT211:ENT211-W01-057","payload":{"prompt":"With very little money, Aisha starts a snack business using her mother's kitchen, second-hand utensils and free social media advertising. Which characteristic of an entrepreneur does this best show?","options":["Resourceful","Self Confidence","Vision","Ability to Network"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Making the best use of the little she has is being Resourceful. Option C is about seeing the future, B is belief in oneself, and D is about relationships, none of which is the focus here."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 58, $official_bank_source${"itemId":"e656fb6a-f29b-562a-bf29-bb980a4d614a","questionId":"4d9fe88c-bc96-566b-bd4d-6e8ae1df4cda","sourceKey":"bank:ENT211:ENT211-W01-058","payload":{"prompt":"The dimensions of entrepreneurship describe the","options":["Legal forms a business can take when it is registered","Behaviours, processes and characteristics that drive entrepreneurial activity","Sources of funds available to a new business","Sectors of the economy in which businesses operate"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"The dimensions describe the behaviours, processes and characteristics that drive entrepreneurial activity. Option D is closer to the idea of scope, and A and C are not what the dimensions describe."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 59, $official_bank_source${"itemId":"bd8137af-a0cd-5456-b8e9-dbbbd9c965ce","questionId":"f95783b9-100c-5e72-b13a-d090dce62743","sourceKey":"bank:ENT211:ENT211-W01-059","payload":{"prompt":"How many dimensions of entrepreneurship are listed (Innovativeness, Proactiveness, Risk taking and so on)?","options":["Eight","Nine","Four","Seven"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"There are seven dimensions: Innovativeness, Proactiveness, Risk taking, Value Creation, Opportunity Recognition, Resource Mobilisation and Autonomy. Option A is the number of characteristics of an entrepreneur and B is the number of scopes, which is why they can be confusing."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 60, $official_bank_source${"itemId":"b0ee978f-d4ba-58d9-bc8d-8eb629cc0678","questionId":"7755dc69-0a07-58ea-b8d9-f534a43320f5","sourceKey":"bank:ENT211:ENT211-W01-060","payload":{"prompt":"Creating something new or improving existing products, services or processes is the dimension of entrepreneurship known as","options":["Resource Mobilisation","Innovativeness","Proactiveness","Value Creation"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Innovativeness means creating something new or improving what already exists. Option C is acting ahead of competitors, D is creating economic, social or environmental value, and A is gathering and managing resources."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 61, $official_bank_source${"itemId":"b3855ff4-8b71-5384-b0e8-18557c648272","questionId":"2a37501b-6c11-5d0b-8ba9-449220dc4397","sourceKey":"bank:ENT211:ENT211-W01-061","payload":{"prompt":"Flutterwave creating an innovative payment infrastructure is used to illustrate which dimension of entrepreneurship?","options":["Autonomy","Risk taking","Resource Mobilisation","Innovativeness"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Building a new payment infrastructure is creating something new, which is Innovativeness. Option A is about independence in decision-making, B is illustrated by Dangote investing despite uncertainty, and C is illustrated by Tony Elumelu and UBA."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 62, $official_bank_source${"itemId":"0ff2a2a3-cb2e-54ee-b96e-508ee667868b","questionId":"70cc634c-8dde-58ef-a5b7-564ff1959af2","sourceKey":"bank:ENT211:ENT211-W01-062","payload":{"prompt":"When entrepreneurs anticipate future trends, act ahead of competitors and seize opportunities early, they are displaying","options":["Autonomy","Innovativeness","Risk taking","Proactiveness"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Anticipating trends and acting before competitors is Proactiveness. Option A is independence in decisions, B is creating something new or improving it, and C is taking calculated risks in uncertain environments."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 63, $official_bank_source${"itemId":"90c860c6-d35c-5fc9-a67c-0b1b7d60dae8","questionId":"8e242fda-ccd0-5830-91c8-25bfead9fa8b","sourceKey":"bank:ENT211:ENT211-W01-063","payload":{"prompt":"Sim Shagaya pioneering Konga online shopping is an example of which dimension of entrepreneurship?","options":["Proactiveness","Resource Mobilisation","Autonomy","Value Creation"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"By pioneering e-commerce with Konga, Sim Shagaya acted ahead of competitors and seized the opportunity early, which is Proactiveness. Option C is about independent decision-making, B is illustrated by Tony Elumelu, and D is illustrated by FarmCrowdy."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 64, $official_bank_source${"itemId":"e8481438-a9d2-581d-b218-99f366c10bb0","questionId":"0b85dd80-4716-544b-879a-672afa364e69","sourceKey":"bank:ENT211:ENT211-W01-064","payload":{"prompt":"Which company did Sim Shagaya pioneer as an example of proactiveness?","options":["Paystack","Konga","uLesson","FarmCrowdy"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Sim Shagaya pioneered Konga, an e-commerce online shopping platform. Option A is a technological entrepreneurship example, C is educational, and D is agricultural."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 65, $official_bank_source${"itemId":"0fcb8a59-5d39-5a7a-aed9-c09ccdfc6ef8","questionId":"07fab8bf-b8bd-5963-a0e5-2174d291a8fa","sourceKey":"bank:ENT211:ENT211-W01-065","payload":{"prompt":"As a dimension of entrepreneurship, risk taking means that entrepreneurs","options":["Take any risk without thinking in stable environments","Pass every risk on to their customers","Avoid all risks until success is guaranteed","Take calculated risks in uncertain environments"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Entrepreneurs take calculated risks in uncertain environments, meaning they weigh the risks before acting. Option A describes reckless gambling, C would mean never starting at all, and B is not what risk taking means."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 66, $official_bank_source${"itemId":"36dea538-d882-5bee-b324-7ecd8eb7f567","questionId":"4436e5da-37d3-5ea7-a710-12f94bd4f2d5","sourceKey":"bank:ENT211:ENT211-W01-066","payload":{"prompt":"Aliko Dangote investing in local industries despite import dominance and market uncertainty is the example given for which dimension of entrepreneurship?","options":["Autonomy","Risk taking","Creativity","Innovativeness"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Risk taking means entrepreneurs take calculated risks in uncertain environments, and investing despite import dominance and market uncertainty is exactly that. Option C, creativity, is listed as a characteristic of an entrepreneur rather than one of the dimensions. Option A is about independence in decision-making, and D is about creating something new or improving what exists."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 67, $official_bank_source${"itemId":"51610e8a-bce3-5237-a6fb-833fb538083f","questionId":"555b3834-09a8-58f9-be1d-4d1ce11bfa99","sourceKey":"bank:ENT211:ENT211-W01-067","payload":{"prompt":"As a dimension of entrepreneurship, value creation can be","options":["Economic, social or environmental","Personal, private or secret","Only economic, measured by profit","Political, religious or military"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Value creation covers economic, social or environmental value, so it is broader than profit alone. Option C is too narrow, and D and B are not the types of value named."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 68, $official_bank_source${"itemId":"08bddb96-f7ac-5e97-b753-2847188bd11e","questionId":"e9e6792e-f0ca-5606-81d4-acb2ffc5b597","sourceKey":"bank:ENT211:ENT211-W01-068","payload":{"prompt":"FarmCrowdy connecting farmers with digital funding and agricultural support is used to illustrate which dimension of entrepreneurship?","options":["Autonomy","Risk taking","Proactiveness","Value Creation"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"By linking farmers to funding and support, FarmCrowdy created value, so it illustrates Value Creation. Option A is about independence, C is illustrated by Sim Shagaya and Konga, and B is illustrated by Dangote."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 69, $official_bank_source${"itemId":"ebf8ac53-ecd1-5f39-ab17-5d1802165b8b","questionId":"91e0529e-5662-5c79-ae8f-0c85ca10ee7d","sourceKey":"bank:ENT211:ENT211-W01-069","payload":{"prompt":"The dimension of entrepreneurship that begins with identifying unmet needs, market gaps or solutions to problems is","options":["Resource Mobilisation","Autonomy","Opportunity Recognition","Risk taking"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Opportunity Recognition is where entrepreneurship begins: spotting unmet needs, market gaps or solutions to problems. Option A comes after, when resources are gathered, B is independence in decision-making, and D is taking calculated risks."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 70, $official_bank_source${"itemId":"58e89b79-a50c-5388-a811-74337a0a4e30","questionId":"e5a248ac-bab6-52e5-aeeb-867976ff833f","sourceKey":"bank:ENT211:ENT211-W01-070","payload":{"prompt":"Entrepreneurs knowing how to gather and manage the resources needed to bring ideas to life describes which dimension?","options":["Innovativeness","Value Creation","Resource Mobilisation","Opportunity Recognition"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Gathering and managing the resources needed to bring ideas to life is Resource Mobilisation. Option D is spotting the need in the first place, A is creating something new, and B is the value that results."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 71, $official_bank_source${"itemId":"462c43ff-5484-5100-bfd6-fa07247c0ca1","questionId":"78a5bc2b-8380-5223-9971-2d27254b76e8","sourceKey":"bank:ENT211:ENT211-W01-071","payload":{"prompt":"Tony Elumelu turning UBA into a global bank is an example of which dimension of entrepreneurship?","options":["Autonomy","Resource Mobilisation","Innovativeness","Proactiveness"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Tony Elumelu is the example of Resource Mobilisation, the ability to gather and manage resources to bring ideas to life. Option A is about independence in decision-making, D is illustrated by Sim Shagaya and Konga, and C by Flutterwave."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 72, $official_bank_source${"itemId":"41c98d36-e95d-5ab3-a27f-b67164945c30","questionId":"59f49882-6d3b-5d37-b057-0e718dc5a38e","sourceKey":"bank:ENT211:ENT211-W01-072","payload":{"prompt":"Independence in decision-making and control over one's goals and actions is the dimension of entrepreneurship called","options":["Resource Mobilisation","Opportunity Recognition","Proactiveness","Autonomy"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Autonomy means independence in decision-making and control over one's goals and actions. Option C is acting ahead of competitors, A is gathering and managing resources, and B is identifying unmet needs."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 73, $official_bank_source${"itemId":"d7ebc4f8-c02d-56a6-a1c9-947b05383642","questionId":"931f2803-c2b2-5b1f-809c-3b4198bf83ea","sourceKey":"bank:ENT211:ENT211-W01-073","payload":{"prompt":"Which of the following is given as the example of autonomy as a dimension of entrepreneurship?","options":["Sim Shagaya pioneering Konga","Tony Elumelu turning UBA into a global bank","Startup founders starting enterprises","FarmCrowdy connecting farmers with funding"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Startup founders starting their own enterprises show autonomy, because they make their own decisions and control their goals. Option B illustrates Resource Mobilisation, A illustrates Proactiveness, and D illustrates Value Creation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 74, $official_bank_source${"itemId":"ab830445-79f1-5f81-bd4b-c748ded985a7","questionId":"42437c6c-d13b-5177-9081-fd33c5ec1fd1","sourceKey":"bank:ENT211:ENT211-W01-074","payload":{"prompt":"Which of the following is NOT one of the dimensions of entrepreneurship?","options":["Passion","Autonomy","Innovativeness","Proactiveness"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Passion is a characteristic of an entrepreneur, not a dimension of entrepreneurship. Options C, D and B are all dimensions."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 75, $official_bank_source${"itemId":"73d77800-4c49-514d-8c31-4fd67364a2b3","questionId":"f7e766d4-f1c9-57ad-a0ea-7ffc85e3b460","sourceKey":"bank:ENT211:ENT211-W01-075","payload":{"prompt":"Which of the following is one of the dimensions of entrepreneurship?","options":["Creativity","Never Give-up (Grit)","Opportunity Recognition","Vision"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Opportunity Recognition is one of the seven dimensions of entrepreneurship. Options D, A and B are characteristics of an entrepreneur rather than dimensions."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 76, $official_bank_source${"itemId":"a28c0646-3ac5-5295-a826-0f333c390c8f","questionId":"f35b7049-0ac4-51a7-a91f-f0829931da39","sourceKey":"bank:ENT211:ENT211-W01-076","payload":{"prompt":"Which of the following is NOT a dimension of entrepreneurship?","options":["Social Entrepreneurship","Value Creation","Resource Mobilisation","Risk taking"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Social Entrepreneurship is a scope of entrepreneurship, not one of its dimensions. Options D, B and C are all dimensions."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 77, $official_bank_source${"itemId":"77bd4fee-d4e1-57d7-9717-e5a52b788e76","questionId":"ee90d27b-840d-5cc4-91aa-160dfaaa0bca","sourceKey":"bank:ENT211:ENT211-W01-077","payload":{"prompt":"A Nigerian startup studies changing customer habits, predicts that cashless payments at roadside markets will soon be common, and launches a solution before any competitor. Which dimension of entrepreneurship is this?","options":["Resource Mobilisation","Proactiveness","Autonomy","Value Creation"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Anticipating a future trend and acting ahead of competitors is Proactiveness. Option C is independence in decision-making, A is gathering resources, and D is the value created, but the key feature here is moving early."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 78, $official_bank_source${"itemId":"e8a68ff0-0f0a-53d3-8b28-7b3b676046c2","questionId":"d6d01214-3fd7-5ee3-b564-768af01aded9","sourceKey":"bank:ENT211:ENT211-W01-078","payload":{"prompt":"Bola resigns from a salaried job to start her own firm because she wants to make her own decisions and control her goals. Which dimension of entrepreneurship does this reflect?","options":["Innovativeness","Value Creation","Autonomy","Proactiveness"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Wanting independence in decision-making and control over one's goals is Autonomy. Option D is about acting ahead of competitors, A is about creating something new, and B is about the value delivered, none of which is her main motive."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 79, $official_bank_source${"itemId":"961a6213-531c-5164-9928-9810471d9d37","questionId":"13a31f13-e086-5397-9a03-d9b5f80141a3","sourceKey":"bank:ENT211:ENT211-W01-079","payload":{"prompt":"A UNILAG student notices that many students struggle to find affordable hostel accommodation near campus and sees this unmet need as a business gap. Which dimension of entrepreneurship is shown?","options":["Opportunity Recognition","Resource Mobilisation","Autonomy","Risk taking"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"Spotting an unmet need or market gap is Opportunity Recognition, the starting point of entrepreneurship. Option B would come later when the student gathers resources, C is about independence, and D is about taking calculated risks."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 80, $official_bank_source${"itemId":"001d1a15-810b-581e-a3fd-4a7cfb67ea80","questionId":"fa98b4bc-6075-58bf-89a3-29bd97cce818","sourceKey":"bank:ENT211:ENT211-W01-080","payload":{"prompt":"In the reflection case, what opportunity did Tunde recognise in his neighbourhood?","options":["People could not get cheap cement for building","People struggled to find clean, affordable drinking water","Students lacked access to online lessons","Farmers could not get funding for their farms"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Tunde noticed that people often struggled to find clean, affordable drinking water. Option A recalls Dangote's cement, C sounds like uLesson, and D sounds like FarmCrowdy, so none fits Tunde's story."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 81, $official_bank_source${"itemId":"e58ab30a-f1c9-5e9b-8bc0-f3ef5ced1b6e","questionId":"82d4c297-8f2b-57ac-81e1-44c106c6b648","sourceKey":"bank:ENT211:ENT211-W01-081","payload":{"prompt":"What kind of business did Tunde start in the reflection case?","options":["Selling water purification equipment to factories","Producing purified bottled water","Trading sugar, rice and cement","Running a crowdfunding platform for farmers"],"correctOption":1,"section":"Week 1: Concept of Entrepreneurship","explanation":"Tunde started a small business producing purified bottled water. Option C is how Dangote began, D describes FarmCrowdy, and A is not what Tunde did; he bought equipment for his own production."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 82, $official_bank_source${"itemId":"b8b35128-4fac-55da-91c0-eb4fc3b99fa6","questionId":"e96995c9-4b84-5d3b-9f14-5c86ede51834","sourceKey":"bank:ENT211:ENT211-W01-082","payload":{"prompt":"Why were the water options people relied on in Tunde's neighbourhood a problem?","options":["Bottled water was free but hard to find","Local supplies were safe but far away","There was too much water and no storage","Bottled water was expensive and local supplies were unsafe"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"People relied on bottled water, which was expensive, or on local water supplies that were unsafe. Options A, B and C each change the facts of the case."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 83, $official_bank_source${"itemId":"54199f59-1c89-5ae1-bfde-1e1eff81c056","questionId":"21f78922-a99c-5c01-95e4-e19c720a7cb6","sourceKey":"bank:ENT211:ENT211-W01-083","payload":{"prompt":"In the reflection case, which of the following was NOT one of the resources Tunde mobilised to start his business?","options":["Equipment that he bought","Staff that he hired","A loan from his uncle","A small rented space"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Tunde rented a small space, bought equipment and hired staff. A loan from an uncle is part of Aliko Dangote's story, not Tunde's, so C is the one that does not belong."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 84, $official_bank_source${"itemId":"36afb7ab-cb44-582a-91f4-440295c8e82e","questionId":"f8b1d968-3711-553a-9e70-786b1feaa52a","sourceKey":"bank:ENT211:ENT211-W01-084","payload":{"prompt":"Tunde renting a small space, buying equipment and hiring staff best illustrates which dimension of entrepreneurship?","options":["Proactiveness","Innovativeness","Autonomy","Resource Mobilisation"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Gathering a space, equipment and staff to bring his idea to life is Resource Mobilisation. Option C is about independence in decisions, A is acting ahead of competitors, and B is creating something new, none of which these actions mainly show."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 85, $official_bank_source${"itemId":"0bf07518-30ad-58de-b523-62cb307af030","questionId":"a9a52a99-7fe1-5e2b-b5ad-275975c9e95e","sourceKey":"bank:ENT211:ENT211-W01-085","payload":{"prompt":"Tunde noticing that his neighbours struggled to find clean, affordable drinking water is an example of which dimension of entrepreneurship?","options":["Risk taking","Autonomy","Opportunity Recognition","Resource Mobilisation"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Spotting an unmet need, here clean and affordable water, is Opportunity Recognition. Option D came next when he rented space and bought equipment, B is about independence, and A is about taking calculated risks."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 86, $official_bank_source${"itemId":"7337b6ea-bec3-5e0b-9912-b5117c78d5e0","questionId":"e4c2ba65-90b6-5371-ae19-2ca2b8294786","sourceKey":"bank:ENT211:ENT211-W01-086","payload":{"prompt":"To whom did Tunde market his purified bottled water?","options":["Foreign buyers and exporters","Large factories and hotels","Government agencies and schools","Local shops and households"],"correctOption":3,"section":"Week 1: Concept of Entrepreneurship","explanation":"Tunde marketed his product to local shops and households in his area. Options C, A and B are not the customers named in the case."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 87, $official_bank_source${"itemId":"a925bfb1-8adc-5171-bc23-724c8e12f9e0","questionId":"ffef8800-7c9e-52b9-8af4-e0f0cf15db04","sourceKey":"bank:ENT211:ENT211-W01-087","payload":{"prompt":"What happened to Tunde's business within a year?","options":["It began exporting water to other countries","It made losses and he closed it down","It became profitable and he started expanding into nearby towns","It was bought by a large company"],"correctOption":2,"section":"Week 1: Concept of Entrepreneurship","explanation":"Within a year, Tunde's business became profitable and he began expanding into nearby towns. Option B is the opposite of what happened, and D and A are not part of the case."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 88, $official_bank_source${"itemId":"eee8b361-48b3-50e2-a755-c9d1ca072cde","questionId":"d38cf2c9-15d2-581c-820c-6a0e4d56e329","sourceKey":"bank:ENT211:ENT211-W01-088","payload":{"prompt":"Which of the following is NOT one of the learning objectives for the lesson on the concept of entrepreneurship?","options":["Calculate the break-even point of a new venture","Understand the characteristics of an entrepreneur","Describe the scope and dimensions of entrepreneurship","Define entrepreneurship"],"correctOption":0,"section":"Week 1: Concept of Entrepreneurship","explanation":"The lesson aims to help students define entrepreneurship, describe its scope and dimensions, and understand the characteristics of an entrepreneur and the dimensions of entrepreneurship. Calculating break-even is not one of these aims, while D, C and B are."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 89, $official_bank_source${"itemId":"fb18766b-4c90-5d9b-9328-77191bf4f921","questionId":"b27a9196-06c5-5dc1-8a4f-b9ade62a11b1","sourceKey":"bank:ENT211:ENT211-W02-001","payload":{"prompt":"In entrepreneurship, beyond simply starting a business, entrepreneurship is described as a mindset and a process of creating value by","options":["securing loans, hiring staff, and expanding branches","copying proven ideas, cutting costs, and avoiding risk","winning contracts, lobbying, and controlling prices","identifying opportunities, taking risks, and innovating"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Entrepreneurship is a mindset and a process of creating value through three things: identifying opportunities, taking risks, and innovating. Option A lists ordinary business activities, not the value-creating process itself. Option B is the opposite of the entrepreneurial mindset, which embraces calculated risk and new ideas."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 90, $official_bank_source${"itemId":"8f92f6ff-7616-57b6-8c3e-084d3c77ab1d","questionId":"139e732d-760f-5d0a-bb1a-cf8ca4d5c41a","sourceKey":"bank:ENT211:ENT211-W02-002","payload":{"prompt":"Which of the following is NOT one of the four entrepreneurial traits?","options":["Change agent","Opportunity seeker","Problem solver","Fund manager"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"The four entrepreneurial traits are opportunity seeker, risk-taker, problem solver and change agent, so fund manager is the odd one out. Options A, B and C are all genuine members of the four traits, which is why they cannot be the answer to a NOT question."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 91, $official_bank_source${"itemId":"80da022e-fb07-5229-b370-83b6d2f65f06","questionId":"7f4b41a5-439f-57dc-8598-546755b155e5","sourceKey":"bank:ENT211:ENT211-W02-003","payload":{"prompt":"Which of the following is one of the four entrepreneurial traits?","options":["Change agent","Rent seeker","Cost controller","Policy maker"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Change agent is one of the four entrepreneurial traits, alongside opportunity seeker, risk-taker and problem solver. A change agent drives change, for example by building a solution instead of just complaining about a problem. Options B, C and D may sound businesslike, but none of them is one of the four traits."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 92, $official_bank_source${"itemId":"97462e61-d945-570e-89bb-bd34354f89b9","questionId":"fac5bbff-67fb-533a-92e7-df1aa4c8d31e","sourceKey":"bank:ENT211:ENT211-W02-004","payload":{"prompt":"Which set correctly lists the four entrepreneurial traits?","options":["Market follower, risk-taker, problem solver, change agent","Opportunity seeker, risk-taker, profit maximizer, change agent","Opportunity seeker, risk-taker, problem solver, change agent","Opportunity seeker, risk avoider, problem solver, change agent"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"The four entrepreneurial traits are opportunity seeker, risk-taker, problem solver and change agent. Option D swaps in 'risk avoider', which contradicts the trait of taking calculated risks. Options A and B replace a genuine trait with 'profit maximizer' or 'market follower', which are not among the four."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 93, $official_bank_source${"itemId":"6f56613d-7b66-5686-887b-bb0fecd0580d","questionId":"9b7f4f72-9e84-5338-9b07-b94dff970cfe","sourceKey":"bank:ENT211:ENT211-W02-005","payload":{"prompt":"The ability to identify and capitalize on market gaps or unmet needs is the entrepreneurial trait known as","options":["The calculated risk-taker","The change agent","The opportunity seeker","The creative thinker"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"An opportunity seeker identifies and capitalizes on market gaps or unmet needs. Option A is about taking risks after assessing downsides, not spotting gaps. Option B is about driving change by fixing problems, and option D is about thinking outside conventional frameworks."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 94, $official_bank_source${"itemId":"40b77163-bb2a-54dc-aa70-3f6decf57a1a","questionId":"e2b49895-9860-50f8-a31c-73ccab562f4e","sourceKey":"bank:ENT211:ENT211-W02-006","payload":{"prompt":"The opportunity seeker trait involves","options":["risk assessment, tolerance for failure, and a high-reward mindset","education, mentorship, and experience","market awareness, proactiveness, and visionary thinking","trade, negotiation, and supply chain management"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Opportunity seeking involves market awareness, proactiveness and visionary thinking, which together help an entrepreneur spot gaps and unmet needs. Option A describes the calculated risk-taker. Option B is how nurtured skills are developed, and option D is what Igba Boi apprentices are taught."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 95, $official_bank_source${"itemId":"2c9855d8-0059-5299-9d14-3ac9dfd00567","questionId":"4b16d4ef-0d60-538b-8634-23fe289e8a11","sourceKey":"bank:ENT211:ENT211-W02-007","payload":{"prompt":"Which of the following is NOT one of the elements involved in the opportunity seeker trait?","options":["Market awareness","Proactiveness","Risk assessment","Visionary thinking"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Risk assessment belongs to the calculated risk-taker trait, which involves risk assessment, tolerance for failure and a high-risk, high-reward mindset. Options A, B and D are the three elements of the opportunity seeker: market awareness, proactiveness and visionary thinking."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 96, $official_bank_source${"itemId":"cf204da6-b665-52e0-891a-80c922ff33fe","questionId":"756b69d9-b7b1-5711-b0eb-eb29a21c2770","sourceKey":"bank:ENT211:ENT211-W02-008","payload":{"prompt":"Proactiveness and visionary thinking are elements of which entrepreneurial trait?","options":["Calculated risk-taker","Problem solver","Change agent","Opportunity seeker"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"The opportunity seeker trait involves market awareness, proactiveness and visionary thinking. Option A involves risk assessment and tolerance for failure instead. Options B and C describe a solution-oriented mindset focused on fixing inefficiencies and driving change."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 97, $official_bank_source${"itemId":"86eed75d-7721-53e7-98e2-03657b00ff4a","questionId":"eca17ae3-8884-59fe-add4-1c1786e6e0ff","sourceKey":"bank:ENT211:ENT211-W02-009","payload":{"prompt":"Sim Shagaya is the founder of","options":["Flutterwave","Konga","MAX.ng","iROKOtv"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Sim Shagaya founded Konga, one of Nigeria's earliest e-commerce giants. Option A was founded by Olugbenga Agboola and Iyinoluwa Aboyeji, option C by Chinedu Azodoh, and option D by Jason Njoku."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 98, $official_bank_source${"itemId":"26d2c63d-1641-51ac-a0d1-f4346359b434","questionId":"6da0061c-f3d7-5392-ba08-5f37d34079db","sourceKey":"bank:ENT211:ENT211-W02-010","payload":{"prompt":"Sim Shagaya founding Konga is used to illustrate which entrepreneurial trait?","options":["The opportunity seeker","The calculated risk-taker","Nurtured traits","The problem solver and change agent"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Shagaya spotted a market gap, the need for a trusted online marketplace in Nigeria, which is what an opportunity seeker does. Option B is illustrated by Aliko Dangote's investments, and option D by DentistAtYourDoor and MAX.ng. Option C relates to the born-or-made debate and the Igba Boi system."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 99, $official_bank_source${"itemId":"6fb06248-5d1c-5bc9-9647-ae6ed540cf53","questionId":"76c73040-2dae-5604-880d-5894065bd04d","sourceKey":"bank:ENT211:ENT211-W02-011","payload":{"prompt":"Which two conditions in Nigeria did Sim Shagaya observe before founding Konga?","options":["An infrastructure deficit and weak local manufacturing","Low penetration of formal retail and growing internet use","Widespread piracy and limited access to Nollywood films","Heavy Lagos traffic and poor dental care access"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Shagaya saw that formal retail had low penetration while internet use was growing, and that pointed him to the opportunity for a trusted online marketplace. Option D is the problem DentistAtYourDoor addressed, and option C is what iROKOtv tackled. Option A relates to Dangote's bet on local production."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 100, $official_bank_source${"itemId":"02389a4e-63df-5c9a-b4bc-1602999e938e","questionId":"922ed4fb-871f-53df-8936-6a8340dea4d6","sourceKey":"bank:ENT211:ENT211-W02-012","payload":{"prompt":"The opportunity Sim Shagaya identified in Nigeria, which led to Konga, was the need for","options":["a payment infrastructure for merchants","a trusted online marketplace","a mobile dental clinic","a tech-enabled motorcycle ride-hailing service"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Shagaya identified the opportunity for a trusted online marketplace, and Konga became one of Nigeria's earliest e-commerce giants. Option C describes DentistAtYourDoor, option D describes MAX.ng, and option A describes Flutterwave."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 101, $official_bank_source${"itemId":"36be9fe6-a769-5e01-9d58-48e61c703633","questionId":"1eac151c-3b00-5f24-a5ef-cfae99d94ae7","sourceKey":"bank:ENT211:ENT211-W02-013","payload":{"prompt":"Konga is described as","options":["the world's largest business incubator","one of Nigeria's earliest e-commerce giants","a hub for arts, dining and theatre in Lagos","the first mobile dental clinic in Lagos"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Konga, founded by Sim Shagaya, is described as one of Nigeria's earliest e-commerce giants. Option D is DentistAtYourDoor, option A is the Igba Boi apprenticeship system, and option C is Terra Kulture."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 102, $official_bank_source${"itemId":"db41a707-6572-5acf-ae29-cf73a462f337","questionId":"1de8aa84-35bf-5978-b329-bc2fcd1cb616","sourceKey":"bank:ENT211:ENT211-W02-014","payload":{"prompt":"In entrepreneurship, opportunity-seeking is best described as","options":["actively looking for frustrations and inefficiencies around you","waiting patiently for a sudden 'eureka' moment","inventing a completely new technology from scratch","avoiding uncertainty until success is guaranteed"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Opportunity-seeking means actively looking for frustrations and inefficiencies around you, not sitting back. Option B is exactly what it is said NOT to be. Option C is not required either, since Sim Shagaya did not invent e-commerce, and option D clashes with the idea that entrepreneurial risk is managed, not eliminated."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 103, $official_bank_source${"itemId":"4fe3891f-d496-5082-9379-f17050b16692","questionId":"ba263cd4-846d-5f3c-9b43-effad2af468b","sourceKey":"bank:ENT211:ENT211-W02-015","payload":{"prompt":"Sim Shagaya did not invent e-commerce. What he did instead, as an opportunity seeker, was to","options":["import a foreign e-commerce company without changes","build it only as an offline retail chain","apply it to the specific challenges and opportunities of the Nigerian market","wait for government to create the market first"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Shagaya took an existing idea, e-commerce, and applied it to the specific challenges and opportunities of the Nigerian market. This shows that opportunity seeking does not require inventing something new. Options A, B and D do not match this point about adapting an idea to a local market."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 104, $official_bank_source${"itemId":"bd1f1655-51f5-5edc-8f00-314cdea98176","questionId":"9fec800a-7bc4-554b-ab6d-dfbe79934814","sourceKey":"bank:ENT211:ENT211-W02-016","payload":{"prompt":"Tolu notices that smartphone use is rising fast in her town while no local business sells groceries online. She sees this unmet need and launches an online grocery store before anyone else does. Which entrepreneurial trait does Tolu mainly show?","options":["Resilience","Calculated risk-taker","Nurtured trait","Opportunity seeker"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Tolu identified and capitalized on a market gap, which defines the opportunity seeker, much like Sim Shagaya and Konga. Option B is about weighing downsides before taking risks, which the scenario does not emphasize. Option C refers to learned skills, and option A is about bouncing back from setbacks."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 105, $official_bank_source${"itemId":"c64ed011-0f42-5231-878a-a0b1b90f1358","questionId":"a0a226cd-6d77-5189-94e2-d96ffc7dad76","sourceKey":"bank:ENT211:ENT211-W02-017","payload":{"prompt":"The willingness to take calculated risks after assessing potential downsides describes","options":["The opportunity seeker","The creative thinker","The calculated risk-taker","The problem solver"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"The calculated risk-taker is willing to take risks, but only after assessing potential downsides. Option A is about identifying market gaps or unmet needs. Option D focuses on fixing inefficiencies, and option B is about thinking outside conventional frameworks."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 106, $official_bank_source${"itemId":"90287f09-ae65-5acb-bb48-74ee51432ea4","questionId":"3fcadce6-aa81-5af5-9032-be99be639dfe","sourceKey":"bank:ENT211:ENT211-W02-018","payload":{"prompt":"The calculated risk-taker trait involves","options":["market awareness, proactiveness, and visionary thinking","high energy, natural charisma, and extraversion","accounting, management, and marketing","risk assessment, tolerance for failure, and a high-risk, high-reward mindset"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Calculated risk-taking involves risk assessment, tolerance for failure and a high-risk, high-reward mindset. Option A lists the elements of the opportunity seeker. Option C lists learned skills, and option B mixes inborn qualities from the 'born' argument."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 107, $official_bank_source${"itemId":"5af53337-e1f4-598a-9f7a-9555ee0adcff","questionId":"61d021fe-2545-5aab-a95f-8bc7f02cfebe","sourceKey":"bank:ENT211:ENT211-W02-019","payload":{"prompt":"Which of the following is NOT one of the elements involved in the calculated risk-taker trait?","options":["Visionary thinking","A high-risk, high-reward mindset","Risk assessment","Tolerance for failure"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Visionary thinking is an element of the opportunity seeker, together with market awareness and proactiveness. Options B, C and D are the three elements of the calculated risk-taker."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 108, $official_bank_source${"itemId":"72bf218e-9edd-579f-b707-3b62a8c51ff6","questionId":"d10c7d79-844c-5423-bd30-b232637c6dd0","sourceKey":"bank:ENT211:ENT211-W02-020","payload":{"prompt":"Tolerance for failure is an element of which entrepreneurial trait?","options":["Opportunity seeker","Creative thinker","Change agent","Calculated risk-taker"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"The calculated risk-taker trait involves risk assessment, tolerance for failure and a high-risk, high-reward mindset. Option A involves market awareness, proactiveness and visionary thinking instead. Options B and C are about driving change and thinking outside conventional frameworks."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 109, $official_bank_source${"itemId":"8402cb78-be33-5210-bef3-6fd1e987532f","questionId":"c0ecada9-8b22-56ef-8414-bdb85ee1340b","sourceKey":"bank:ENT211:ENT211-W02-021","payload":{"prompt":"Aliko Dangote's heavy investment in cement production and Oil & Gas is used to illustrate which entrepreneurial trait?","options":["The innovator and creative thinker","The calculated risk-taker","The opportunity seeker","The problem solver and change agent"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Dangote invested heavily when others were skeptical, after understanding the infrastructure deficit, which is calculated risk-taking. Option C is illustrated by Sim Shagaya and Konga. Option D is illustrated by DentistAtYourDoor and MAX.ng, and option A by Terra Kulture, iROKOtv and Flutterwave."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 110, $official_bank_source${"itemId":"141395b6-2f29-5569-9961-bee1a6654736","questionId":"3eb7e4c2-ff15-5627-8273-831097785b67","sourceKey":"bank:ENT211:ENT211-W02-022","payload":{"prompt":"In which sectors did Aliko Dangote invest heavily when others were skeptical about local manufacturing capacity?","options":["E-commerce and online retail","Cement production and Oil & Gas","Film distribution and entertainment","Digital payments and fintech"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Dangote invested heavily in cement production and Oil & Gas in Nigeria. Option A is the area of Konga, option D is Flutterwave's field, and option C is iROKOtv's field."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 111, $official_bank_source${"itemId":"f266ef02-7baf-5b9d-a7ca-6fc3ff59eed8","questionId":"be6682df-3f16-5b66-abf5-68bb49e5c4ec","sourceKey":"bank:ENT211:ENT211-W02-023","payload":{"prompt":"When Aliko Dangote invested heavily in cement and Oil & Gas, what were others skeptical about?","options":["Online film piracy","Internet penetration","Local manufacturing capacity","Dental care access"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Dangote invested at a time when others doubted Nigeria's local manufacturing capacity, which is what made his move a real risk. Option B relates to Konga's market, option D to DentistAtYourDoor, and option A to iROKOtv."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 112, $official_bank_source${"itemId":"fcd66cd9-1f22-52e0-9852-8c80341b2e80","questionId":"97febced-d570-524c-94d5-3ec64903ee47","sourceKey":"bank:ENT211:ENT211-W02-024","payload":{"prompt":"What made Aliko Dangote's risk a calculated one?","options":["He understood Nigeria's infrastructure deficit and bet on the long-term need for local production","He had a guarantee that his investments could not fail","He waited until others had stopped being skeptical","He copied a business that had already succeeded in Nigeria"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Dangote's risk was calculated because he understood Nigeria's infrastructure deficit and bet on the long-term need for local production. Option B is wrong because entrepreneurial risk is about managing uncertainty, not eliminating it. Option C contradicts the fact that he invested while others were still skeptical."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 113, $official_bank_source${"itemId":"ece3f27c-d916-5288-8155-7c762da3c13a","questionId":"2de6675c-d223-5691-8588-e9405fe1237c","sourceKey":"bank:ENT211:ENT211-W02-025","payload":{"prompt":"In entrepreneurship, entrepreneurial risk is about","options":["gambling without assessing downsides","avoiding any investment others doubt","managing uncertainty, not eliminating it","eliminating uncertainty before acting"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Entrepreneurial risk is about managing uncertainty, not eliminating it, as Dangote's calculated bet shows. Option D is the reverse of this idea. Option A ignores the 'calculated' part, since a calculated risk-taker assesses potential downsides first."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 114, $official_bank_source${"itemId":"4a860f8e-3c5d-55b3-ae7f-40cf95cc5596","questionId":"d8921566-6f37-59ce-8bb7-8499415de4b4","sourceKey":"bank:ENT211:ENT211-W02-026","payload":{"prompt":"Aliko Dangote's calculated risk in cement and Oil & Gas is said to have built","options":["one of Nigeria's earliest e-commerce giants","a multi-billion-dollar industrial empire","a payment infrastructure across Africa","the first mobile dental clinic in Lagos"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Dangote's calculated risk built a multi-billion-dollar industrial empire. Option A describes Konga, option D describes DentistAtYourDoor, and option C describes Flutterwave."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 115, $official_bank_source${"itemId":"acbb9ee2-233c-5fe4-a036-ce2adda56d39","questionId":"27360825-f0df-5be6-9a88-2b7ccdc3824c","sourceKey":"bank:ENT211:ENT211-W02-027","payload":{"prompt":"Before putting most of her savings into a rice-processing mill, Ngozi studies what could go wrong, estimates possible losses and decides the long-term demand justifies the bet. She then invests heavily. Which trait does she show?","options":["Change agent","Creative thinker","Calculated risk-taker","Opportunity seeker"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Ngozi assessed the potential downsides before committing, which is the heart of the calculated risk-taker, similar to Dangote betting on long-term demand for local production. Option D would focus on spotting a market gap, which the scenario does not stress. Options A and B focus on driving change and generating unconventional ideas."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 116, $official_bank_source${"itemId":"2471d26e-cb0a-5bbc-b8ec-f70f56f76e18","questionId":"c57ed545-5e2c-5dd0-9a30-346ab59b9a3f","sourceKey":"bank:ENT211:ENT211-W02-028","payload":{"prompt":"What makes a risk 'calculated' in the calculated risk-taker trait?","options":["It carries no chance of failure","It is taken only with borrowed money","It is taken after assessing potential downsides","It is approved by competitors first"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"A calculated risk is one taken after assessing potential downsides. Option A is wrong because the trait involves tolerance for failure, so failure remains possible. Options B and D have nothing to do with how the trait is defined."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 117, $official_bank_source${"itemId":"26632841-4a2f-5646-828c-c4bee7d0ae49","questionId":"13d6ea58-31dd-5435-8f80-d29305ed3603","sourceKey":"bank:ENT211:ENT211-W02-029","payload":{"prompt":"A solution-oriented mindset focused on fixing inefficiencies and driving change, often creating social impact, describes","options":["The natural (born) entrepreneur","The calculated risk-taker","The opportunity seeker","The problem solver and the change agent"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"The problem solver and change agent has a solution-oriented mindset that fixes inefficiencies and drives change, often with social impact. Option C is about identifying market gaps or unmet needs. Option B is about taking risks after assessing downsides, and option A refers to inborn qualities."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 118, $official_bank_source${"itemId":"6ac5f1fb-9ef3-54a5-9b2b-9575c8beb8c8","questionId":"0809b1f1-4216-56ac-ae42-7bce522b76f8","sourceKey":"bank:ENT211:ENT211-W02-030","payload":{"prompt":"The problem solver and change agent mindset often results in","options":["low penetration of formal retail","social impact","higher piracy levels","a near 100% success rate"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"The problem solver and change agent mindset fixes inefficiencies and drives change, often creating social impact. Option D describes the Igba Boi system. Options A and C are problems that other entrepreneurs responded to, not results of this mindset."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 119, $official_bank_source${"itemId":"d9d4b195-8a2c-560d-a51e-416e74f824f3","questionId":"ffffe11f-ee85-57a2-a519-26b4040766f7","sourceKey":"bank:ENT211:ENT211-W02-031","payload":{"prompt":"Dr. Akintonwa Oluwayemisi is associated with which venture?","options":["Konga","MAX.ng","Terra Kulture","DentistAtYourDoor"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Dr. Akintonwa Oluwayemisi launched DentistAtYourDoor, the first mobile dental clinic. Option C is Bolanle Austen-Peters' venture, option B is Chinedu Azodoh's, and option A is Sim Shagaya's."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 120, $official_bank_source${"itemId":"44db3a66-8f2b-556e-94ae-64be0cc0f71b","questionId":"a690f669-02ae-5260-99a4-7c48bababd00","sourceKey":"bank:ENT211:ENT211-W02-032","payload":{"prompt":"DentistAtYourDoor solved the problem of","options":["Nollywood piracy and access","dental care access in traffic-heavy Lagos","unsafe, informal motorcycle taxis","payment challenges across Africa"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"DentistAtYourDoor solved the problem of dental care access in traffic-heavy Lagos by bringing the clinic to the people. Option C is the problem MAX.ng tackled, option A is iROKOtv's, and option D is Flutterwave's."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 121, $official_bank_source${"itemId":"3964503b-643a-5fcf-aa01-eef8572be17e","questionId":"38d33d1e-0cb3-5999-97cf-530f76f15776","sourceKey":"bank:ENT211:ENT211-W02-033","payload":{"prompt":"How did Dr. Akintonwa Oluwayemisi solve the problem of dental care access in traffic-heavy Lagos?","options":["By lobbying government to reduce traffic","By building the largest dental hospital in Lagos","By offering dental advice only on radio","By launching the first mobile dental clinic"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"She launched the first mobile dental clinic, DentistAtYourDoor, which brings the service to the people instead of making them fight traffic. Options A, B and C do not describe what she did."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 122, $official_bank_source${"itemId":"e8ca57ce-353b-5326-bf63-a22fe5e47781","questionId":"fe7c0b34-12a1-50a2-ab60-bb2b6349b3ae","sourceKey":"bank:ENT211:ENT211-W02-034","payload":{"prompt":"Chinedu Azodoh is associated with","options":["Flutterwave","MAX.ng","DentistAtYourDoor","iROKOtv"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Chinedu Azodoh is linked with MAX.ng, which created a tech-enabled, safer ride-hailing and delivery service. Option D is Jason Njoku's, option A belongs to Olugbenga Agboola and Iyinoluwa Aboyeji, and option C is Dr. Akintonwa Oluwayemisi's."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 123, $official_bank_source${"itemId":"a6eb4e71-f7a6-5af6-851c-3b0c0bed79ff","questionId":"4474f805-f6da-57d0-94df-cf90a892f252","sourceKey":"bank:ENT211:ENT211-W02-035","payload":{"prompt":"MAX.ng solved the problem of","options":["low penetration of formal retail","unsafe, informal motorcycle taxis ('okada')","dental care access in traffic-heavy Lagos","content distribution piracy in Nollywood"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"MAX.ng tackled unsafe, informal motorcycle taxis, popularly called okada, with a tech-enabled service. Option C is DentistAtYourDoor's problem, option A is the gap Konga addressed, and option D is what iROKOtv tackled."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 124, $official_bank_source${"itemId":"eacf87c4-5455-52d2-a187-b19da5ca10cb","questionId":"c650c058-9b35-5e6a-90fd-fe51764dccf1","sourceKey":"bank:ENT211:ENT211-W02-036","payload":{"prompt":"MAX.ng solved the okada problem by creating","options":["a tech-enabled, safer, energy-saving and more reliable ride-hailing and delivery service","a trusted online marketplace for consumer goods","an online platform for Nollywood films","a payment infrastructure for global merchants"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"MAX.ng created a tech-enabled, safer, energy-saving and more reliable ride-hailing and delivery service. Option B describes Konga, option C describes iROKOtv, and option D describes Flutterwave."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 125, $official_bank_source${"itemId":"7ccbb950-88ad-53e6-987f-921c37899b4b","questionId":"43595de1-7810-53c4-8254-8c9161a72e92","sourceKey":"bank:ENT211:ENT211-W02-037","payload":{"prompt":"DentistAtYourDoor and MAX.ng are both used to illustrate which entrepreneurial trait?","options":["The opportunity seeker","The calculated risk-taker","Nurtured traits (made)","The problem solver and the change agent"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Both ventures fixed real, persistent problems, dental access in Lagos traffic and unsafe okada rides, which shows the problem solver and change agent. Option A is illustrated by Sim Shagaya, option B by Aliko Dangote, and option C by the Igba Boi system."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 126, $official_bank_source${"itemId":"766d1fc6-6e4c-5637-a7ff-eb2281869870","questionId":"d484f4fa-12a9-522e-9083-224492cb54eb","sourceKey":"bank:ENT211:ENT211-W02-038","payload":{"prompt":"In entrepreneurship, the most sustainable businesses are those that","options":["avoid all forms of risk","rely only on natural charisma","solve a persistent problem","copy the most popular product"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"The most sustainable businesses solve a persistent problem, like DentistAtYourDoor did with dental access in Lagos traffic. Option D is not presented as the key to sustainability. Option A contradicts calculated risk-taking, and option B ignores the role of learned skills."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 127, $official_bank_source${"itemId":"2d780748-f910-54c6-8ff4-afdf15667420","questionId":"7b6859b6-ee73-5d4c-9055-0baf52a00694","sourceKey":"bank:ENT211:ENT211-W02-039","payload":{"prompt":"Dr. Oluwayemisi did not just complain about the traffic in Lagos; she built a mobile clinic to bring the service to the people. This is described as being","options":["a calculated risk-taker","a natural-born entrepreneur","an Igba Boi apprentice","a change agent"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Turning a complaint into action that brings a service to people is what being a change agent means. Option A focuses on taking risks after assessing downsides. Option C refers to the apprenticeship system, and option B refers to inborn traits, none of which this example is used to show."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 128, $official_bank_source${"itemId":"e3218a5b-d80b-5a30-b7ef-e16dcc664612","questionId":"a138723d-8c8d-5b7e-ba82-d89773369b55","sourceKey":"bank:ENT211:ENT211-W02-040","payload":{"prompt":"In Yaba, students waste hours queuing for water at one borehole. Emeka builds a cheap tech-enabled booking and delivery system that ends the queues and improves life in the area. Which trait does this best show?","options":["Natural (born) trait","Problem solver and change agent","Calculated risk-taker","Igba Boi settlement"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Emeka fixed an inefficiency and drove change with social impact, which is the problem solver and change agent mindset. Option C would stress weighing potential downsides before a big bet. Options A and D relate to the born-or-made debate rather than to a trait shown in action."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 129, $official_bank_source${"itemId":"4b2f9009-ce96-5820-9eb1-199c18b51674","questionId":"bc104f17-c2f0-5429-944e-c240cdcf1032","sourceKey":"bank:ENT211:ENT211-W02-041","payload":{"prompt":"Complete the statement: 'Entrepreneurs thrive on ...'","options":["eliminating all uncertainty","solving real problems","waiting for eureka moments","inheriting family capital"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Entrepreneurs thrive on solving real problems, which is why the most sustainable businesses solve persistent ones. Option C is rejected because opportunity-seeking means actively looking for frustrations. Option A is wrong because entrepreneurial risk manages uncertainty rather than eliminating it."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 130, $official_bank_source${"itemId":"5b724a89-d511-5d16-aa89-27c27e4c6abc","questionId":"b5975878-77fa-5169-9689-09653a0e1f6f","sourceKey":"bank:ENT211:ENT211-W02-042","payload":{"prompt":"The 'Natural Traits (Born)' argument holds that some people have, from birth,","options":["high energy, natural charisma, and high risk tolerance","market awareness gained through mentorship","accounting, management, and marketing skills","trade, negotiation, and supply chain knowledge"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"The born argument says some people have high energy, natural charisma and high risk tolerance from birth. Option C lists learned skills from the 'made' argument. Option D is what Igba Boi apprentices are taught, and option B involves mentorship, which is nurture."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 131, $official_bank_source${"itemId":"649f0bbc-f521-52c1-9aee-619c22b4ad16","questionId":"1c3f63fd-55dd-5f60-9ba7-31e53c3800a0","sourceKey":"bank:ENT211:ENT211-W02-043","payload":{"prompt":"The 'Nurtured Traits (Made)' argument holds that entrepreneurial skills are developed through","options":["education, mentorship, and experience","birth, family name, and luck","charisma, extraversion, and energy","inheritance, capital, and connections"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"The made argument says skills are developed through education, mentorship and experience. Option C lists qualities from the born argument. Options B and D are not given as ways entrepreneurial skills are built."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 132, $official_bank_source${"itemId":"1da75b2f-f01a-59fa-ab38-0aa367cce8ff","questionId":"17afcd01-450b-5f9f-a203-55762cf24241","sourceKey":"bank:ENT211:ENT211-W02-044","payload":{"prompt":"Which of the following is listed as a learned skill in the 'made' argument?","options":["Emotional intelligence","High energy","Extraversion","Natural charisma"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Accounting, management, marketing and emotional intelligence are listed as learned skills. Options B, C and D come from the born argument, which points to qualities people have from birth or that appear early."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 133, $official_bank_source${"itemId":"4b26904c-eba7-587a-b611-76a66b6c56e6","questionId":"c4af5e2f-6824-56bd-b11f-f6812c4ab657","sourceKey":"bank:ENT211:ENT211-W02-045","payload":{"prompt":"Which of the following is NOT listed among the learned skills in the 'Nurtured Traits (Made)' argument?","options":["Natural charisma","Marketing","Accounting","Emotional intelligence"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Natural charisma belongs to the born argument, along with high energy and high risk tolerance from birth. Options B, C and D are all named as learned skills, together with management."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 134, $official_bank_source${"itemId":"ca4504bf-9a22-583b-bff9-d75002f6939e","questionId":"6dc70b25-4851-53a1-880c-26a5bb0e7b39","sourceKey":"bank:ENT211:ENT211-W02-046","payload":{"prompt":"In the 'born' argument, which of the following is named as an inherent quality that appears early in some people?","options":["Supply chain management","Management","Extraversion","Accounting"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"The born argument names resilience, creativity and extraversion as inherent qualities that appear early for some people. Options B and D are learned skills, and option A is something Igba Boi apprentices are taught."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 135, $official_bank_source${"itemId":"5f4bf24e-a975-557b-a4f7-b48889cc8348","questionId":"efc8fd89-679d-5a6e-86ff-dc06e9d98c98","sourceKey":"bank:ENT211:ENT211-W02-047","payload":{"prompt":"Igba Boi is another name for","options":["the Nigerian Stock Exchange","a government start-up grant","the Igbo Apprenticeship System","a mobile dental clinic"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Igba Boi is the Igbo Apprenticeship System, in which young people are mentored and then 'settled' to start their own businesses. Options A, B and D have no link to the term."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 136, $official_bank_source${"itemId":"13199139-6e92-5405-9596-b8298b997184","questionId":"14630bfa-be46-5bb7-b932-dbfd23ababce","sourceKey":"bank:ENT211:ENT211-W02-048","payload":{"prompt":"The 'world's largest business incubator', found right here in Nigeria, refers to","options":["the Igba Boi apprenticeship system","Flutterwave","Konga","Terra Kulture"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"The Igbo Apprenticeship System, Igba Boi, is called the world's largest business incubator. Option C is an e-commerce company, option D is a cultural hub and option B is a payment company."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 137, $official_bank_source${"itemId":"03957ccf-394a-53ae-9100-cd440d84e288","questionId":"1f80b546-aa71-5c6d-b704-ca8358ee8d25","sourceKey":"bank:ENT211:ENT211-W02-049","payload":{"prompt":"Which sequence correctly describes the Igba Boi process?","options":["Nurtured, then settled, then picked","Picked, then nurtured through years of mentorship, then settled (funded)","Settled (funded), then picked, then nurtured","Picked, then settled (funded), then nurtured"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Young people are first picked, often with no capital, then nurtured through years of mentorship, and finally settled, meaning funded to start their own business. Options A, C and D put the steps out of order, for example funding before the mentorship has happened."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 138, $official_bank_source${"itemId":"2250db57-2c81-5249-bee8-f59115e40bd2","questionId":"e1f807e2-cb87-56f1-aa68-d291bfe065d5","sourceKey":"bank:ENT211:ENT211-W02-050","payload":{"prompt":"In the Igba Boi system, being 'settled' means the apprentice is","options":["enrolled in a university","funded to start his own business","sent back home without support","made a permanent employee"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Being settled means the apprentice is funded to start his own business after years of mentorship. Options A, C and D contradict the idea that the system ends with a new, independent business."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 139, $official_bank_source${"itemId":"7131b5c9-3bfe-5397-b481-cd60fb6ea254","questionId":"a76f6d58-99f4-5d97-988f-bc2c405552fa","sourceKey":"bank:ENT211:ENT211-W02-051","payload":{"prompt":"Young people picked into the Igba Boi system often start with","options":["no capital","an established shop of their own","a large inheritance","a university degree"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Apprentices are often picked with no capital, and the system later funds them when they are settled. Options B, C and D miss the point that the system builds entrepreneurs from scratch."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 140, $official_bank_source${"itemId":"9be56c4b-4f0f-5240-984a-b70be4daa3cf","questionId":"46956900-7bf6-59aa-889f-c29778eb0aff","sourceKey":"bank:ENT211:ENT211-W02-052","payload":{"prompt":"The Igba Boi system is said to have a success rate of","options":["about 25%","under 10%","about 50%","near 100%"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"The Igba Boi system is said to have a near 100% success rate, which is used as proof that entrepreneurs can be made. Options A, B and C understate this figure."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 141, $official_bank_source${"itemId":"c2fd7504-42ae-596d-be2b-5c10e5fd8c6e","questionId":"10a8957c-1411-5710-83d9-d0ff8d1261fd","sourceKey":"bank:ENT211:ENT211-W02-053","payload":{"prompt":"The Igba Boi system is presented as the perfect example of","options":["nature, proving that entrepreneurs are born","inheritance, proving wealth passes in families","luck, proving success is random","nurture, proving that entrepreneurs can be made"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Igba Boi is the perfect example of nurture: young people are taught and mentored, which proves entrepreneurs can be made. Option A is the opposite conclusion. Options B and C are not ideas linked to the system."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 142, $official_bank_source${"itemId":"88cf9d1d-d7fa-5030-9cbb-e7c4ddbcec2d","questionId":"a589f419-9a2c-5660-88e3-45131e57af14","sourceKey":"bank:ENT211:ENT211-W02-054","payload":{"prompt":"Igba Boi apprentices are taught","options":["market awareness, proactiveness, and visionary thinking","risk assessment and tolerance for failure only","accounting, emotional intelligence, and charisma","trade, negotiation, and supply chain management"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Apprentices are taught trade, negotiation and supply chain management, which is why they come to know things like the price of spare parts. Option C mixes learned skills with charisma, which is inborn. Option A lists opportunity seeker elements, and option B describes the risk-taker."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 143, $official_bank_source${"itemId":"bc0f958c-f401-5abd-9bc5-4764f8256570","questionId":"00ca1787-2576-5681-8cae-117b9b93c49c","sourceKey":"bank:ENT211:ENT211-W02-055","payload":{"prompt":"The remark 'These boys aren't born knowing the price of spare parts' supports which view?","options":["Entrepreneurs are only born with natural traits","Entrepreneurship depends mainly on capital","Entrepreneurs can be made through nurture","Risk-taking cannot be learned"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"The point is that apprentices learn trade knowledge such as prices through mentorship, so entrepreneurs can be made. Option A is the view this remark argues against. Options B and D are contradicted by apprentices starting with no capital and being taught their skills."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 144, $official_bank_source${"itemId":"4092ac79-589b-544d-a929-5eaf19a19c17","questionId":"5d3a2477-d123-5aae-b01b-66911a0c4f69","sourceKey":"bank:ENT211:ENT211-W02-056","payload":{"prompt":"At 14, Chuka leaves his village to serve a spare-parts dealer in Onitsha with no money of his own. After seven years of learning the trade, his master gives him funds to open his own shop. Which concept does this describe?","options":["The calculated risk-taker trait","A high-risk, high-reward mindset","The 'Natural Traits (Born)' argument","The Igba Boi apprenticeship system"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Being picked with no capital, mentored for years and then settled with funds is exactly the Igba Boi process. Option C argues that traits are inborn, which this story contradicts. Options A and B relate to risk, not to an apprenticeship model."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 145, $official_bank_source${"itemId":"eb4adf46-cedc-52ce-af2c-742b8ba4e508","questionId":"7190af07-4acb-585a-9d76-c13a964cf579","sourceKey":"bank:ENT211:ENT211-W02-057","payload":{"prompt":"In the entrepreneurial self-assessment profile, 'How do you bounce back from setbacks?' measures","options":["Resilience","Risk Tolerance","Opportunity Seeking","Creativity"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Resilience is about how you bounce back from setbacks. Option B asks about comfort with calculated, uncertain outcomes, option D about generating new ideas, and option C about spotting problems or gaps."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 146, $official_bank_source${"itemId":"c32375f5-1c33-5e2c-b741-73c0326bee78","questionId":"fc73cc03-dd88-53b8-960a-6af0b907f0c1","sourceKey":"bank:ENT211:ENT211-W02-058","payload":{"prompt":"In the entrepreneurial self-assessment profile, 'How comfortable are you with calculated, uncertain outcomes?' measures","options":["Creativity","Problem-Solving","Risk Tolerance","Resilience"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Risk Tolerance asks how comfortable you are with calculated, uncertain outcomes. Option D is about bouncing back from setbacks, option B about moving from a problem to solutions, and option A about generating new ideas."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 147, $official_bank_source${"itemId":"5f82b0fb-a746-5749-8da3-1a78aab386a8","questionId":"2b840098-1613-5e74-b295-33fb70cbb92e","sourceKey":"bank:ENT211:ENT211-W02-059","payload":{"prompt":"In the entrepreneurial self-assessment profile, 'How quickly do you move from identifying a problem to brainstorming solutions?' measures","options":["Problem-Solving","Resilience","Opportunity Seeking","Risk Tolerance"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Problem-Solving measures how quickly you move from identifying a problem to brainstorming solutions. Option C is tempting, but it asks how often you spot problems or gaps, not how fast you turn to solutions. Options B and D are about uncertain outcomes and bouncing back."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 148, $official_bank_source${"itemId":"150277bd-ffc1-55b3-b10e-3b0613ea84b8","questionId":"b2c8ec1b-cb6b-5089-a006-675074724e32","sourceKey":"bank:ENT211:ENT211-W02-060","payload":{"prompt":"In the entrepreneurial self-assessment profile, the Opportunity Seeking dimension asks","options":["How do you bounce back from setbacks?","How comfortable are you with calculated, uncertain outcomes?","How often do you spot problems or gaps around you?","How easily do you generate new ideas or unconventional approaches?"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Opportunity Seeking asks how often you spot problems or gaps around you. Option D is the Creativity question, option A is Resilience, and option B is Risk Tolerance."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 149, $official_bank_source${"itemId":"f38e82ba-499f-5172-b086-4c3ac1b348df","questionId":"ddb46006-9178-57a9-9306-bbbb90691313","sourceKey":"bank:ENT211:ENT211-W02-061","payload":{"prompt":"In the entrepreneurial self-assessment profile, the Creativity dimension asks","options":["How often do you spot problems or gaps around you?","How do you bounce back from setbacks?","How quickly do you move from identifying a problem to brainstorming solutions?","How easily do you generate new ideas or unconventional approaches?"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Creativity asks how easily you generate new ideas or unconventional approaches. Option A is Opportunity Seeking, option C is Problem-Solving, and option B is Resilience."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 150, $official_bank_source${"itemId":"c6363ff1-9061-5c05-8851-c9ea8231c62d","questionId":"b4d0138d-891e-5505-8e27-6e054971525a","sourceKey":"bank:ENT211:ENT211-W02-062","payload":{"prompt":"Which of the following is NOT one of the labelled dimensions in the 'Assess Your Entrepreneurial Profile' self-assessment?","options":["Opportunity Seeking","Emotional intelligence","Resilience","Risk Tolerance"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Emotional intelligence appears as a learned skill in the born-or-made debate, not as a self-assessment dimension. Options A, C and D are labelled dimensions, together with Problem-Solving and Creativity."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 151, $official_bank_source${"itemId":"716f0b84-bc22-5acb-bbf9-c8a815e487a8","questionId":"40d346e5-4b89-598f-a1f7-91d2835db600","sourceKey":"bank:ENT211:ENT211-W02-063","payload":{"prompt":"Introducing new products, services, or business models is called","options":["Opportunity seeking","Creativity","Risk tolerance","Innovation"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Innovation introduces new products, services or business models; it turns an idea into reality. Option B is thinking outside conventional frameworks to develop unique solutions, which is the idea stage. Options A and C are entrepreneurial traits or profile dimensions, not this definition."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 152, $official_bank_source${"itemId":"723b9ca8-0516-5eb6-aeed-0f1719fa2e5a","questionId":"eb03d72a-5d1e-525c-a669-4cdc3d0ebeb0","sourceKey":"bank:ENT211:ENT211-W02-064","payload":{"prompt":"Thinking outside conventional frameworks to develop unique solutions is called","options":["Creativity","Innovation","Proactiveness","Resilience"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Creativity is thinking outside conventional frameworks to develop unique solutions. Option B is the act of introducing new products, services or business models, which makes ideas real. Option C is an element of opportunity seeking, and option D is about bouncing back from setbacks."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 153, $official_bank_source${"itemId":"12377d4c-c006-580c-9c4b-dbcc097f734a","questionId":"66a95cf9-070d-53df-a9cb-40b565622374","sourceKey":"bank:ENT211:ENT211-W02-065","payload":{"prompt":"Which statement correctly distinguishes creativity from innovation?","options":["Creativity and innovation both mean introducing new business models","Creativity is learned, while innovation is inborn","Creativity involves having a better idea; innovation involves making it a reality","Innovation involves having a better idea; creativity involves making it a reality"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Creativity is having a better idea, while innovation is making that idea a reality. Option D swaps the two, which is a common trap. Option A wrongly treats them as the same, and option B is not how the two are distinguished."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 154, $official_bank_source${"itemId":"3f617aba-8ba6-5726-8d47-01feec846869","questionId":"f5641819-01ba-5b96-9705-347750c720f7","sourceKey":"bank:ENT211:ENT211-W02-066","payload":{"prompt":"Bisi sketches a clever new design for a solar-powered phone charger in her notebook. Months later, Kunle manufactures and sells it to customers in Ibadan. Bisi's sketch and Kunle's launch represent, respectively,","options":["creativity and innovation","risk tolerance and resilience","innovation and creativity","opportunity seeking and nurture"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Bisi had the better idea, which is creativity, and Kunle made it a reality as a product on the market, which is innovation. Option C reverses the pair. Options B and D do not describe the move from idea to product."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 155, $official_bank_source${"itemId":"edd79b21-bb6c-5baf-bb21-59f6324f8eea","questionId":"936ad01b-f791-5a29-a32b-f969c450fa44","sourceKey":"bank:ENT211:ENT211-W02-067","payload":{"prompt":"Bolanle Austen-Peters is associated with","options":["Konga","DentistAtYourDoor","Terra Kulture","iROKOtv"],"correctOption":2,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Bolanle Austen-Peters is behind Terra Kulture, which reimagined the cultural space in Lagos. Option D is Jason Njoku's, option A is Sim Shagaya's, and option B is Dr. Akintonwa Oluwayemisi's."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 156, $official_bank_source${"itemId":"8837ce9d-c8bb-55eb-94fe-b61c3d269daa","questionId":"67ae0530-fb16-51f5-b8df-fea2cffd55eb","sourceKey":"bank:ENT211:ENT211-W02-068","payload":{"prompt":"Terra Kulture is described as having","options":["launched the first mobile dental clinic in Lagos","reimagined the cultural space in Lagos, creating a vibrant hub for arts, dining, and theatre","revolutionized Nollywood content distribution by moving it online","provided payment infrastructure for merchants across Africa"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Terra Kulture reimagined the cultural space in Lagos as a vibrant hub for arts, dining and theatre. Option C describes iROKOtv, option D describes Flutterwave, and option A describes DentistAtYourDoor."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 157, $official_bank_source${"itemId":"eea2732b-bd35-5280-8d7c-394e8e999f69","questionId":"95ed64ac-0c69-5097-9b17-f79fb7b7fcd7","sourceKey":"bank:ENT211:ENT211-W02-069","payload":{"prompt":"Jason Njoku is associated with","options":["iROKOtv","Terra Kulture","MAX.ng","Flutterwave"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Jason Njoku is linked with iROKOtv, which moved Nollywood content distribution online. Option C is Chinedu Azodoh's, option D belongs to Olugbenga Agboola and Iyinoluwa Aboyeji, and option B is Bolanle Austen-Peters'."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 158, $official_bank_source${"itemId":"190a8fa7-f6df-5286-b15b-be1549bc20e1","questionId":"0b775c25-b710-5c56-a181-3d0d490703b2","sourceKey":"bank:ENT211:ENT211-W02-070","payload":{"prompt":"iROKOtv revolutionized Nollywood content distribution by moving it online. Which issues did this solve?","options":["Unsafe okada rides","Piracy and access","Payment challenges for merchants","Traffic and dental care"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Moving Nollywood distribution online helped solve piracy and access issues. Option D relates to DentistAtYourDoor, option A to MAX.ng, and option C to Flutterwave."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 159, $official_bank_source${"itemId":"12e3b308-49c8-5fcc-8641-171e458ef28e","questionId":"bfbf3557-b8dd-5bfb-a6c6-b577768c8372","sourceKey":"bank:ENT211:ENT211-W02-071","payload":{"prompt":"Flutterwave is associated with","options":["Sim Shagaya and Aliko Dangote","Olugbenga Agboola and Iyinoluwa Aboyeji","Jason Njoku and Chinedu Azodoh","Bolanle Austen-Peters and Akintonwa Oluwayemisi"],"correctOption":1,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Flutterwave is linked with Olugbenga Agboola and Iyinoluwa Aboyeji. The pairs in options C, A and D are entrepreneurs linked with other ventures, such as iROKOtv, MAX.ng, Konga, Dangote's industries, Terra Kulture and DentistAtYourDoor."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 160, $official_bank_source${"itemId":"72b31068-cd40-5e1c-a453-2e0919dbfcd4","questionId":"2ea8fa81-4dfa-5f3f-8ce3-f29c043dc4b8","sourceKey":"bank:ENT211:ENT211-W02-072","payload":{"prompt":"Flutterwave solved the payment challenge in Africa by","options":["providing a payment infrastructure for global merchants and payment service providers across the continent","moving Nollywood films online to fight piracy","creating a hub for arts, dining and theatre","building a trusted online marketplace for Nigerian shoppers"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Flutterwave provides a payment infrastructure for global merchants and payment service providers across Africa. Option D describes Konga, option B describes iROKOtv, and option C describes Terra Kulture."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 161, $official_bank_source${"itemId":"00e9f8f1-2062-5cbc-b3a9-e1d28ffc1f36","questionId":"777108e0-ddf2-54d3-8c4a-e6090bc3f787","sourceKey":"bank:ENT211:ENT211-W02-073","payload":{"prompt":"Terra Kulture, iROKOtv and Flutterwave are all used as examples of","options":["innovators and creative thinkers","calculated risk-takers","the 'Natural Traits (Born)' argument","the Igba Boi apprenticeship system"],"correctOption":0,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"These three ventures introduced new services or business models, so they are examples of innovators and creative thinkers. Option B is illustrated by Aliko Dangote. Options C and D come from the born-or-made debate."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 162, $official_bank_source${"itemId":"11086157-f62f-5e14-9c89-33f2899669fc","questionId":"4dda1d23-d9ed-5281-ab0a-ed25fc17d310","sourceKey":"bank:ENT211:ENT211-W02-074","payload":{"prompt":"Which entrepreneur is cited as an example of innovators and creative thinkers?","options":["Sim Shagaya","Chinedu Azodoh","Aliko Dangote","Jason Njoku"],"correctOption":3,"section":"Weeks 2-3: Entrepreneurship Traits","explanation":"Jason Njoku of iROKOtv is an example of innovators and creative thinkers for moving Nollywood distribution online. Option A illustrates the opportunity seeker, option C the calculated risk-taker, and option B the problem solver and change agent."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 163, $official_bank_source${"itemId":"2ae729ed-b378-5c80-a64a-cc3b47d7d882","questionId":"e6366806-181a-5ceb-9e44-4101929c2734","sourceKey":"bank:ENT211:ENT211-W04-001","payload":{"prompt":"The systematic practice of developing and marketing breakthrough products and services for adoption by customers is known as","options":["Change management","Invention","Innovation","Knowledge management"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"Innovation is the systematic practice of developing and marketing breakthrough products and services so that customers adopt them. Option B (invention) is only coming up with something new, not making it work in the market. Options A and D deal with managing knowledge and managing change, not with bringing breakthrough offerings to customers."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 164, $official_bank_source${"itemId":"a9a1c497-2723-507a-9977-8ce18314b667","questionId":"f7c2b26f-6c8e-5f42-ae93-eb4a9fc21646","sourceKey":"bank:ENT211:ENT211-W04-002","payload":{"prompt":"The definition of innovation as \"the systematic practice of developing and marketing breakthrough products and services for adoption by customers\" is attributed to","options":["World Bank (2020)","OECD","McKinsey (2022)","Kurt Lewin"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"This definition of innovation comes from McKinsey (2022). Option D, Kurt Lewin, is linked to the 3-stage model of planned change, not to this innovation definition. Options A and B are not where this particular definition comes from."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 165, $official_bank_source${"itemId":"16395513-556a-5f73-82b0-13397ab54477","questionId":"d285e926-dc3b-52ef-aa15-f5f990c58d08","sourceKey":"bank:ENT211:ENT211-W04-003","payload":{"prompt":"In entrepreneurship, innovation is best described as","options":["The habit of preferring familiar ways of doing things","The process of managing an organisation's stored information","The mere invention of a new idea or device","The successful implementation of new ideas that create value"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"Innovation means successfully implementing new ideas that create value, so an idea has to work in the real world. Option C is tempting, but innovation is not just invention. Option B describes knowledge management, and option A describes resistance to change."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 166, $official_bank_source${"itemId":"05df8105-3a80-589a-a6df-4c60e0dd9f4d","questionId":"cdeee101-f49e-5cef-bcb9-1395b0449e45","sourceKey":"bank:ENT211:ENT211-W04-004","payload":{"prompt":"Which statement best captures the difference between innovation and invention?","options":["Invention creates value while innovation only generates ideas","Innovation is about making an idea work in the real world, not just inventing it","Innovation and invention mean exactly the same thing","Invention is the marketing of an idea while innovation is its design"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"Innovation goes beyond invention: it is about making an idea work in the real world so that it creates value. Option A reverses the relationship, and option C ignores the clear point that innovation is not just invention. Option D invents a distinction that has nothing to do with value creation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 167, $official_bank_source${"itemId":"726c02e1-6b6d-5763-9895-d060146142e4","questionId":"cccf2b42-cbcf-5eb7-ab4e-e06a1e1bfa82","sourceKey":"bank:ENT211:ENT211-W04-005","payload":{"prompt":"Which of the following is one of the four dimensions of innovation?","options":["Legal innovation","Political innovation","Organisational innovation","Financial innovation"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"The four dimensions of innovation are product, process, market and organisational innovation, so organisational innovation is a correct member. Options A, B and D sound reasonable but are not among the four dimensions."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 168, $official_bank_source${"itemId":"f46130db-32b5-5068-be60-0b4696d72f2a","questionId":"73b2d316-8ad2-5f0f-b3fb-6c3a70ec1c7d","sourceKey":"bank:ENT211:ENT211-W04-006","payload":{"prompt":"Which of the following is NOT one of the four dimensions of innovation?","options":["Market innovation","Product innovation","Refreeze innovation","Process innovation"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"Refreeze is the final stage of Kurt Lewin's change model, not a dimension of innovation. Options A, B and D are all genuine dimensions, alongside organisational innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 169, $official_bank_source${"itemId":"72d7af21-3cf6-5dca-917d-3ac576a04600","questionId":"9608384b-bfcb-5d4b-9560-5fc04d9c8779","sourceKey":"bank:ENT211:ENT211-W04-007","payload":{"prompt":"How many dimensions of innovation are identified?","options":["Three","Two","Four","Five"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"Innovation has four dimensions: product, process, market and organisational. Option A (three) is the number of stages in Kurt Lewin's change model, which is easy to confuse. Options B and D do not match the four listed dimensions."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 170, $official_bank_source${"itemId":"152c0bd4-6f17-5d7f-b963-716a64ac2c94","questionId":"7cf65e5b-a864-5e51-8adf-85eaca92b05e","sourceKey":"bank:ENT211:ENT211-W04-008","payload":{"prompt":"Product innovation is mainly concerned with","options":["Who you sell to and how you reach them","What you sell","How you create it","How you structure and manage your company"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"Product innovation focuses on what you sell, that is, the product or service itself. Option C describes process innovation, option A describes market innovation, and option D describes organisational innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 171, $official_bank_source${"itemId":"e3905829-e184-5d81-a44d-8bc2c3e596a8","questionId":"3096441b-74a7-508d-9cda-1944a6c1d480","sourceKey":"bank:ENT211:ENT211-W04-009","payload":{"prompt":"The dimension of innovation summed up as \"How you create it\" is","options":["Product innovation","Organisational innovation","Process innovation","Market innovation"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"Process innovation is about how you create a product or deliver it. Option A is about what you sell, option D is about who you sell to and how you reach them, and option B is about how the company is structured and managed."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 172, $official_bank_source${"itemId":"86e8a8ea-d88d-5750-a236-2813561ba696","questionId":"291d9741-00a2-50a1-a574-e36aae9c7389","sourceKey":"bank:ENT211:ENT211-W04-010","payload":{"prompt":"\"Who you sell to and how you reach them\" describes which dimension of innovation?","options":["Process innovation","Market innovation","Organisational innovation","Product innovation"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"Market innovation is about who you sell to and how you reach them, such as finding new target customers or new packaging. Option A is about how the product is created, option D is about what is sold, and option C is about company structure and management."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 173, $official_bank_source${"itemId":"1b55e805-20f8-5534-a52a-5db11fcb7a76","questionId":"e82a95ba-020d-5c21-a5fe-7800460ace18","sourceKey":"bank:ENT211:ENT211-W04-011","payload":{"prompt":"\"How you structure and manage your company\" refers to","options":["Process innovation","Market innovation","Organisational innovation","Product innovation"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"Organisational innovation concerns how a company is structured and managed, including its workplace culture. Option B is about customers and reach, option A is about how products are made or delivered, and option D is about what is sold."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 174, $official_bank_source${"itemId":"e157acfd-f9dc-5477-b6e1-a60448f4568b","questionId":"954f8fd4-314f-5a14-a944-9873626ec2eb","sourceKey":"bank:ENT211:ENT211-W04-012","payload":{"prompt":"Product innovation involves","options":["Improving a product or creating a totally new one","Finding new markets or packaging for existing products","Changing workplace culture or structure","Changing how a product is created or delivered to lower cost"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"Product innovation means improving an existing product or creating a totally new one. Option D is process innovation, option B is market innovation, and option C is organisational innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 175, $official_bank_source${"itemId":"09f1a01d-27a0-56b0-9733-429fda0522ff","questionId":"25e1aafe-a552-5dda-8b99-acb06b9ebbd0","sourceKey":"bank:ENT211:ENT211-W04-013","payload":{"prompt":"Process innovation is defined as","options":["Finding new markets or packaging for existing products","Changing how a product is created or delivered to lower cost or increase speed","Changing workplace culture or structure","Improving a product or creating a totally new one"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"Process innovation changes how a product is created or delivered, with the aim of lowering cost or increasing speed. Option D is product innovation, option A is market innovation, and option C is organisational innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 176, $official_bank_source${"itemId":"6d1cafdb-5836-5f02-8385-b32a14efd778","questionId":"fe4b39df-9adb-50b3-a411-a8f6854c5a99","sourceKey":"bank:ENT211:ENT211-W04-014","payload":{"prompt":"Finding new markets or packaging for existing products is called","options":["Organisational innovation","Process innovation","Product innovation","Market innovation"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"Market innovation means finding new markets or new packaging for products that already exist, which is why it is linked to new targets. Option C changes the product itself, option B changes how it is made or delivered, and option A changes the company's culture or structure."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 177, $official_bank_source${"itemId":"1841a1c8-268e-50b8-8334-c4e0146c5972","questionId":"e3f9cac3-2546-5b5f-b669-454004c3a8b7","sourceKey":"bank:ENT211:ENT211-W04-015","payload":{"prompt":"Changing workplace culture or structure is an example of","options":["Organisational innovation","Market innovation","Product innovation","Process innovation"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"Organisational innovation, also described as new structures, involves changing workplace culture or structure. Option D is about production and delivery methods, option B is about new markets or packaging, and option C is about the product itself."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 178, $official_bank_source${"itemId":"deef7cfc-2c58-556a-bb67-dc13cc606f65","questionId":"e52bf143-f7e7-5455-b73b-13d1b22b4a03","sourceKey":"bank:ENT211:ENT211-W04-016","payload":{"prompt":"Market innovation is also described by which label?","options":["New Targets","New Processes","New Products","New Structures"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"Market innovation is labelled \"New Targets\" because it is about reaching new customers or markets. Option D, \"New Structures\", is the label for organisational innovation. Options B and C are not labels used for market innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 179, $official_bank_source${"itemId":"3798811f-04f5-5206-ada7-af81ce2b629e","questionId":"4de3fe5e-1424-5a6a-b5b1-5712712787d8","sourceKey":"bank:ENT211:ENT211-W04-017","payload":{"prompt":"Organisational innovation is also described by which label?","options":["New Packaging","New Targets","New Structures","New Markets"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"Organisational innovation is labelled \"New Structures\" since it changes workplace culture or structure. Option B, \"New Targets\", belongs to market innovation, and options A and D are also features of market innovation, not organisational innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 180, $official_bank_source${"itemId":"a94c680d-f51d-5c95-b8fa-401ce2cffa99","questionId":"2b3b936d-03d5-5ee5-92ac-be552a89635c","sourceKey":"bank:ENT211:ENT211-W04-018","payload":{"prompt":"Cowrywise and Piggyvest taking the traditional wooden Kolo (savings box) and moving it to an app with interest rates is an example of","options":["Organisational innovation","Product innovation","Process innovation","Market innovation"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"Cowrywise and Piggyvest improved the savings product itself, turning the wooden Kolo into an app that pays interest, which is product innovation. Option C would be about delivery logistics, option D about new markets or packaging, and option A about workplace culture."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 181, $official_bank_source${"itemId":"5a2408e3-5730-5bcb-9c8b-3f432e49e935","questionId":"76429c9b-807c-5d99-bec8-73c91d9603fa","sourceKey":"bank:ENT211:ENT211-W04-019","payload":{"prompt":"Which of the following is given as an example of product innovation?","options":["Chowdeck and Glovo","Andela and tech startups","Cowrywise and Piggyvest","The sachet economy for Peak Milk"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"Cowrywise and Piggyvest are the product innovation example because they turned the Kolo savings box into an interest-paying app. Option A illustrates process innovation, option D illustrates market innovation, and option B illustrates organisational innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 182, $official_bank_source${"itemId":"3955f982-a781-597f-b264-8aa76880fa2f","questionId":"57122ffb-9304-5950-a2aa-232ebcbc0db3","sourceKey":"bank:ENT211:ENT211-W04-020","payload":{"prompt":"In the product innovation example, what traditional item did Cowrywise and Piggyvest move to an app?","options":["The kerosene stove","The Okada motorcycle","The big tin of Peak Milk","The wooden Kolo (savings box)"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"Cowrywise and Piggyvest took the traditional wooden Kolo, a savings box, and moved it to an app with interest rates. Option C belongs to the sachet economy example, while options A and B come from the change examples about gas cylinders and the Lagos Okada ban."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 183, $official_bank_source${"itemId":"6ff0b08c-2fae-53ef-936e-d44cc865118f","questionId":"eda00a2b-b686-5a8d-ae5d-cdeb7619db40","sourceKey":"bank:ENT211:ENT211-W04-021","payload":{"prompt":"Chowdeck and Glovo using bikes and bicycles to deliver within 30 minutes in Lagos traffic illustrates","options":["Process innovation","Market innovation","Product innovation","Organisational innovation"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"The innovation by Chowdeck and Glovo is the logistics process of delivering with bikes and bicycles to beat Lagos traffic, which is process innovation. Option C is tempting because food delivery is a service, but the new thing here is how it is delivered, not what is sold. Options B and D deal with new markets and workplace structure."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 184, $official_bank_source${"itemId":"5eb1773a-54ca-599f-bba9-0d685f2bd147","questionId":"4cb3b13a-2fb4-52e4-8d28-584d2e2729d9","sourceKey":"bank:ENT211:ENT211-W04-022","payload":{"prompt":"In the Chowdeck and Glovo example, the logistics process using bikes/bicycles allowed delivery in Lagos traffic within","options":["60 minutes","15 minutes","45 minutes","30 minutes"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"The bike and bicycle logistics process allowed Chowdeck and Glovo to deliver within 30 minutes despite Lagos traffic. Options A, B and C are not the time stated for this example."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 185, $official_bank_source${"itemId":"5a1d7fef-5dfb-578d-b832-54b37369cb2c","questionId":"b1395c84-b78b-5260-9c34-d2ecb0f11ced","sourceKey":"bank:ENT211:ENT211-W04-023","payload":{"prompt":"For Chowdeck and Glovo, what exactly was the innovation?","options":["Allowing staff to work from home","Selling food in smaller sachets to low-income earners","Creating a totally new type of food","The logistics process of using bikes/bicycles to beat Lagos traffic"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"The innovation was the logistics process: using bikes and bicycles so deliveries could get through Lagos traffic quickly. Option C would be product innovation, option B resembles the sachet economy (market innovation), and option A resembles the Andela example (organisational innovation)."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 186, $official_bank_source${"itemId":"dee5e621-9193-5b0f-a0f4-77c6d5e46b9a","questionId":"71bda471-331a-5845-a2b3-3f79cefbbbaa","sourceKey":"bank:ENT211:ENT211-W04-024","payload":{"prompt":"Companies selling Peak Milk in sachets because most Nigerians cannot buy big tins is an example of","options":["Market innovation","Process innovation","Organisational innovation","Product innovation"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"The sachet economy is market innovation because the milk stayed the same, but new packaging opened a massive market of low-income earners. Option D is tempting, yet the product itself was not changed. Option B concerns how products are made or delivered, and option C concerns workplace culture."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 187, $official_bank_source${"itemId":"545bac58-e209-5bf7-92ef-a566e0899a79","questionId":"4f8b3e70-f07c-5afe-b67d-5df3cb81c0fb","sourceKey":"bank:ENT211:ENT211-W04-025","payload":{"prompt":"Which of the following is given as an example of market innovation?","options":["Andela and tech startups","The \"Sachet Economy\"","Cowrywise and Piggyvest","Chowdeck and Glovo"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"The sachet economy is the market innovation example, where packaging Peak Milk in sachets opened a market for low-income earners. Option C is product innovation, option D is process innovation, and option A is organisational innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 188, $official_bank_source${"itemId":"9cd73d89-6542-5e0d-937c-a3dc8ec05734","questionId":"837ba570-7845-55a1-b109-bde228f70a3d","sourceKey":"bank:ENT211:ENT211-W04-026","payload":{"prompt":"In the sachet economy example, innovating the packaging opened a massive market for which group?","options":["Large supermarkets","Government agencies","Foreign tourists","Low-income earners"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"Most Nigerians could not buy big tins of Peak Milk, so sachet packaging opened a massive market for low-income earners. Options A, B and C are not the group this packaging change reached."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 189, $official_bank_source${"itemId":"a0b3119f-17cf-575d-8170-6a62e11b0e85","questionId":"ff81a830-3807-5372-8060-9c06f209d834","sourceKey":"bank:ENT211:ENT211-W04-027","payload":{"prompt":"Andela and other tech startups moving from the \"Oga must see you at your desk\" mentality to a results-based culture where staff can work from home illustrates","options":["Product innovation","Organisational innovation","Process innovation","Market innovation"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"Shifting from desk-watching to a results-based, work-from-home culture is a change in workplace culture and structure, which is organisational innovation. Option C is about how products are produced or delivered, option D is about new markets or packaging, and option A is about the product itself."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 190, $official_bank_source${"itemId":"0680716a-d1eb-5feb-9b61-0349a66efeec","questionId":"471acb48-30c2-564a-92ac-4335fb2fa277","sourceKey":"bank:ENT211:ENT211-W04-028","payload":{"prompt":"Which of the following is given as an example of organisational innovation?","options":["Andela and tech startups","Chowdeck and Glovo","The \"Sachet Economy\"","Cowrywise and Piggyvest"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"Andela and tech startups are the organisational innovation example, moving to a results-based culture where staff can work from home. Option C is market innovation, option B is process innovation, and option D is product innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 191, $official_bank_source${"itemId":"c251f741-70da-525d-b102-4699410e6516","questionId":"79454679-9f3f-59a1-b413-ae27a6084df9","sourceKey":"bank:ENT211:ENT211-W04-029","payload":{"prompt":"In the organisational innovation example, tech startups moved away from the \"Oga must see you at your desk\" mentality to","options":["A culture where the boss checks attendance more strictly","Selling products in smaller packs","A results-based culture where you can work from home","Delivering products by bikes to beat traffic"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"Andela and tech startups replaced the \"Oga must see you at your desk\" mentality with a results-based culture that allows working from home. Option A is the opposite of that shift, while options B and D describe the process and market innovation examples."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 192, $official_bank_source${"itemId":"74c4d29e-8443-529f-9753-28de8975b213","questionId":"329fc185-197b-5839-be1b-7169f78ba9c2","sourceKey":"bank:ENT211:ENT211-W04-030","payload":{"prompt":"A Lagos detergent maker notices that many customers cannot afford its 1kg bag, so it starts selling the same detergent in small single-use packs. This is best described as","options":["Organisational innovation","Product innovation","Process innovation","Market innovation"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"Selling the same detergent in smaller packs to reach customers who could not afford the big bag is market innovation, just like the sachet economy. Option B is tempting, but the detergent itself is unchanged. Option C would involve changing how it is made or delivered, and option A would involve changing company culture or structure."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 193, $official_bank_source${"itemId":"f0d76e46-11bb-526a-b523-851ca6531a83","questionId":"19f4673f-ea17-566f-aa0e-e1d9ab988170","sourceKey":"bank:ENT211:ENT211-W04-031","payload":{"prompt":"A pharmacy chain in Abuja switches from van deliveries to motorcycle riders so that orders reach customers faster and at lower cost. Which dimension of innovation is this?","options":["Process innovation","Market innovation","Organisational innovation","Product innovation"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"Changing how products are delivered in order to increase speed and lower cost is process innovation, as in the food-delivery example where bikes beat Lagos traffic. Option B would mean finding new markets or packaging, option D would mean changing the medicines themselves, and option C would mean changing workplace culture or structure."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 194, $official_bank_source${"itemId":"9867ee55-9211-545f-bb9d-09184bbf6595","questionId":"16bd14a3-f999-5962-8c61-ee7f332034ed","sourceKey":"bank:ENT211:ENT211-W04-032","payload":{"prompt":"A Nigerian bank lets its staff work from home and judges them by the results they deliver rather than by the hours they sit at their desks. This is an example of","options":["Product innovation","Organisational innovation","Market innovation","Process innovation"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"Changing workplace culture to a results-based, work-from-home model is organisational innovation, as in the Andela example. Option D concerns how products are created or delivered, option C concerns new markets or packaging, and option A concerns what is sold."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 195, $official_bank_source${"itemId":"55778ca8-0dcd-5809-8600-b30a6fe83953","questionId":"5a5516aa-55c8-5f69-88d5-74015e548554","sourceKey":"bank:ENT211:ENT211-W04-033","payload":{"prompt":"A fintech in Ibadan turns the traditional esusu savings practice into a mobile app that pays interest on savings. This is closest to","options":["Organisational innovation","Product innovation","Market innovation","Process innovation"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"Turning a traditional savings method into a new app product with interest is product innovation, much like Cowrywise and Piggyvest digitising the Kolo. Option C would be about new markets or packaging for an existing product, option A about workplace culture, and option D about lowering cost or speeding up production or delivery."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 196, $official_bank_source${"itemId":"ca935780-3682-5b10-96f5-9baff7e072bb","questionId":"716668ea-4c77-5f22-82ab-2fa58c7c5c98","sourceKey":"bank:ENT211:ENT211-W04-034","payload":{"prompt":"The systematic process of creating, sharing, using and managing an organization's knowledge and information is called","options":["Process innovation","Organisational innovation","Change management","Knowledge Management (KM)"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"Knowledge Management (KM) is the systematic process of creating, sharing, using and managing an organization's knowledge and information. Option C is about planning change, while options A and B are dimensions of innovation rather than the management of knowledge."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 197, $official_bank_source${"itemId":"d02db347-5564-5070-b429-4a36659ed9a0","questionId":"9c580967-7ae1-5cb3-be2b-f0949a91ab73","sourceKey":"bank:ENT211:ENT211-W04-035","payload":{"prompt":"Knowledge Management (KM) involves","options":["Finding new markets or packaging for existing products","Developing and marketing breakthrough products for customers","Creating, sharing, using and managing an organization's knowledge and information","Unfreezing, changing and refreezing staff behaviour"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"Knowledge Management is the systematic process of creating, sharing, using and managing an organization's knowledge and information. Option D describes Kurt Lewin's change model, option B is the McKinsey definition of innovation, and option A is market innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 198, $official_bank_source${"itemId":"5671c080-a210-5764-8993-67787edfc99a","questionId":"cf3f479e-4108-5746-bd18-4d3416837068","sourceKey":"bank:ENT211:ENT211-W04-036","payload":{"prompt":"The statement \"Innovation doesn't happen in a vacuum\" means that innovation is","options":["Fueled by knowledge","Fueled only by government policy","Independent of any information","Caused mainly by luck"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"Innovation does not happen in a vacuum because it is fueled by knowledge. Options B, C and D ignore this link between knowledge and innovation, which is the whole point of knowledge management."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 199, $official_bank_source${"itemId":"bba39eda-3243-52fa-81ad-c9d2b38bbed9","questionId":"27369b43-077d-5633-b2c2-89ba9d228183","sourceKey":"bank:ENT211:ENT211-W04-037","payload":{"prompt":"In the pyramid linking knowledge to innovation, \"Data\" refers to","options":["Application","Creating value","Context","Raw facts"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"Data is the base of the pyramid and means raw facts, such as \"Rice is 80k per bag\". Option C describes information, option A describes knowledge, and option B describes innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 200, $official_bank_source${"itemId":"e8d5ff62-0a06-5f20-97bc-17283470b21a","questionId":"a21fa865-5d94-5bd3-a809-0c190549fcb4","sourceKey":"bank:ENT211:ENT211-W04-038","payload":{"prompt":"In the pyramid linking knowledge to innovation, \"Information\" is described as","options":["Context","Raw facts","Creating value from knowledge","Application"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"Information gives context to data, for example explaining that rice prices rose because of the border closure. Option B is data, option D is knowledge, and option C is innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 201, $official_bank_source${"itemId":"df69eddb-a31c-59c2-8544-db5345136f8f","questionId":"3b0c9fa2-16ad-5e3b-9a59-51908ccc9c1e","sourceKey":"bank:ENT211:ENT211-W04-039","payload":{"prompt":"In the pyramid linking knowledge to innovation, \"Knowledge\" is described as","options":["Context","Raw facts","Measurements","Application"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"Knowledge is about application, meaning deciding what to do, such as switching to local rice or cassava alternatives. Option A is information and option B is data. Option C is a label at the base of the DIKW diagram, not the meaning of knowledge."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 202, $official_bank_source${"itemId":"8c1da3c1-c36c-5079-8095-5d4ffbb6dc06","questionId":"26eab0c3-6b68-5655-bf3e-cc59b47abc32","sourceKey":"bank:ENT211:ENT211-W04-040","payload":{"prompt":"In the pyramid linking knowledge to innovation, the level described as \"Creating value from that knowledge\" is","options":["Data","Knowledge","Innovation","Information"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"Innovation is the top of this pyramid and means creating value from knowledge. Option D is context, option A is raw facts, and option B is the application of information, which comes just before innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 203, $official_bank_source${"itemId":"fbf38950-7832-52e3-8266-90a777e445a9","questionId":"efc93a78-d73f-5216-abd7-b5827b09a6b0","sourceKey":"bank:ENT211:ENT211-W04-041","payload":{"prompt":"The statement \"Rice is 80k per bag\" is an example of","options":["Innovation","Information","Knowledge","Data"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"\"Rice is 80k per bag\" is a raw fact with no explanation or decision attached, so it is data. Option B would add context, such as why the price rose. Option C would be a decision on what to do, and option A would be creating value from that decision."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 204, $official_bank_source${"itemId":"c055cb3b-9ff9-54eb-998a-b8accc41578c","questionId":"39655bcc-71dc-54ef-9494-09ff88d8d402","sourceKey":"bank:ENT211:ENT211-W04-042","payload":{"prompt":"The statement \"Rice price went up because of the border closure\" is an example of","options":["Information","Knowledge","Innovation","Data"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"This statement explains why the price changed, giving context to the raw fact, so it is information. Option D would be the bare price alone. Option B would be a decision such as switching to local rice, and option C would be creating value from that knowledge."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 205, $official_bank_source${"itemId":"0ec08f60-ea5a-5b3b-a2fa-771e995e7929","questionId":"00bc17c2-f808-5da1-b6bc-43a6fb0daab7","sourceKey":"bank:ENT211:ENT211-W04-043","payload":{"prompt":"A trader concluding \"I should switch to selling local rice or cassava alternatives\" is an example of","options":["Information","Knowledge","Opinion","Data"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"Knowledge is the application of information, and deciding to switch to local rice or cassava alternatives is a trader applying what he knows. Option A, information, is the context of why the price rose, and option D, data, is the raw price itself. Option C, opinion, is not a level of the knowledge pyramid at all."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 206, $official_bank_source${"itemId":"f139459e-e28f-535f-9888-99d3056eefc3","questionId":"3ca59e15-f5b5-55af-892d-06d4b6c77b15","sourceKey":"bank:ENT211:ENT211-W04-044","payload":{"prompt":"In the information example, the rice price went up because of","options":["Fuel subsidy removal","The border closure","The dollar rate","The Okada ban"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"The information example explains that the rice price went up because of the border closure. Options A and C are external shocks mentioned in the case on adapting to change, and option D is from the Lagos change example."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 207, $official_bank_source${"itemId":"5dd1e21a-cb66-54e6-807a-9a60c4cb1074","questionId":"c10ee39c-2032-5340-863a-614fe2221ea9","sourceKey":"bank:ENT211:ENT211-W04-045","payload":{"prompt":"Which order correctly moves up the pyramid linking knowledge to innovation, from bottom to top?","options":["Data, Knowledge, Information, Innovation","Knowledge, Information, Data, Innovation","Information, Data, Knowledge, Innovation","Data, Information, Knowledge, Innovation"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"The pyramid starts with data (raw facts), adds context to become information, applies it as knowledge, and finally creates value as innovation. Options A, B and C mix up the order, for example by placing knowledge before information."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 208, $official_bank_source${"itemId":"c5d2e99b-67e3-5b22-adc7-906e2469ef65","questionId":"8be30d32-3cd4-5900-b66e-7f5dc07f8adb","sourceKey":"bank:ENT211:ENT211-W04-046","payload":{"prompt":"Every trader in Balogun market has data (prices). What separates the innovators among them?","options":["They avoid using market data altogether","They use that data to predict what will sell next Christmas","They keep their prices the same all year","They collect more price lists than other traders"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"Innovators move beyond simply having data and use it to predict what will sell next Christmas, turning data into knowledge and value. Option D is still just gathering data. Options A and C ignore the use of data entirely."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 209, $official_bank_source${"itemId":"a075ca22-e5ec-50d6-8ded-adc0f08df1a0","questionId":"a59affc1-85c7-5808-88ae-5281305d3b19","sourceKey":"bank:ENT211:ENT211-W04-047","payload":{"prompt":"In the DIKW Knowledge Management Model, the level at the top of the pyramid is","options":["Information","Data","Knowledge","Wisdom"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"In the DIKW model, the levels run from data to information to knowledge, with wisdom at the top. Option C sits just below wisdom, while options A and B are lower levels of the pyramid."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 210, $official_bank_source${"itemId":"7aaa46de-4141-51c1-ad78-b220ab8e1527","questionId":"3ef98439-a6be-53fb-81ab-416b733865f3","sourceKey":"bank:ENT211:ENT211-W04-048","payload":{"prompt":"In the DIKW Knowledge Management Model, the letters D-I-K-W stand for","options":["Decision, Information, Knowledge, Wealth","Data, Innovation, Knowledge, Work","Data, Information, Knowledge, Wisdom","Data, Insight, Know-how, Value"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"DIKW stands for Data, Information, Knowledge and Wisdom, the levels shown in the knowledge management pyramid. Option B swaps in innovation and work, and options A and D use words that are not part of the model."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 211, $official_bank_source${"itemId":"12122a83-6a8e-51e0-99fc-88cb9ae70f91","questionId":"edb7fe10-e5c7-5d20-b354-e3fe811dbf83","sourceKey":"bank:ENT211:ENT211-W04-049","payload":{"prompt":"Humans are said to be naturally averse to change because they prefer","options":["\"The grass that is greener\"","\"The risk of the unknown\"","\"The Devil they know\"","\"The new way of doing things\""],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"People are naturally averse to change and prefer \"the Devil they know\", meaning the familiar way even when it is not ideal. Options A, B and D all suggest a preference for something new, which is the opposite of resistance to change."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 212, $official_bank_source${"itemId":"5f57ce97-8607-52fc-9d40-bac3d677d975","questionId":"3ae5c193-e2b8-5544-a6c8-08b67d7c53d6","sourceKey":"bank:ENT211:ENT211-W04-050","payload":{"prompt":"Kurt Lewin is known for proposing","options":["The four dimensions of innovation","A 3-stage model for planning change","The definition of innovation as marketing breakthrough products","The DIKW knowledge management pyramid"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"Kurt Lewin proposed a 3-stage model for planning change: Unfreeze, Change and Refreeze. Option A is the framework of product, process, market and organisational innovation, option D is the knowledge management model, and option C is McKinsey's definition of innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 213, $official_bank_source${"itemId":"ccb10776-20a2-565f-b02b-5bf1dea644af","questionId":"2831f962-b603-5a9b-8af8-0cc5960d61d0","sourceKey":"bank:ENT211:ENT211-W04-051","payload":{"prompt":"The correct order of the stages in Kurt Lewin's change model is","options":["Unfreeze, Change, Refreeze","Refreeze, Change, Unfreeze","Change, Unfreeze, Refreeze","Unfreeze, Refreeze, Change"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"Lewin's model starts by unfreezing (realising the old way is bad), then moves through change (the messy transition), and ends with refreezing (making the new way a habit). Options B, C and D place the stages in the wrong order."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 214, $official_bank_source${"itemId":"3d8473a3-4f94-5c98-8ffa-45be3d14f389","questionId":"17269e5b-c9e3-58b0-ab22-9e446ae17a42","sourceKey":"bank:ENT211:ENT211-W04-052","payload":{"prompt":"In Kurt Lewin's model, realizing that the old way of doing things is dangerous or expensive is the","options":["Change stage","Refreeze stage","Unfreeze stage","Pivot stage"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"Unfreeze is the first stage, where people realise the old way, such as kerosene stoves, is dangerous or expensive. Option A is the messy transition to the new way, and option B is making the new way a habit. Option D, the pivot, describes adapting to external change, not a stage of Lewin's model."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 215, $official_bank_source${"itemId":"d0fa8ca9-72d1-5aad-a6f4-e24d0605987f","questionId":"7cd42bdf-6125-5557-b04e-8d9362077b05","sourceKey":"bank:ENT211:ENT211-W04-053","payload":{"prompt":"In Kurt Lewin's model, the messy transition to the new way is the","options":["Refreeze stage","Innovation stage","Change stage","Unfreeze stage"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"The Change stage is the messy transition to the new way, such as switching to gas cylinders. Option D comes before it and is about realising the old way is bad, and option A comes after it and makes the new way a habit. Option B is not one of Lewin's three stages."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 216, $official_bank_source${"itemId":"5e3c1219-9a13-51f7-97e7-f55f1652eb80","questionId":"c16e1fe6-1ad5-5ea2-975e-1aafec6c50d2","sourceKey":"bank:ENT211:ENT211-W04-054","payload":{"prompt":"In Kurt Lewin's model, making the new way the habit is the","options":["Refreeze stage","Adoption stage","Change stage","Unfreeze stage"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"Refreeze is the final stage, where the new way becomes the habit. Option C is the messy transition itself, and option D is realising the old way is dangerous or expensive. Option B is not one of Lewin's three stages."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 217, $official_bank_source${"itemId":"cb0d1efc-3635-5c68-98c1-9198fb389c34","questionId":"f23c1c28-e550-58e5-b2b8-46ccfded8220","sourceKey":"bank:ENT211:ENT211-W04-055","payload":{"prompt":"In Kurt Lewin's model, the messy transition of actually switching from kerosene stoves to gas cylinders belongs to which stage?","options":["Change","Unfreeze","Refreeze","Pivot"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"The Change stage is the messy transition to the new way, such as actually switching to gas cylinders. Option B, Unfreeze, is only the realisation that the old kerosene stoves are dangerous or expensive. Option C, Refreeze, is when the new way becomes the habit, and option D is not one of Lewin's three stages."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 218, $official_bank_source${"itemId":"2753a26a-53f3-599e-9c64-203f263d87de","questionId":"a7623bd4-32ca-5da0-91a7-bf032c2b7e0c","sourceKey":"bank:ENT211:ENT211-W04-056","payload":{"prompt":"When Lagos banned Okadas in certain areas, people had to trek and the situation was chaotic. In Kurt Lewin's model, this chaotic period was the","options":["Planning phase","Refreeze phase","Unfreeze phase","Change phase"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"The chaotic period when people had to trek after the Okada ban was the Change phase, the messy transition to a new way. Option B came later, when people settled into using buses or trekking. Option C is the earlier realisation that the old way is bad, and option A is not one of Lewin's stages."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 219, $official_bank_source${"itemId":"67d2421c-2928-57d5-a4f6-e2836e4c5878","questionId":"fd0fe114-0f15-5029-8af1-b6c20b9e2091","sourceKey":"bank:ENT211:ENT211-W04-057","payload":{"prompt":"After the Lagos Okada ban, people eventually settled into using buses or trekking. In Kurt Lewin's model, this represents","options":["Refreezing","Changing","Unfreezing","Pivoting"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"Settling into buses or trekking as the new normal is refreezing, where the new way becomes the habit. Option B was the earlier chaotic period of transition, and option C is the first stage of realising the old way is bad. Option D is about adapting to external shocks, not a Lewin stage."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 220, $official_bank_source${"itemId":"587e44df-9b1b-5bc7-b107-73de1ac1756b","questionId":"076e76f9-448b-50e2-b382-43e455949c03","sourceKey":"bank:ENT211:ENT211-W04-058","payload":{"prompt":"In Kurt Lewin's approach to planned change, before announcing an innovation an entrepreneur must first","options":["Refreeze people into the new habit","Unfreeze people by convincing them why the old way is bad","Wait for an external shock to force the change","Launch the change and handle resistance later"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"You cannot just announce innovation; you must first unfreeze people by convincing them why the old way is bad. Option A is the last stage, which cannot come first. Option D skips the unfreezing step, and option C confuses planned change with change forced by external shocks."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 221, $official_bank_source${"itemId":"3b767e7b-33c7-5240-9b05-2b82141e5c76","questionId":"373dc997-879f-55b3-9287-32546537bae7","sourceKey":"bank:ENT211:ENT211-W04-059","payload":{"prompt":"A Kano agro-processor holds meetings showing staff how much money and time the old manual record books are costing the company, before introducing new software. Which stage of Kurt Lewin's model is this?","options":["Pivot","Unfreeze","Refreeze","Change"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"Showing people why the old way is costly before introducing the new one is the Unfreeze stage. Option D would be the actual messy switch to the software, and option C would be when using the software becomes the habit. Option A refers to adapting to external change, not a Lewin stage."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 222, $official_bank_source${"itemId":"914226a5-e6bc-5d08-bd05-2a07b34719e5","questionId":"c0945d1c-aa97-5268-9935-ac69be74c3f1","sourceKey":"bank:ENT211:ENT211-W04-060","payload":{"prompt":"Which of the following are given as examples of external shocks that force innovation?","options":["Dollar rate and fuel subsidy removal","Product design and packaging","Data and information","Workplace culture and company structure"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"External shocks such as the dollar rate and fuel subsidy removal come from outside the business and force it to innovate. Option D relates to organisational innovation, option B relates to product and market innovation, and option C are levels of the knowledge pyramid."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 223, $official_bank_source${"itemId":"58a93ab8-803a-54a1-808d-a80f7081d43e","questionId":"86c0c70e-4c21-5f7e-8c60-eb36f11a4984","sourceKey":"bank:ENT211:ENT211-W04-061","payload":{"prompt":"Adapting a business in response to external change is described as","options":["The refreeze","The Kolo","The sachet economy","The pivot"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"Adapting to external change is called the pivot, where outside shocks force a business to innovate. Option A is the last stage of Lewin's planned change model, option C is a market innovation example, and option B is the traditional savings box in the product innovation example."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 224, $official_bank_source${"itemId":"d5c63cf6-bcb3-5fba-9f92-8999824b4202","questionId":"fe04d65f-f7fa-5bf2-9194-46cf0b1eae19","sourceKey":"bank:ENT211:ENT211-W04-062","payload":{"prompt":"In the case study of fuel subsidy removal (2023/2024), what happened to transport costs?","options":["They stayed the same","They halved","They doubled","They tripled"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"The reaction to fuel subsidy removal was that transport costs tripled. Options A, B and C do not match this effect, and the sharp tripling is what pushed companies to innovate."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 225, $official_bank_source${"itemId":"eb2989f7-1451-5470-ac49-315320dfb9e5","questionId":"90158e62-57f0-54c2-9987-049eed546874","sourceKey":"bank:ENT211:ENT211-W04-063","payload":{"prompt":"The fuel subsidy removal case study is dated","options":["2019/2020","2015/2016","2021/2022","2023/2024"],"correctOption":3,"section":"Weeks 4-5: Innovation and Change","explanation":"The case study of fuel subsidy removal covers 2023/2024. Options A, B and C are not the period given for this case."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 226, $official_bank_source${"itemId":"522d9a5d-509c-54f3-92e6-dc72431aabf1","questionId":"9c84e12e-655a-5747-a8a3-193161e21e7d","sourceKey":"bank:ENT211:ENT211-W04-064","payload":{"prompt":"In the fuel subsidy removal case, companies shifting to remote work is classified as","options":["Market change","Data change","Organizational change","Product/Process change"],"correctOption":2,"section":"Weeks 4-5: Innovation and Change","explanation":"Shifting to remote work changes how the company is organised and managed, so it is an organizational change. Option D is how mechanics converting cars to CNG is classified. Options A and B are not the classification given for remote work."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 227, $official_bank_source${"itemId":"8933d76c-2c1a-5dd7-8d9b-d850ed84e140","questionId":"9cb63423-fa1a-556a-a4c1-ba24bba45d69","sourceKey":"bank:ENT211:ENT211-W04-065","payload":{"prompt":"In the fuel subsidy removal case, mechanics converting cars to CNG is classified as","options":["Organizational change","Product/Process change","Market change","Refreeze change"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"Converting cars to CNG changes the product and how it works, so it is classified as product/process change. Option A is the classification for companies shifting to remote work. Options C and D are not used for the CNG example."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 228, $official_bank_source${"itemId":"32036539-9bab-5542-9455-428627fc16dc","questionId":"7eb4e774-d20f-5c2c-8ca9-5b9c9dd849fe","sourceKey":"bank:ENT211:ENT211-W04-066","payload":{"prompt":"Which of the following was NOT an innovation response to fuel subsidy removal?","options":["Providing staff buses","Selling milk in sachets","Shifting to remote work","Converting cars to CNG"],"correctOption":1,"section":"Weeks 4-5: Innovation and Change","explanation":"Selling milk in sachets is the sachet economy example of market innovation, not a response to fuel subsidy removal. Options A, C and D were all responses: remote work, staff buses and CNG conversion."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 229, $official_bank_source${"itemId":"5a8e1cf9-94db-5c9e-987e-48d911d91cff","questionId":"47d5046b-0cc1-55ec-949d-0f38c0730743","sourceKey":"bank:ENT211:ENT211-W04-067","payload":{"prompt":"The key lesson of the fuel subsidy removal case is that","options":["Change is not always voluntary; sometimes the economy forces you to innovate","Innovation should always wait until the economy is stable","Only large companies can respond to economic shocks","External shocks reduce the need for innovation"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"The lesson is that change is not always voluntary, because sometimes the economy forces you to innovate. Option B and option D contradict the idea that shocks force innovation, and option C ignores that even mechanics innovated by converting cars to CNG."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 230, $official_bank_source${"itemId":"870c88fb-89e3-52a2-bc84-d3c8ad120e27","questionId":"d8859ce5-1ad5-53a5-8d2b-39acf66edc4b","sourceKey":"bank:ENT211:ENT211-W04-068","payload":{"prompt":"After a sharp fall in the naira against the dollar, a Lagos fashion brand that imported fabric switches to locally woven aso-oke to survive. This best illustrates","options":["Adapting to external change (the pivot)","Knowledge management","Refreezing an old habit","The sachet economy"],"correctOption":0,"section":"Weeks 4-5: Innovation and Change","explanation":"A sudden dollar rate shock forcing the brand to change its inputs is an example of adapting to external change, or pivoting. Option C is the final stage of Lewin's planned change, option B is managing organisational knowledge, and option D is a market innovation example about packaging."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 231, $official_bank_source${"itemId":"cc1f52c4-a5c8-506c-9c7b-a188471d16d0","questionId":"1d41165d-4315-5f25-83ab-750ee20c6c1a","sourceKey":"bank:ENT211:ENT211-W06-001","payload":{"prompt":"Which of the following is a stated learning outcome of the Enterprise Formation (Business Plan) topic in ENT 211?","options":["Calculate the market share of a new product","Design a national policy for small businesses","Develop the outline of a simple business plan","Prepare audited financial statements for a public company"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"One of the outcomes of studying enterprise formation is being able to develop the outline of a simple business plan, alongside identifying ownership forms in Nigeria and weighing their advantages and disadvantages. Options D, B and A sound like business tasks, but none of them is one of the outcomes of this topic."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 232, $official_bank_source${"itemId":"efed94fb-726e-5bd9-92da-d6237157b943","questionId":"45723bc7-d140-562d-861f-9cb8b7018b3f","sourceKey":"bank:ENT211:ENT211-W06-002","payload":{"prompt":"Which of the following is NOT one of the learning outcomes of the Enterprise Formation (Business Plan) topic?","options":["Identify the different forms of business ownership in Nigeria","Develop the outline of a simple business plan","Register a business on the stock exchange","Evaluate the advantages and disadvantages of each ownership type"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Listing a business on the stock exchange is not one of the outcomes of this topic. The three real outcomes are identifying the forms of business ownership in Nigeria (option A), evaluating the advantages and disadvantages of each ownership type (option D) and developing the outline of a simple business plan (option B)."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 233, $official_bank_source${"itemId":"40efe43f-996d-58d2-be07-9c3ede1eaf71","questionId":"08f64afd-dbec-5bea-a541-63ba8f3c1281","sourceKey":"bank:ENT211:ENT211-W06-003","payload":{"prompt":"A strategic roadmap detailing a company's goals and the methods to achieve them is called a","options":["revenue model","SWOT analysis","business plan","executive summary"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A business plan is the strategic roadmap that sets out a company's goals and how it will reach them. A revenue model (option A) only explains how the business makes money, a SWOT analysis (option B) is one section of the plan, and the executive summary (option D) is just the summary of the plan."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 234, $official_bank_source${"itemId":"dbc42dbc-d17e-5174-84af-9dd17cf9dc6b","questionId":"21357843-7dba-5fd2-bd63-a1765655fc78","sourceKey":"bank:ENT211:ENT211-W06-004","payload":{"prompt":"The definition of a business plan as 'a strategic roadmap detailing a company's goals and the methods to achieve them' is credited to","options":["McKinsey (2022)","World Bank (2020)","SMEDAN (2017)","Bank of America (2025)"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"This definition of a business plan is credited to Bank of America (2025). McKinsey (2022) in option A is linked to the definition of innovation, while SMEDAN (2017) and the World Bank (2020) in options C and B are linked to how enterprises are classified by size."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 235, $official_bank_source${"itemId":"0ee6d72c-4e38-5448-8b39-18cc4909fc29","questionId":"370641d1-2df9-54b4-9380-da40a8cb250c","sourceKey":"bank:ENT211:ENT211-W06-005","payload":{"prompt":"In ENT 211, a business plan is best described as","options":["a strategic roadmap detailing a company's goals and the methods to achieve them","a record of a company's past profits and losses","an agreement in which partners share assets, profits and liabilities","a legal certificate showing that a business has been registered"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A business plan looks forward: it is a strategic roadmap of a company's goals and the methods for achieving them. Option D describes a registration certificate, option B describes past financial records, and option C is closer to the definition of a general partnership."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 236, $official_bank_source${"itemId":"3d78c36d-59be-56db-bd4e-38c0b27020c0","questionId":"4a34cb86-5b9b-579e-950c-82a65d84ef4b","sourceKey":"bank:ENT211:ENT211-W06-006","payload":{"prompt":"Which of the following statements about a business plan is correct?","options":["It is a foundational roadmap for the founder, not just a document for investors","It is needed only when a business wants to attract investors","It must run to at least 50 pages to be useful","It should be written only after the business starts making profit"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A business plan is not just for investors; it is the founder's foundational roadmap for thinking through every step. Option B is the exact idea being rejected, option C is wrong because you do not need 50 pages, and option D is wrong because the plan guides the business from the start."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 237, $official_bank_source${"itemId":"2773749c-820c-53b5-9692-5c52f919b9fe","questionId":"83576d80-9f47-51cc-a86e-694990051070","sourceKey":"bank:ENT211:ENT211-W06-007","payload":{"prompt":"Tunde has a business idea but feels he must write a 50-page plan before he can start. The best advice for him is to","options":["copy a long plan from an existing company","start with a clear, practical and brief mini plan","wait until an investor asks him for a full plan","skip planning and fix weaknesses as they come"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A beginner does not need 50 pages; the advice is to start with a clear, practical and brief mini plan. Option C is wrong because a plan is not just for investors, option A does not make him think through his own steps, and option D misses the point that a plan helps you spot weaknesses early."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 238, $official_bank_source${"itemId":"9c1962c9-6fb5-511f-a78d-dc1b5bd96999","questionId":"3c7ca203-c030-526a-9dd3-2b340842dc5a","sourceKey":"bank:ENT211:ENT211-W06-008","payload":{"prompt":"Which of the following is NOT stated as something a business plan helps an entrepreneur to do?","options":["Align the team","Guarantee that investors will fund the business","Think through every step of the business","Identify weaknesses early"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A business plan forces you to think through every step, identify weaknesses early and align your team, so options C, D and A are all stated benefits. Nothing can guarantee investor funding, and the plan is described as more than just a document for investors."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 239, $official_bank_source${"itemId":"33e35303-1674-5735-acaa-bf8a750002e6","questionId":"6db31672-5fce-5f78-a1db-bafee689ef7f","sourceKey":"bank:ENT211:ENT211-W06-009","payload":{"prompt":"How many core components make up a simple business plan in ENT 211?","options":["Ten","Six","Seven","Eight"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A simple business plan has eight core components: Executive Summary, Company Description, Business Opportunity, Competitor Analysis, SWOT Analysis, Revenue Model, Financial Projection and Team. Seven (option C) is the number of stages in the Swift Clean case study, which is easy to mix up with this list."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 240, $official_bank_source${"itemId":"a77f7ae5-5156-5b58-b2e1-837cb0f3420f","questionId":"6ae0c777-f473-5e1e-bde3-c5299e11b3bd","sourceKey":"bank:ENT211:ENT211-W06-010","payload":{"prompt":"In a simple business plan, the component that gives a 'summary of the plan' is the","options":["Financial Projection","Company Description","Team","Executive Summary"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The Executive Summary is a summary of the whole plan. The Company Description (option B) explains what the company does, Team (option C) covers how the company is structured and managed, and Financial Projection (option A) predicts the company's growth."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 241, $official_bank_source${"itemId":"7fd49f47-4771-5c03-9de7-8a68e3dd3152","questionId":"53d6f851-c900-5487-aac5-9f98518ae3b2","sourceKey":"bank:ENT211:ENT211-W06-011","payload":{"prompt":"The business plan component that answers the question 'What does your company do?' is the","options":["Company Description","Business Opportunity","Executive Summary","Revenue Model"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The Company Description explains what the company does. The Executive Summary (option C) summarises the whole plan, the Business Opportunity (option B) is about market potential, and the Revenue Model (option D) explains how the business will make money."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 242, $official_bank_source${"itemId":"4581ac61-c4a9-5040-91e9-1f4efa00cd6c","questionId":"e56dd28d-fa48-5249-8a6b-075cde65f2d0","sourceKey":"bank:ENT211:ENT211-W06-012","payload":{"prompt":"The business plan component that answers the question 'What is the market potential?' is the","options":["Company Description","Competitor Analysis","Financial Projection","Business Opportunity"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The Business Opportunity section shows the market potential for the business. Competitor Analysis (option B) shows what makes you stand out, Financial Projection (option C) predicts the company's growth, and Company Description (option A) explains what the company does."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 243, $official_bank_source${"itemId":"75fc48ef-3942-581b-a890-b3fbf03cf5ee","questionId":"050cb883-f31e-5547-92c5-8cf1cd3db71a","sourceKey":"bank:ENT211:ENT211-W06-013","payload":{"prompt":"The business plan component that answers the question 'What makes you stand out?' is the","options":["Competitor Analysis","Business Opportunity","Executive Summary","Team"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Competitor Analysis compares a business with its rivals to answer 'What makes you stand out?'. Option D, Team, covers how you structure and manage your company, option B, Business Opportunity, covers market potential, and option C, the Executive Summary, is a summary of the whole plan."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 244, $official_bank_source${"itemId":"7808dee0-4677-59ca-85e6-9d1a2933f389","questionId":"7b5b8767-8710-5e97-9120-499b092ef023","sourceKey":"bank:ENT211:ENT211-W06-014","payload":{"prompt":"The business plan component that answers the question 'How will you make money?' is the","options":["Business Opportunity","Team","Revenue Model","Financial Projection"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The Revenue Model explains how the business will make money. Financial Projection (option D) is tempting because it also involves money, but it predicts the company's growth rather than explaining how income is earned. Business Opportunity (option A) covers market potential and Team (option B) covers structure and management."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 245, $official_bank_source${"itemId":"1514f5b1-a789-574e-a9d7-d765b5dcd9db","questionId":"5dc1eae8-693d-5fa0-bd0b-4efa3ea74142","sourceKey":"bank:ENT211:ENT211-W06-015","payload":{"prompt":"In a simple business plan, the 'company's growth prediction' is presented in the","options":["Financial Projection","Business Opportunity","SWOT Analysis","Revenue Model"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The Financial Projection is the company's growth prediction. The Revenue Model (option D) explains how money will be made, not how the company is expected to grow, Business Opportunity (option B) is about market potential, and SWOT Analysis (option C) covers strengths, weaknesses, opportunities and threats."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 246, $official_bank_source${"itemId":"ce706d2f-1219-5b64-ab64-74bdaab308da","questionId":"83c477dd-df36-5f58-8613-860462623060","sourceKey":"bank:ENT211:ENT211-W06-016","payload":{"prompt":"The business plan component that shows how you structure and manage your company is the","options":["Team","Company Description","Executive Summary","Competitor Analysis"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The Team section shows how you structure and manage your company. Company Description (option B) is about what the company does, the Executive Summary (option C) summarises the plan, and Competitor Analysis (option D) shows what makes you stand out."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 247, $official_bank_source${"itemId":"63b334bc-fb8c-56ba-b747-c97defb62056","questionId":"3622ddb9-e1d0-59f2-9cab-1b91a3570146","sourceKey":"bank:ENT211:ENT211-W06-017","payload":{"prompt":"In a business plan, SWOT stands for","options":["Strengths, Workforce, Objectives and Timeline","Strategy, Weaknesses, Operations and Targets","Strengths, Weaknesses, Opportunities and Threats","Sales, Weaknesses, Opportunities and Trends"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"SWOT stands for Strengths, Weaknesses, Opportunities and Threats, which together give a balanced look at the business and its environment. Options B, A and D each keep a letter or two right but swap in words that are not part of SWOT."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 248, $official_bank_source${"itemId":"de7ade22-a4b8-5b7c-b489-b3fd569bb432","questionId":"f01b28ef-4898-546f-b629-116460a3bfa3","sourceKey":"bank:ENT211:ENT211-W06-018","payload":{"prompt":"The Revenue Model section of a simple business plan answers which question?","options":["What does your company do?","What makes you stand out?","How will you make money?","What is the market potential?"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The Revenue Model answers 'How will you make money?'. Market potential (option D) belongs to Business Opportunity, standing out (option B) belongs to Competitor Analysis, and what the company does (option A) belongs to Company Description."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 249, $official_bank_source${"itemId":"4ad539c1-787b-5c14-a1d5-639c72cfbc37","questionId":"2860c117-5e63-53eb-8332-1d61b600efc4","sourceKey":"bank:ENT211:ENT211-W06-019","payload":{"prompt":"Which of the following is NOT one of the core components of a simple business plan?","options":["SWOT Analysis","Go-to-Market","Team","Revenue Model"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Go-to-Market is a stage in the Swift Clean case study, not one of the eight core components of a simple business plan. SWOT Analysis (option A), Team (option C) and Revenue Model (option D) are all core components."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 250, $official_bank_source${"itemId":"68e3cc9c-bb73-56a4-bc9c-a3a82ec0ac05","questionId":"08609db6-dbbe-5e17-9a83-2a0175de0c75","sourceKey":"bank:ENT211:ENT211-W06-020","payload":{"prompt":"Which of the following is NOT one of the core components of a simple business plan?","options":["Executive Summary","Competitor Analysis","Financial Projection","Patronage Refund"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A patronage refund is a way cooperatives return profit to members; it is not a component of a business plan. Executive Summary (option A), Competitor Analysis (option B) and Financial Projection (option C) are all core components of a simple plan."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 251, $official_bank_source${"itemId":"66a948bb-37fd-59f5-bbc4-c75c471ee209","questionId":"1301d43e-46e3-5296-bf93-b3d42778e082","sourceKey":"bank:ENT211:ENT211-W06-021","payload":{"prompt":"Which of the following is one of the core components of a simple business plan?","options":["Business Opportunity","Key Disadvantage","Milestones (First 90 Days)","Unique Selling Proposition"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Business Opportunity, which shows the market potential, is one of the eight core components of a simple plan. USP (option D) and Milestones (option C) are stages in the Swift Clean case study, while Key Disadvantage (option B) is a column in the table comparing forms of ownership."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 252, $official_bank_source${"itemId":"7535d4d3-e2e2-5a11-96b7-626f4780291e","questionId":"68306514-f087-5a91-953b-6bf130ce4ce4","sourceKey":"bank:ENT211:ENT211-W06-022","payload":{"prompt":"In her business plan, Ada writes a section predicting how her catering company will grow over the next three years. This section is the","options":["Executive Summary","Business Opportunity","Revenue Model","Financial Projection"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A prediction of how the company will grow is the Financial Projection. The Revenue Model (option C) would explain how she charges and earns money, Business Opportunity (option B) would describe market potential, and the Executive Summary (option A) would summarise the whole plan."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 253, $official_bank_source${"itemId":"544dc5e7-04f4-50b7-98d2-3619fdd84e9b","questionId":"d10ce8a0-60f2-567f-8737-07f10ce76973","sourceKey":"bank:ENT211:ENT211-W06-023","payload":{"prompt":"Emeka's business plan explains that his printing shop will charge per page and also sell monthly printing packages to student associations. This part of the plan is the","options":["Revenue Model","Financial Projection","Company Description","Competitor Analysis"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Explaining how the shop will charge customers and earn income is the Revenue Model, which answers 'How will you make money?'. Financial Projection (option B) predicts growth, Company Description (option C) explains what the business does, and Competitor Analysis (option D) shows what makes it stand out."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 254, $official_bank_source${"itemId":"b032b9f6-af56-5779-a172-117cc305f6f8","questionId":"a0f491f7-ec43-5d9f-acc2-1cd10f998909","sourceKey":"bank:ENT211:ENT211-W06-024","payload":{"prompt":"A section of a business plan lists the startup's internal strong and weak points as well as the outside opportunities and threats it faces. This section is the","options":["Business Opportunity","Competitor Analysis","SWOT Analysis","Team"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Looking at strengths, weaknesses, opportunities and threats together is a SWOT Analysis. Competitor Analysis (option B) focuses on what makes you stand out from rivals, Business Opportunity (option A) focuses on market potential, and Team (option D) is about structure and management."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 255, $official_bank_source${"itemId":"b6775dda-265a-51f5-910d-ab6d1675ddfb","questionId":"14122d59-9ed6-5a40-9af6-1a37d550d913","sourceKey":"bank:ENT211:ENT211-W06-025","payload":{"prompt":"A food delivery startup's plan includes a section estimating how many office workers in Ikeja would pay for its service, answering the question 'What is the market potential?'. This section is the","options":["Company Description","Team","Revenue Model","Business Opportunity"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Business Opportunity is the component that answers 'What is the market potential?', which is what estimating how many people would pay is about. Option C, Revenue Model, explains how you will make money, option A, Company Description, explains what the company does, and option B, Team, covers how the company is structured and managed."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 256, $official_bank_source${"itemId":"8f8953e9-6a57-5356-ab72-edca87583add","questionId":"e8e95653-34fc-5d70-b3c3-e1a6beaeafb5","sourceKey":"bank:ENT211:ENT211-W06-026","payload":{"prompt":"Swift Clean, the case study used to illustrate a simple business plan, is a","options":["Lagos-based student hostel booking app","Abuja-based mobile laundry cooperative","Lagos-based food delivery startup","Lagos-based mobile laundry service startup"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Swift Clean is a Lagos-based mobile laundry service startup that offers on-demand laundry pickup and delivery through an app. Options C and A name the wrong kind of business, and option B gets both the city and the form of business wrong."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 257, $official_bank_source${"itemId":"ef6d3b6b-9b85-5833-b5eb-62ed2994240a","questionId":"5a5d2f62-7542-5bab-858f-7105e6ff72a8","sourceKey":"bank:ENT211:ENT211-W06-027","payload":{"prompt":"Swift Clean's business idea is on-demand laundry pickup and delivery via an app for students in","options":["Ikeja and Surulere","Akoka and Yaba","Lekki and Ajah","Ikorodu and Epe"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Swift Clean targets students in Akoka and Yaba, where UNILAG and YabaTech are located. Options A, C and D are real Lagos areas, but they are not where Swift Clean's business idea is focused."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 258, $official_bank_source${"itemId":"aea83e26-0945-5192-a1ae-8d33b3d9d392","questionId":"e0c3d43d-0688-56c0-96fb-2907fc5fe9aa","sourceKey":"bank:ENT211:ENT211-W06-028","payload":{"prompt":"In the Swift Clean case, what problem do students face?","options":["They waste time and money on unreliable laundry services","Their hostels have no water for washing clothes","They have no space to dry clothes in the hostel","They cannot afford to buy washing machines"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The problem Swift Clean addresses is that students waste time and money on unreliable laundry services. Options D, B and C sound like believable hostel problems, but none of them is the problem stated in the case."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 259, $official_bank_source${"itemId":"3f37fe88-c21d-5ecd-a553-a8a446d3ece8","questionId":"0db2b3ab-10d7-57fb-b29b-236a97213150","sourceKey":"bank:ENT211:ENT211-W06-029","payload":{"prompt":"What turnaround time does Swift Clean promise its customers?","options":["24 hours","48 hours","72 hours","12 hours"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Swift Clean offers a 48-hour turnaround, together with scheduled pickups and transparent pricing. The other times in options A, C and D are not what the startup promises."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 260, $official_bank_source${"itemId":"c3b56838-8087-5807-b5ef-d579591d386b","questionId":"edb8eb24-80ba-529b-87f0-a35a87e8f1aa","sourceKey":"bank:ENT211:ENT211-W06-030","payload":{"prompt":"Under Problem & Solution, which of the following is NOT part of what Swift Clean says it offers?","options":["Transparent pricing","Scheduled pickups","48-hour turnaround","A campus ambassador program"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Swift Clean's solution is scheduled pickups (option B), transparent pricing (option A) and a 48-hour turnaround (option C). The campus ambassador program does exist in the case, but it is part of the Go-to-Market stage, not the solution."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 261, $official_bank_source${"itemId":"aa12de2d-8992-5a57-a751-3cbf0062b239","questionId":"269a7357-3f1f-5e85-83f9-0740623e5a06","sourceKey":"bank:ENT211:ENT211-W06-031","payload":{"prompt":"How large is Swift Clean's stated target market?","options":["50,000+ undergraduate students","15,000+ undergraduate students","1,500+ undergraduate students","5,000+ undergraduate students"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Swift Clean's target market is 15,000+ undergraduate students in UNILAG and YabaTech hostels. Options D, C and A give the wrong figure."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 262, $official_bank_source${"itemId":"90cff64a-e829-5f89-b0f7-a0f5c6d63010","questionId":"cef906cf-5b72-5c81-a43b-9589f17736ba","sourceKey":"bank:ENT211:ENT211-W06-032","payload":{"prompt":"Swift Clean's target market is undergraduate students living in the hostels of","options":["UNILAG and UNIBEN","UNILAG and LASU","UNILAG and YabaTech","YabaTech and LASU"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The target market is undergraduates in UNILAG and YabaTech hostels, which fits the business idea of serving Akoka and Yaba. LASU and UNIBEN in options B, D and A are not part of the target market."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 263, $official_bank_source${"itemId":"2af73001-0b3a-5032-b7f6-fdfec803bee0","questionId":"5623e9d7-d6e4-54c3-8688-d2c2e15c7d90","sourceKey":"bank:ENT211:ENT211-W06-033","payload":{"prompt":"Which of the following is part of Swift Clean's Unique Selling Proposition (USP)?","options":["A campus ambassador program","Onboarding 200 customers","Per-kg pricing","A loyalty points system"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Swift Clean's USP is student-friendly pricing, free pickup/delivery on campus and a loyalty points system. The campus ambassador program (option A) belongs to Go-to-Market, per-kg pricing (option C) belongs to the Revenue Model, and onboarding 200 customers (option B) is a milestone."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 264, $official_bank_source${"itemId":"d314f0aa-c8cd-51c3-8318-ec53120a2208","questionId":"801d616f-0554-5c99-8d0d-e49c7330ab86","sourceKey":"bank:ENT211:ENT211-W06-034","payload":{"prompt":"In the Swift Clean case, free pickup and delivery on campus is part of which stage?","options":["Go-to-Market","Revenue Model","Problem & Solution","USP"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Free pickup/delivery on campus is listed under the USP, along with student-friendly pricing and loyalty points. Go-to-Market (option A) covers ambassadors, social media ads and partnerships, the Revenue Model (option B) covers per-kg pricing and bulk plans, and Problem & Solution (option C) covers scheduled pickups, transparent pricing and 48-hour turnaround."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 265, $official_bank_source${"itemId":"0b81b640-0efe-548b-9078-77cf7dea2efd","questionId":"7e9d589b-a260-5787-b78d-95e9d16c493e","sourceKey":"bank:ENT211:ENT211-W06-035","payload":{"prompt":"A campus ambassador program, targeted Instagram/Facebook ads and partnerships with student associations make up Swift Clean's","options":["Milestones","Go-to-Market","USP","Target Market"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"These are the ways Swift Clean plans to reach customers, so they form its Go-to-Market stage. The USP (option C) is what makes it special, the Target Market (option D) is the 15,000+ students it serves, and Milestones (option A) are its 90-day goals."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 266, $official_bank_source${"itemId":"f1c2e64d-8425-5feb-97a8-b1b5c8a2e82b","questionId":"620b1097-0344-5967-8713-417762731a2a","sourceKey":"bank:ENT211:ENT211-W06-036","payload":{"prompt":"How does Swift Clean charge for its laundry service?","options":["Per item of clothing, with no discounts","A flat yearly fee for every student","Per kg, with discounted monthly bulk plans","Per hour of washing time"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Swift Clean's Revenue Model uses per-kg pricing, with discounted monthly 'bulk' plans for hostels and couples. Options A, B and D describe other pricing methods that are not part of this case."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 267, $official_bank_source${"itemId":"d197a579-b2b0-5643-963c-01ed6f5781e9","questionId":"9fae6b7f-05fa-5bd4-82d6-993b1d742f7c","sourceKey":"bank:ENT211:ENT211-W06-037","payload":{"prompt":"Swift Clean's discounted monthly 'bulk' plans are meant for","options":["lecturers and university staff","hostels and couples","first-year students only","restaurants and hotels"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The discounted monthly bulk plans are for hostels and couples. Options A, C and D name other groups that are not mentioned in Swift Clean's Revenue Model."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 268, $official_bank_source${"itemId":"5d24c4f4-4d6e-58f3-9819-ce7cae334132","questionId":"50f85a88-8939-5d7c-bd63-8facb02de104","sourceKey":"bank:ENT211:ENT211-W06-038","payload":{"prompt":"How many customers does Swift Clean aim to onboard as one of its milestones?","options":["15,000","200","500","2,000"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"One of Swift Clean's first-90-day milestones is to onboard 200 customers. Option A (15,000) is the size of the target market, not the customer milestone, and options D and C are not stated."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 269, $official_bank_source${"itemId":"1b63850e-7e5a-5723-858b-7edd921b9cca","questionId":"c4abee25-544f-59be-a5be-eea0825483a8","sourceKey":"bank:ENT211:ENT211-W06-039","payload":{"prompt":"Swift Clean's milestones are set for what period?","options":["The first 30 days","The first year","The first 90 days","The first 6 months"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Swift Clean's milestones cover the first 90 days: launch the app, onboard 200 customers and secure one hostel partnership. The periods in options A, D and B are not the ones given."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 270, $official_bank_source${"itemId":"d1dce277-5844-5979-b7af-6351ab1cb00a","questionId":"d13c9daa-502e-5bbe-ade5-32cca71960e2","sourceKey":"bank:ENT211:ENT211-W06-040","payload":{"prompt":"Which of the following is one of Swift Clean's milestones?","options":["Open a physical laundry shop in Yaba","Secure 1 hostel partnership","Secure 10 hostel partnerships","Onboard 2,000 customers"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Swift Clean's milestones are to launch the app, onboard 200 customers and secure 1 hostel partnership. Options C and D inflate the numbers, and option A goes against the app-based pickup and delivery model."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 271, $official_bank_source${"itemId":"69a39051-e51a-57e8-9b81-7e613847f0e5","questionId":"74c33e40-684a-5371-8bb0-0620ad1d50d7","sourceKey":"bank:ENT211:ENT211-W06-041","payload":{"prompt":"In the Swift Clean case study, which stage comes immediately after Target Market (Stage 3)?","options":["Problem & Solution","USP","Go-to-Market","Revenue Model"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The numbered stages run: 1 Business Idea, 2 Problem & Solution, 3 Target Market, 4 USP, 5 Go-to-Market, 6 Revenue Model, 7 Milestones. So USP follows Target Market. Problem & Solution (option A) comes before it, while Go-to-Market (option C) and Revenue Model (option D) come later."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 272, $official_bank_source${"itemId":"383bd769-9cc4-5f44-b476-9ee61133e991","questionId":"bd1295de-e394-5407-b0fd-168ccf65afeb","sourceKey":"bank:ENT211:ENT211-W06-042","payload":{"prompt":"What is Stage 1 in the Swift Clean case study?","options":["Problem & Solution","Target Market","Executive Summary","Business Idea"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Swift Clean starts with Stage 1, the Business Idea: on-demand laundry pickup and delivery via an app. Problem & Solution (option A) is Stage 2 and Target Market (option B) is Stage 3. Executive Summary (option C) is a business plan component, not a stage in this case."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 273, $official_bank_source${"itemId":"b31cafbc-f962-58fc-ad2d-a72cd1958f19","questionId":"0115a027-53f7-5b11-811f-6a81fe1a39b2","sourceKey":"bank:ENT211:ENT211-W06-043","payload":{"prompt":"The final stage (Stage 7) in the Swift Clean case study is","options":["Go-to-Market","Milestones (First 90 Days)","Financial Projection","Revenue Model"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Stage 7 is Milestones (First 90 Days). The Revenue Model (option D) is Stage 6 and Go-to-Market (option A) is Stage 5. Financial Projection (option C) is a business plan component, not one of the Swift Clean stages."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 274, $official_bank_source${"itemId":"be70c2d6-30f4-56ca-9ff0-8fdf704026d6","questionId":"b11fe81f-d8bc-563d-af46-6f2f0b0dd344","sourceKey":"bank:ENT211:ENT211-W06-044","payload":{"prompt":"In the Swift Clean case study, Go-to-Market is which stage?","options":["Stage 5","Stage 4","Stage 3","Stage 6"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Go-to-Market is Stage 5, coming after the USP (Stage 4) and before the Revenue Model (Stage 6). Stage 3 (option C) is Target Market, Stage 4 (option B) is the USP, and Stage 6 (option D) is the Revenue Model."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 275, $official_bank_source${"itemId":"0dfcec4c-fa8b-5743-ad1d-383eb31fecc0","questionId":"2384efa3-0eda-531b-8175-0868b287d2ec","sourceKey":"bank:ENT211:ENT211-W06-045","payload":{"prompt":"How many stages are presented in the Swift Clean case study?","options":["Seven","Eight","Six","Five"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The Swift Clean case runs through seven stages, from Business Idea to Milestones (First 90 Days). Eight (option B) is the number of core components of a simple business plan, which is easy to confuse with the number of case stages."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 276, $official_bank_source${"itemId":"3c870882-2d81-5436-a488-8f0198f9c620","questionId":"cea912d2-2458-5e57-9915-d5086de5f470","sourceKey":"bank:ENT211:ENT211-W06-046","payload":{"prompt":"A business with a single owner and no legal difference between the owner and the business is a","options":["cooperative","general partnership","limited liability partnership","sole proprietorship"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A sole proprietorship has one owner, and the law makes no difference between the owner and the business. A general partnership (option B) needs two or more people, an LLP (option C) is a legal entity separate from its members, and a cooperative (option A) is owned by many members."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 277, $official_bank_source${"itemId":"0cdc9469-42a2-5c85-a26f-e912bdbba69b","questionId":"34789de9-3e02-5091-bbc1-8e812dc20418","sourceKey":"bank:ENT211:ENT211-W06-047","payload":{"prompt":"The owner of a sole proprietorship has","options":["unlimited personal liability for all debts and losses","liability limited to the shares owned","liability shared jointly with co-partners","no liability, because the business carries its own debts"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Because the owner and the business are legally the same, a sole proprietor has unlimited personal liability for all debts and losses. Option B describes a limited liability company, option C describes a general partnership, and option D is wrong because the business has no separate legal existence to carry its own debts."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 278, $official_bank_source${"itemId":"7fb46142-651b-5b61-8222-85877ffbfdb6","questionId":"312a58bb-2e4c-5d6d-ad8f-9edbe1999fe9","sourceKey":"bank:ENT211:ENT211-W06-048","payload":{"prompt":"A sole proprietorship is simple to register and is often called a","options":["'Cooperative Society'","'Business Name'","'Joint Venture'","'Limited Company'"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A sole proprietorship is simple to register and is often called a 'Business Name'. A limited company (option D) is the Ltd form, a joint venture (option C) involves more than one party, and a cooperative society (option A) is owned by members."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 279, $official_bank_source${"itemId":"87541fc5-9861-5502-98d1-c1ab75b8afed","questionId":"dba37d5e-eb80-5d1e-ad2f-f738df22042b","sourceKey":"bank:ENT211:ENT211-W06-049","payload":{"prompt":"The statement 'Someone who owns an unincorporated business by himself or herself is a sole proprietor' is credited to","options":["Tyler (2025)","Bloomenthal (2025)","Lip (2024)","Beattie (2025)"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"This description of a sole proprietor is credited to Tyler (2025). Beattie (2025) in option D defines the limited liability partnership, Bloomenthal (2025) in option B defines the general partnership, and Lip (2024) in option C defines the cooperative."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 280, $official_bank_source${"itemId":"49cff7fd-de60-568b-aa88-fa64e463938c","questionId":"da345cc8-7c94-5918-915a-490a0ac27d95","sourceKey":"bank:ENT211:ENT211-W06-050","payload":{"prompt":"Which of the following is NOT true of a sole proprietorship?","options":["It is a distinct legal entity with perpetual existence","It is simple to register","The owner keeps all the profits","The owner has total control"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Being a distinct legal entity with perpetual existence is a feature of a limited liability partnership, not a sole proprietorship, where owner and business are legally the same. Total control (option D), keeping all profits (option C) and simple registration (option B) are all true of a sole proprietorship."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 281, $official_bank_source${"itemId":"65a64e42-57e2-51bb-b970-1d700ed10b88","questionId":"25c74285-b5b4-58ce-91e6-a51dbc426898","sourceKey":"bank:ENT211:ENT211-W06-051","payload":{"prompt":"Mama Nkechi runs a provision shop in Mushin by herself, registered as a business name. When the shop owed a supplier, the supplier was able to claim against her personal property. Her form of ownership is a","options":["cooperative","sole proprietorship","limited liability partnership","limited liability company"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"One owner, a business-name registration and unlimited personal liability together point to a sole proprietorship. A limited liability company (option D) and an LLP (option C) would protect her personal assets, and a cooperative (option A) is owned by many members, not one person."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 282, $official_bank_source${"itemId":"a94b7dc3-640b-5bb2-b762-a5e528525054","questionId":"3f4038ce-7313-5a48-8379-334925699535","sourceKey":"bank:ENT211:ENT211-W06-052","payload":{"prompt":"A business structure that blends features of partnerships and corporations, giving partners limited personal liability while allowing flexible management, is a","options":["general partnership","cooperative","limited liability partnership","sole proprietorship"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A limited liability partnership (LLP) mixes partnership and corporate features, so partners get limited personal liability and flexible management. A general partnership (option A) and a sole proprietorship (option D) both carry unlimited liability, and a cooperative (option B) is defined by democratic member ownership."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 283, $official_bank_source${"itemId":"b68a4cbb-52f5-5b7b-a5de-91d3aef3728a","questionId":"19303db1-d10b-5738-b678-07f20e9d33a5","sourceKey":"bank:ENT211:ENT211-W06-053","payload":{"prompt":"The definition of a Limited Liability Partnership as a structure blending features of partnerships and corporations is credited to","options":["Tyler (2025)","Beattie (2025)","Lip (2024)","Bloomenthal (2025)"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The LLP definition is credited to Beattie (2025). Bloomenthal (2025) in option D is linked to the general partnership, Tyler (2025) in option A to the sole proprietor, and Lip (2024) in option C to the cooperative."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 284, $official_bank_source${"itemId":"59337660-5b21-510a-b702-455d3b003978","questionId":"70298b31-c742-5ad1-a24f-beb4001f6696","sourceKey":"bank:ENT211:ENT211-W06-054","payload":{"prompt":"A limited liability partnership is described as ideal for","options":["farmers pooling their resources","a boutique firm run by spouses","professional services like law, accounting or consulting","solo vendors and freelancers"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Because an LLP shields partners from a co-partner's misconduct and can own property and sue, it is ideal for professional services like law, accounting and consulting. Option A describes a producer cooperative, option D fits a sole proprietorship, and option B is the example of a general partnership."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 285, $official_bank_source${"itemId":"26a24092-4771-566e-b474-b30f6695541d","questionId":"a5c10850-1eef-5126-a4d1-ade15c85b673","sourceKey":"bank:ENT211:ENT211-W06-055","payload":{"prompt":"Which of the following is NOT a feature of a limited liability partnership?","options":["It can own property, sue and be sued","Partners have unlimited personal liability for the firm's debts","It is a distinct legal entity separate from its members","It has perpetual existence"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"An LLP gives partners limited personal liability, so unlimited liability is not one of its features. Being a separate legal entity (option C), having perpetual existence (option D) and being able to own property, sue and be sued (option A) are all LLP features."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 286, $official_bank_source${"itemId":"ce7d451e-695c-5bd9-89ac-247d20ebf6d1","questionId":"0fd2e2cb-0929-57c6-83d2-14754b2f5df1","sourceKey":"bank:ENT211:ENT211-W06-056","payload":{"prompt":"An LLP protects partners' personal assets from","options":["business failures or co-partners' misconduct","competition from rival firms","all taxes on business income","any form of government regulation"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Limited personal liability in an LLP protects partners' personal assets if the business fails or if a co-partner misbehaves. Options C, D and B are not things an LLP protects partners from; limited liability is about debts and obligations."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 287, $official_bank_source${"itemId":"f52e9618-f6c2-5edf-8b02-a209ba5137bf","questionId":"2e5746ed-c9a0-59e2-b41d-b7d494791b6e","sourceKey":"bank:ENT211:ENT211-W06-057","payload":{"prompt":"Three chartered accountants in Lagos want to run a firm together. Each wants their personal assets protected if a co-partner commits misconduct, and they want the firm to be able to own property and be sued in its own name. The most suitable form is a","options":["cooperative","general partnership","limited liability partnership","sole proprietorship"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Protection from a co-partner's misconduct, a separate legal identity and suitability for accounting firms all point to a limited liability partnership. A general partnership (option B) makes partners jointly and personally liable, a sole proprietorship (option D) has only one owner, and a cooperative (option A) is built around democratic member ownership rather than professional practice."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 288, $official_bank_source${"itemId":"d11db4ec-3f38-556a-af29-ba24f7a1a570","questionId":"f371a638-7828-55e5-be58-18ea4332438e","sourceKey":"bank:ENT211:ENT211-W06-058","payload":{"prompt":"A business arrangement in which two or more individuals agree to share responsibilities, assets, profits, and financial and legal liabilities of a jointly-owned business is a","options":["cooperative","sole proprietorship","general partnership","limited liability company"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"This is the definition of a general partnership: two or more people sharing responsibilities, assets, profits and liabilities. A sole proprietorship (option B) has one owner, a cooperative (option A) is democratically controlled by members who are its customers, workers or producers, and a limited liability company (option D) limits liability to shares owned."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 289, $official_bank_source${"itemId":"db75f5de-16f6-565d-a299-7bcf0986d668","questionId":"3ad2c650-90b9-5f51-a40f-f0ec64fe5105","sourceKey":"bank:ENT211:ENT211-W06-059","payload":{"prompt":"The definition of a general partnership as two or more individuals sharing responsibilities, assets, profits and liabilities is credited to","options":["Bank of America (2025)","Beattie (2025)","Bloomenthal (2025)","Tyler (2025)"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The general partnership definition is credited to Bloomenthal (2025). Beattie (2025) in option B defines the LLP, Tyler (2025) in option D describes the sole proprietor, and Bank of America (2025) in option A defines a business plan."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 290, $official_bank_source${"itemId":"241eeda4-3086-54cf-ab97-813d4d393d27","questionId":"d57c4012-e9ac-550c-86a7-abfdca74a3cf","sourceKey":"bank:ENT211:ENT211-W06-060","payload":{"prompt":"Which example is given of a business for which a general partnership is common?","options":["A freelancer working alone","A law firm seeking protection from co-partners' misconduct","A boutique firm run by spouses","Farmers pooling resources together"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"General partnerships are common for small, trusted teams, such as a boutique firm run by spouses. Option B describes the case for an LLP, option D describes a producer cooperative, and option A fits a sole proprietorship."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 291, $official_bank_source${"itemId":"b99edbee-f2ec-524d-8f9e-e50fce975c98","questionId":"0a0fcfa5-19f4-597b-91d6-dc2efc95a941","sourceKey":"bank:ENT211:ENT211-W06-061","payload":{"prompt":"Compared with a corporation, a general partnership is","options":["impossible to form without investors","required to have at least ten partners","less expensive to form","more expensive to form"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"General partnerships are less expensive to form than a corporation, which is why they suit small, trusted teams. Option D says the opposite, and options A and B add requirements that do not exist, since two or more individuals are enough."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 292, $official_bank_source${"itemId":"2e7c9b91-4286-5f94-ba65-e7cb95a92920","questionId":"844809a3-32ed-5844-b45a-dc4c2def0a59","sourceKey":"bank:ENT211:ENT211-W06-062","payload":{"prompt":"A business owned and democratically controlled by its members, who are also its customers, workers or producers, is a","options":["general partnership","limited liability partnership","sole proprietorship","cooperative"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A cooperative (co-op) is owned and democratically controlled by its members, who are also its customers, workers or producers. A general partnership (option A) is about partners sharing liabilities, an LLP (option B) gives limited liability to professional partners, and a sole proprietorship (option C) has a single owner."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 293, $official_bank_source${"itemId":"c0b1ea75-2639-5b33-9ccc-5b278ee84999","questionId":"2d270ad2-f7be-52fc-9e10-c8c13dbbcce8","sourceKey":"bank:ENT211:ENT211-W06-063","payload":{"prompt":"The definition of a cooperative as a business owned and democratically controlled by its members is credited to","options":["Tyler (2025)","Beattie (2025)","Lip (2024)","Bloomenthal (2025)"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The cooperative definition is credited to Lip (2024). Tyler (2025) in option A is linked to the sole proprietor, Beattie (2025) in option B to the LLP, and Bloomenthal (2025) in option D to the general partnership."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 294, $official_bank_source${"itemId":"37a7dc06-d093-56c9-a944-863ac626d52d","questionId":"3d497d35-37b6-5337-aa50-5f97c355f3c9","sourceKey":"bank:ENT211:ENT211-W06-064","payload":{"prompt":"In a cooperative, the principle of 'one member, one vote' describes","options":["equal voting rights","perpetual existence","control based on share ownership","patronage refunds"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"'One member, one vote' means every member has equal voting rights, whatever they have contributed. Control based on share ownership (option C) is how traditional corporations work, patronage refunds (option D) are how co-op profits are returned, and perpetual existence (option B) is an LLP feature."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 295, $official_bank_source${"itemId":"18dea52d-2033-5001-aafd-82a28003e565","questionId":"48a3eb6f-9e6e-5ae6-846e-c2448ba4a8e9","sourceKey":"bank:ENT211:ENT211-W06-065","payload":{"prompt":"In a cooperative, profits are often","options":["paid out according to the number of shares each person holds","transferred to the government as levies","returned to members as patronage refunds or reinvested for member benefit","kept entirely by a single owner"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Co-ops often return profits to members as patronage refunds or reinvest them for member benefit. Option D describes a sole proprietorship, option A reflects share-based corporations, and option B is not mentioned at all."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 296, $official_bank_source${"itemId":"bccbd6c0-96c8-5a78-9e09-398033bcb4a4","questionId":"50df6547-0986-50f8-9bc4-119cf210ae5c","sourceKey":"bank:ENT211:ENT211-W06-066","payload":{"prompt":"Which of the following is NOT a key feature of a cooperative?","options":["Control based on share ownership","Mutual benefit","Collective management","Voluntary membership"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Control based on share ownership is what makes traditional corporations different from co-ops, where each member has one vote. Voluntary membership (option D), collective management (option C) and mutual benefit (option B) are all key features of a cooperative."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 297, $official_bank_source${"itemId":"86178dd6-e44f-5492-bfb5-0e9050ea9b6b","questionId":"c2d54995-217a-5219-b8b6-6bc54f7a60f6","sourceKey":"bank:ENT211:ENT211-W06-067","payload":{"prompt":"The main focus of a cooperative is","options":["maximising profit for a single owner","protecting professional partners from each other's misconduct","attracting outside investors to scale quickly","meeting shared economic, social and cultural needs rather than just profit"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A co-op focuses on meeting its members' shared economic, social and cultural needs, not just on profit. Option A describes a sole proprietorship, option B describes an LLP, and option C matches the limited liability company, which suits businesses seeking investment."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 298, $official_bank_source${"itemId":"6dac24ad-8956-5e81-9c59-40d3545421e2","questionId":"9ee752b0-e1f3-57b5-82e0-b359439563e0","sourceKey":"bank:ENT211:ENT211-W06-068","payload":{"prompt":"A group of rice farmers in Kebbi pool their money to buy a shared milling machine and jointly sell their produce, with each farmer having one vote. This is an example of a","options":["consumer cooperative","worker cooperative","general partnership","producer cooperative"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Farmers pooling resources is the example of a producer co-op. A consumer co-op (option A) is owned by shoppers, as in a grocery, a worker co-op (option B) is owned by its employees, and a general partnership (option C) does not run on one member, one vote."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 299, $official_bank_source${"itemId":"6e755f1b-b719-5a01-9f36-646c10f0e175","questionId":"717380aa-3194-5f16-ac72-f5b02fc22375","sourceKey":"bank:ENT211:ENT211-W06-069","payload":{"prompt":"A bakery in Ibadan is owned by the people who work in it, and each employee-owner has an equal vote in decisions. This is an example of a","options":["consumer cooperative","producer cooperative","sole proprietorship","worker cooperative"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"An employee-owned business run on equal votes is a worker co-op. A consumer co-op (option A) is owned by its customers, like a grocery, a producer co-op (option B) is for producers such as farmers pooling resources, and a sole proprietorship (option C) has only one owner."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 300, $official_bank_source${"itemId":"7f8c46f0-6e96-53d6-9f74-4e172620e820","questionId":"6c31ae19-b831-5e99-8659-ecd01625d52b","sourceKey":"bank:ENT211:ENT211-W06-070","payload":{"prompt":"A grocery store owned by the shoppers who buy from it is an example of a","options":["consumer cooperative","limited liability partnership","producer cooperative","worker cooperative"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A grocery owned by its customers is the example of a consumer co-op. A worker co-op (option D) is employee-owned, a producer co-op (option C) is made up of producers such as farmers, and an LLP (option B) is a professional partnership, not a member-owned store."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 301, $official_bank_source${"itemId":"ba8b5dc1-da50-570a-aa74-e63c2eb43588","questionId":"9dc331ed-7cf0-544d-9497-5b8ee1a26e43","sourceKey":"bank:ENT211:ENT211-W06-071","payload":{"prompt":"In the comparison of ownership forms, the liability of a general partnership is","options":["varies","unlimited, with partners jointly liable","unlimited, because the owner is the business","limited to shares owned"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"General partnership liability is unlimited, with the partners jointly liable. 'Limited to shares owned' (option D) is the Ltd company, 'varies' (option A) is the cooperative, and 'the owner is the business' (option C) describes the sole proprietorship, which also has unlimited liability but for a single owner."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 302, $official_bank_source${"itemId":"cce5d7f0-6c1a-5145-ae5c-7fa6fa22d102","questionId":"fb160783-347a-5988-b88e-b6545563f9b0","sourceKey":"bank:ENT211:ENT211-W06-072","payload":{"prompt":"Which form of ownership has 'personal risk, hard to raise capital' as its key disadvantage?","options":["Cooperative","Limited liability company (Ltd)","Sole proprietorship","General partnership"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A sole proprietor carries all the personal risk and finds it hard to raise capital alone. General partnership's key disadvantage (option D) is potential for conflict and shared personal risk, the Ltd's (option B) is that it is more complex and expensive to register and run, and the cooperative's (option A) is that it can be slow to decide."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 303, $official_bank_source${"itemId":"f2cda022-943c-53c5-8b8f-4fe952f16d81","questionId":"092fbc86-f704-5dad-a2e9-4b12dead69e2","sourceKey":"bank:ENT211:ENT211-W06-073","payload":{"prompt":"In the comparison of ownership forms, which form is best for solo vendors and freelancers?","options":["General partnership","Sole proprietorship","Cooperative","Limited liability company (Ltd)"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Sole proprietorship is best for solo vendors and freelancers, and its key advantage is being simple, low cost and giving full control. The general partnership (option A) suits small high-trust teams, the Ltd (option D) suits scalable startups seeking investment, and the cooperative (option C) suits agricultural groups, credit unions and collective retail."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 304, $official_bank_source${"itemId":"89c58937-7a40-5aea-a2e2-56b80b1c425a","questionId":"99486e41-690e-5622-858a-993b76f8e921","sourceKey":"bank:ENT211:ENT211-W06-074","payload":{"prompt":"The key advantage of a general partnership is","options":["member ownership and democratic control","protection of personal assets and credibility with investors","shared skills/resources and ease of formation","full control by a single owner at low cost"],"correctOption":2,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"General partnerships let people share skills and resources and are easy to form. Option B is the key advantage of a limited liability company, option A is that of a cooperative, and option D is that of a sole proprietorship."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 305, $official_bank_source${"itemId":"41a40624-01dd-5220-8a0a-f0b32b6052fa","questionId":"5c4fbad7-37b5-535a-a350-6d0aa5a537d7","sourceKey":"bank:ENT211:ENT211-W06-075","payload":{"prompt":"The key disadvantage of a general partnership is","options":["potential for conflict and shared personal risk","it can be slow to decide","personal risk and difficulty raising capital for one owner","it is more complex and expensive to register and run"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Because partners share decisions and are jointly liable, the key disadvantage of a general partnership is potential for conflict and shared personal risk. Option B belongs to the cooperative, option D to the limited liability company, and option C to the sole proprietorship."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 306, $official_bank_source${"itemId":"661b1687-bf52-5a6d-86af-fbd48dc14537","questionId":"31e739d2-633b-5ede-bd91-ac03bd88923b","sourceKey":"bank:ENT211:ENT211-W06-076","payload":{"prompt":"In the comparison of ownership forms, a general partnership is best for","options":["agricultural groups and credit unions","solo vendors and freelancers","most scalable startups seeking investment","small teams with high trust, such as a family business"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"General partnerships are best for small, high-trust teams such as a family business, because partners share personal risk. Option A is best served by cooperatives, option C by limited liability companies, and option B by sole proprietorships."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 307, $official_bank_source${"itemId":"ab15a4cc-ad2b-5557-8d23-91eef4b7a635","questionId":"ce50da14-87bf-5279-b489-69aa655fdd9d","sourceKey":"bank:ENT211:ENT211-W06-077","payload":{"prompt":"The liability of a limited liability company (Ltd) is","options":["unlimited, because the owner is the business","limited to the shares owned","unlimited, with partners jointly liable","varies"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"In a limited liability company, an owner's liability is limited to the shares they own, which protects personal assets. Option A describes the sole proprietorship, option C the general partnership, and option D the cooperative."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 308, $official_bank_source${"itemId":"0bbf4037-47ce-5491-a351-726b48b62e85","questionId":"fe17d96c-ae8b-5604-8d31-176ef9e80052","sourceKey":"bank:ENT211:ENT211-W06-078","payload":{"prompt":"Which form of ownership has 'more complex/expensive to register and run' as its key disadvantage?","options":["Sole proprietorship","Cooperative","General partnership","Limited liability company (Ltd)"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The Ltd company protects personal assets but is more complex and expensive to register and run. A sole proprietorship (option A) is simple and low cost, a general partnership (option C) is easy to form, and a cooperative's key disadvantage (option B) is that it can be slow to decide."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 309, $official_bank_source${"itemId":"61d42075-8b61-5691-82f1-1c27bd3661bb","questionId":"387f18f6-8bff-508f-9655-6b2c3e9fde95","sourceKey":"bank:ENT211:ENT211-W06-079","payload":{"prompt":"Zainab is starting a fintech company in Lagos that she hopes to scale quickly by raising money from investors, and she wants her personal assets protected. The most suitable form of ownership is a","options":["cooperative","sole proprietorship","general partnership","limited liability company (Ltd)"],"correctOption":3,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"The Ltd is best for the most scalable startups and any business seeking investment, and it protects personal assets while being credible to investors. A sole proprietorship (option B) and a general partnership (option C) carry unlimited liability and make it harder to raise capital, and a cooperative (option A) suits groups such as farmers and credit unions."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 310, $official_bank_source${"itemId":"1f28eddf-d34a-5fa6-bc5a-8a05d89cd312","questionId":"b4e83149-9f89-5152-8b2b-2059df200f0e","sourceKey":"bank:ENT211:ENT211-W06-080","payload":{"prompt":"In the comparison of ownership forms, the liability of a cooperative is described as","options":["unlimited, because the owner is the business","varies","limited to shares owned","unlimited, with members jointly liable"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"A cooperative's liability is shown as 'varies'. Option D is close to the general partnership entry, option C is the Ltd company entry, and option A is the sole proprietorship entry."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 311, $official_bank_source${"itemId":"d78702ab-3c91-57c7-b444-09dd28b6600a","questionId":"33c5c7f6-2c5d-5045-b7c7-730124f8a3d3","sourceKey":"bank:ENT211:ENT211-W06-081","payload":{"prompt":"Which form of ownership has 'can be slow to decide' as its key disadvantage?","options":["Cooperative","Limited liability company (Ltd)","Sole proprietorship","General partnership"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Because a cooperative is democratically controlled, with one vote per member, decisions can be slow. A general partnership's (option D) key disadvantage is conflict and shared personal risk, the Ltd's (option B) is cost and complexity, and the sole proprietorship's (option C) is personal risk and difficulty raising capital."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 312, $official_bank_source${"itemId":"f0bd11e8-12ac-5797-8166-8e07010a1588","questionId":"af64ac23-8e70-5464-bd18-2dfa760d8642","sourceKey":"bank:ENT211:ENT211-W06-082","payload":{"prompt":"In the comparison of ownership forms, which form is best for agricultural groups, credit unions and collective retail?","options":["Cooperative","Limited liability company (Ltd)","Sole proprietorship","General partnership"],"correctOption":0,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Cooperatives are best for agricultural groups, credit unions and collective retail, where members own the business and control it democratically. The general partnership (option D) suits small high-trust teams, the Ltd (option B) suits scalable startups seeking investment, and the sole proprietorship (option C) suits solo vendors and freelancers."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 313, $official_bank_source${"itemId":"d0e71e1a-78d0-532c-b96a-3ad97f6b6e31","questionId":"57aca358-4b10-5e0c-9b6e-757ece0156cb","sourceKey":"bank:ENT211:ENT211-W06-083","payload":{"prompt":"Which two forms of ownership carry unlimited liability in the comparison table?","options":["Limited liability company and cooperative","Sole proprietorship and general partnership","General partnership and cooperative","Sole proprietorship and limited liability company"],"correctOption":1,"section":"Weeks 6-7: Enterprise Formation (Business Plan)","explanation":"Both the sole proprietorship (the owner is the business) and the general partnership (partners are jointly liable) carry unlimited liability. The Ltd company has liability limited to shares owned and the cooperative's liability varies, so options A, D and C each include at least one wrong form."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 314, $official_bank_source${"itemId":"d05f4c87-13c3-5022-8d45-28bb03f1c913","questionId":"1e85568b-3af6-5023-9d11-da550ae0e7a4","sourceKey":"bank:ENT211:ENT211-W08-001","payload":{"prompt":"In Nigeria, registering a business is a legal requirement within how many days of starting the business?","options":["14 days","90 days","30 days","28 days"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A business in Nigeria is required by law to register within 28 days of starting. Options A, C and B are close-sounding periods, but 28 days is the stated legal window, and after it a default fee applies."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 315, $official_bank_source${"itemId":"1b31c09b-0a14-54e8-8763-c748cb29c2dd","questionId":"0c69b97d-b1a9-5f6d-ad8f-4173d0dbdcf0","sourceKey":"bank:ENT211:ENT211-W08-003","payload":{"prompt":"Which of the following is NOT one of the benefits of registering a business in Nigeria?","options":["It protects the business name","It exempts the business from tax registration","It builds trust with customers and banks","It gives the business a legal identity"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Registration gives a business a legal identity, protects its name and builds trust with customers and banks, so options D, A and C are genuine benefits. It does not remove the need for tax registration; after CAC registration the business must still get a Tax Identification Number from FIRS."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 316, $official_bank_source${"itemId":"56824a40-5e36-50bb-a3ac-726240b89f05","questionId":"5c55fe72-5abc-52e4-bc90-022f225d1ecb","sourceKey":"bank:ENT211:ENT211-W08-004","payload":{"prompt":"Business registration is needed to open which type of bank account?","options":["A corporate bank account","A personal savings account","A fixed deposit account","A student current account"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A registered business can open a corporate bank account, which is an account in the business's own name. Options B, C and D are accounts an individual can open without registering a business."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 317, $official_bank_source${"itemId":"801fe1bf-7a82-5a04-ab19-1020bfb2245a","questionId":"72312886-2c7c-583c-a709-4bcda2f87bee","sourceKey":"bank:ENT211:ENT211-W08-005","payload":{"prompt":"Which of the following is registration described as essential for?","options":["Attending Lagos Startup Week","Obtaining a National Identification Number","Government contracts","Joining an online networking group"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Registration is essential for winning government contracts, because government deals with legally recognised businesses. Option B is a personal ID you need before registering, and options D and A are networking activities that need no registration."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 318, $official_bank_source${"itemId":"e0c981f4-baf3-58b4-a0e3-bf86fb31e622","questionId":"d535d676-7870-5e7e-bceb-b99751483206","sourceKey":"bank:ENT211:ENT211-W08-006","payload":{"prompt":"Amaka registers her bakery so that no other business can trade under the same name 'Amaka's Oven'. Which benefit of registration is she mainly enjoying?","options":["Access to government contracts","Name protection","Opening a corporate bank account","Trust building"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Name protection means your registered business name is secured so others cannot use it. Option D is about customers and banks seeing you as credible, while options A and C are about contracts and banking, not about the name."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 319, $official_bank_source${"itemId":"70b6f6cc-d1b9-53b2-85b9-489785660630","questionId":"f26d9e4a-3817-5371-93f1-b88ce02a5b42","sourceKey":"bank:ENT211:ENT211-W08-007","payload":{"prompt":"A tailoring business in Surulere registers with CAC, and soon customers and its bank begin to see it as more credible and reliable. Which benefit of registration does this show?","options":["Default fee avoidance","Trust building","Access to government contracts","Name protection"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Registration builds trust with customers and banks, which is exactly what happens here. Option D is about securing the business name, option C is about winning government jobs, and option A is not the benefit being described."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 320, $official_bank_source${"itemId":"b6dce6b8-00a0-5e68-ba68-20b213455261","questionId":"bc2c1f7d-2b9f-5b45-b60c-422f49cce7c2","sourceKey":"bank:ENT211:ENT211-W08-008","payload":{"prompt":"In Nigeria, business registration is managed by which body?","options":["Small and Medium Enterprises Development Agency of Nigeria (SMEDAN)","Corporate Affairs Commission (CAC)","Federal Inland Revenue Service (FIRS)","Central Bank of Nigeria (CBN)"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The Corporate Affairs Commission (CAC) manages business registration in Nigeria. Option C, FIRS, issues the Tax Identification Number after registration, and options A and D do not register businesses."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 321, $official_bank_source${"itemId":"8db40d84-4238-5b34-8368-4da116d16202","questionId":"4f1eeec1-4d6d-5eeb-a0b1-5f48f60cf2d2","sourceKey":"bank:ENT211:ENT211-W08-009","payload":{"prompt":"Business registration by the CAC in Nigeria is carried out under which law?","options":["Investment and Securities Act","Small Business Development Act","Companies and Allied Matters Act (CAMA)","Federal Inland Revenue Service Act"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The CAC manages registration under the Companies and Allied Matters Act, known as CAMA. Options D, A and B are not the law under which CAC registers businesses."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 322, $official_bank_source${"itemId":"5afc4089-d020-5863-b4c4-2e7d797bccee","questionId":"b33037a3-260a-5f51-8246-b73429d51c8e","sourceKey":"bank:ENT211:ENT211-W08-010","payload":{"prompt":"As of 2026, business registration in Nigeria is primarily completed online through which platform?","options":["The iCRP Portal","The NIN Enrolment Portal","The SMEDAN Registration Portal","The FIRS TIN Portal"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"As of 2026, CAC registration is done mainly online through the iCRP Portal. Option D relates to tax, which comes after registration, and options C and B are not the CAC registration platform."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 323, $official_bank_source${"itemId":"61b433fb-0843-5672-8fbb-31c761c58adb","questionId":"62aca858-1777-5bcd-9d2d-2e503f7dcf2c","sourceKey":"bank:ENT211:ENT211-W08-011","payload":{"prompt":"What is the FIRST step in the CAC business registration process?","options":["Complete the Pre-Registration Form (CAC-BN01)","Pay the filing fees","Choose and reserve a name","Submit and await approval"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Registration starts with choosing and reserving an available business name on the CAC portal. Option A is step 2, option B is step 3 and option D is step 4."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 324, $official_bank_source${"itemId":"3cf0aa0f-28e1-5d3c-9a5e-e7a34b318cd6","questionId":"0f92480a-4a95-58d7-b3d2-3dc46a1eb9da","sourceKey":"bank:ENT211:ENT211-W08-012","payload":{"prompt":"When choosing a business name for CAC registration, how many alternative names should you have?","options":["1","3","5","2"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"You should have 2 alternative names ready, so that if your first choice is taken you can still reserve another. Options A, B and C are not the number recommended."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 325, $official_bank_source${"itemId":"52728b54-30a3-5ff6-ba09-f85fd7f92371","questionId":"d69cea52-e724-58f6-a7b3-d1cc9e206d84","sourceKey":"bank:ENT211:ENT211-W08-013","payload":{"prompt":"The Pre-Registration Form submitted online during business name registration with CAC is called","options":["CAC-BN02","FIRS-TIN01","CAMA-01","CAC-BN01"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"CAC-BN01 is the Pre-Registration Form filled in step 2 of registration, where you enter the business activity and the proprietor or partner details. Option C borrows the name of CAMA, which is the law behind registration, not a form, and option B mixes in FIRS, which only deals with tax after registration. Option A looks similar, but the form named for this step is CAC-BN01."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 326, $official_bank_source${"itemId":"ac343ac7-1729-56d8-a31d-4ddde54e786e","questionId":"3d32cd4b-4740-5981-8dff-12e4e35684bb","sourceKey":"bank:ENT211:ENT211-W08-014","payload":{"prompt":"Which details are submitted online on the Pre-Registration Form (CAC-BN01)?","options":["A full business plan and marketing strategy","Bank statements and the Tax Identification Number","Business activity and proprietor/partner details such as NIN, address and photo","Audited financial statements and a tax clearance certificate"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"On CAC-BN01 you submit the business activity plus the proprietor or partner details: NIN, address and photo. Options D and B include tax items that come after registration, and option A is not required on the form."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 327, $official_bank_source${"itemId":"268a7412-b8fb-527e-8721-e6a96276c048","questionId":"f995e172-d63e-5128-badf-975f0b9ef6ba","sourceKey":"bank:ENT211:ENT211-W08-015","payload":{"prompt":"Which of the following is part of the proprietor/partner details required on the CAC-BN01 form?","options":["Tax Identification Number (TIN)","Certified Extract","Default fee receipt","National Identification Number (NIN)"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The proprietor or partner must supply their NIN, address and photo on the form. Option A, the TIN, is obtained from FIRS after registration, option B is downloaded after approval, and option C is only paid when the 28-day deadline is missed."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 328, $official_bank_source${"itemId":"b3e6f2ea-9b3b-59b8-b9fa-50566bc5ec11","questionId":"a33d6ae9-567a-56e5-a5b0-471f74ffecad","sourceKey":"bank:ENT211:ENT211-W08-016","payload":{"prompt":"Which step of the CAC registration process comes immediately after completing the Pre-Registration Form (CAC-BN01)?","options":["Obtain a TIN from FIRS","Submit and await approval","Pay the filing fees","Choose and reserve a name"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Step 3, paying the prescribed filing fees online, follows step 2, the CAC-BN01 form. Option D is step 1, option B is step 4, and option A is a post-registration task."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 329, $official_bank_source${"itemId":"ce152054-953c-5d38-9aa9-c85ccd5c7220","questionId":"a3436727-f3c7-5372-ae31-3990c07d8094","sourceKey":"bank:ENT211:ENT211-W08-017","payload":{"prompt":"Which of the following shows the correct order of the four CAC registration steps?","options":["Choose and reserve a name -> Complete CAC-BN01 -> Pay filing fees -> Submit and await approval","Choose and reserve a name -> Pay filing fees -> Complete CAC-BN01 -> Submit and await approval","Complete CAC-BN01 -> Choose and reserve a name -> Pay filing fees -> Submit and await approval","Pay filing fees -> Choose and reserve a name -> Complete CAC-BN01 -> Submit and await approval"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"You first reserve a name, then fill CAC-BN01, then pay the fees, and finally submit and wait for approval. Options C, B and D each mix up the order, for example by paying fees or filling the form before a name is reserved."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 330, $official_bank_source${"itemId":"259f20fd-974e-5e46-8d2a-f3328cffc20b","questionId":"b203fb75-3950-5c70-95bd-58f9e8e38d03","sourceKey":"bank:ENT211:ENT211-W08-018","payload":{"prompt":"If CAC approves a business registration application, what does the applicant download?","options":["A National Identification Number slip and business permit","A reserved name slip and the CAC-BN01 form","A Tax Identification Number and tax clearance certificate","An electronic Certificate of Registration and Certified Extract"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Once approved, you download an electronic Certificate of Registration and a Certified Extract. Option C comes from FIRS after registration, option A is not issued by CAC, and option B belongs to the earlier steps."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 331, $official_bank_source${"itemId":"642ff2c2-ae73-5b06-898d-d0c7fa8d87c6","questionId":"29fccd01-58ba-5713-8c1b-38bb03c9dde2","sourceKey":"bank:ENT211:ENT211-W08-019","payload":{"prompt":"After CAC registration, a business must obtain a Tax Identification Number (TIN) from which body?","options":["Federal Inland Revenue Service (FIRS)","Small and Medium Enterprises Development Agency of Nigeria (SMEDAN)","Corporate Affairs Commission (CAC)","Central Bank of Nigeria (CBN)"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The TIN is obtained from the Federal Inland Revenue Service (FIRS) once CAC registration is done. Option C, CAC, handles the registration itself, while options B and D do not issue TINs."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 332, $official_bank_source${"itemId":"af5edea4-f922-57a2-9388-75c58f6296a0","questionId":"2acdbccb-c434-5353-b8ba-ab9b50d1b939","sourceKey":"bank:ENT211:ENT211-W08-020","payload":{"prompt":"Obtaining a Tax Identification Number (TIN) is described as which stage of business registration?","options":["Name reservation","Pre-registration","Post-registration","Filing fee payment"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Getting a TIN from FIRS is a post-registration task, done after CAC has approved the business. Options A, B and D are parts of the four main CAC steps that come before approval."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 333, $official_bank_source${"itemId":"b916ca80-8d63-513b-b3a0-f0ae5db9cc3b","questionId":"d5653b30-8103-5f8b-8969-9c3d452a743b","sourceKey":"bank:ENT211:ENT211-W08-021","payload":{"prompt":"Femi has just downloaded the electronic Certificate of Registration for his printing business. What should he do next?","options":["Complete the CAC-BN01 form","Pay the filing fees","Reserve two alternative names on the CAC portal","Obtain a Tax Identification Number from FIRS"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Once registration is approved, the next task is to get a TIN from FIRS, and this should be done immediately. Options C, A and B are earlier steps that Femi must already have completed before receiving his certificate."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 334, $official_bank_source${"itemId":"11c9851c-87a6-5018-a3ae-5a6be1ce84fc","questionId":"4b6081d8-8072-5bd3-8b7b-35a305b893ee","sourceKey":"bank:ENT211:ENT211-W08-022","payload":{"prompt":"Which of the following is NOT one of the four numbered steps of CAC business registration?","options":["Identify venues","Choose and reserve a name","Pay filing fees","Submit and await approval"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Identify Venues is a step in the 4-step networking plan, not in business registration. Options B, C and D are genuine CAC registration steps, along with completing the CAC-BN01 form."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 335, $official_bank_source${"itemId":"5f778d15-376d-561d-adf8-5f0ef9afb03e","questionId":"b7f21dae-41fb-5fdc-8f45-d9a8f728d512","sourceKey":"bank:ENT211:ENT211-W08-023","payload":{"prompt":"In step 4 of the registration process, 'Submit and Await Approval', who processes the application?","options":["The applicant's bank","The Federal Inland Revenue Service (FIRS)","A networking group","The Corporate Affairs Commission (CAC)"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"In step 4, CAC processes the application and, if approved, issues the electronic certificate. Option B, FIRS, only comes in afterwards for the TIN, and options A and C do not approve registrations."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 336, $official_bank_source${"itemId":"429219a2-5812-59db-b1ac-8aaf74cb58fe","questionId":"ce73daff-221f-5891-8d08-ca93a2a9c089","sourceKey":"bank:ENT211:ENT211-W08-024","payload":{"prompt":"In step 3 of CAC registration, how are the prescribed filing fees paid?","options":["In cash at any FIRS office","By cheque at a SMEDAN office","Online","At the first networking event attended"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The prescribed filing fees are paid online, matching the fact that the whole process is mainly done online through the iCRP Portal. Options A, B and D name offices or events that do not collect CAC filing fees."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 337, $official_bank_source${"itemId":"a725c9be-612e-5001-bf90-dd679a8dd7e7","questionId":"6d434a6e-aa7a-586f-b9d6-d33239b2a9b8","sourceKey":"bank:ENT211:ENT211-W08-025","payload":{"prompt":"What is the consequence of skipping the name search when registering a business?","options":["Errors in documents cause delays","Conflicting names cause rejection","It leads to tax penalties","A default fee must be paid"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"If you skip the name search, your chosen name may clash with an existing one and the application is rejected. Option A results from inaccurate information, option C from forgetting tax registration, and option D from missing the 28-day deadline."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 338, $official_bank_source${"itemId":"10049e38-a8e6-59c7-a9ce-4f5a32a9023d","questionId":"a337912d-9f00-5fc6-a6b1-2c1c466ee044","sourceKey":"bank:ENT211:ENT211-W08-026","payload":{"prompt":"Providing inaccurate information during business registration mainly results in","options":["a default fee after the grace period","delays, because errors in documents slow down the process","penalties for not registering for tax","rejection, because the name conflicts with another business"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Errors in documents cause delays, which is the risk of giving inaccurate information. Option D is caused by skipping the name search, option C by forgetting tax registration and option A by missing the deadline."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 339, $official_bank_source${"itemId":"f3c22467-59d4-5ed0-b0cb-0a6eb3504fdb","questionId":"d1c2d24e-7d1f-5578-93ea-bb6660d4bf14","sourceKey":"bank:ENT211:ENT211-W08-027","payload":{"prompt":"Forgetting tax registration after registering a business leads to","options":["loss of the Certified Extract","penalties","rejection of the business name","delays caused by document errors"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Failing to register for tax leads to penalties, which is why you should go to FIRS for a TIN right after CAC registration. Option C comes from skipping the name search, option D from inaccurate information, and option A is not a stated consequence."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 340, $official_bank_source${"itemId":"5fb12cfe-9336-5003-9c13-0bc109c74aaa","questionId":"0d2dd9b9-1c8d-5d78-98b4-7540e14ad61e","sourceKey":"bank:ENT211:ENT211-W08-028","payload":{"prompt":"What happens to a business owner who misses the registration deadline?","options":["They are banned from registering for one year","They are asked to pay a default fee after the 28-day grace period","Their NIN is suspended by CAC","Their business name is automatically given to another applicant"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Missing the deadline means paying a default fee once the 28-day grace period has passed. Options D, A and C sound serious but are not the stated consequence."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 341, $official_bank_source${"itemId":"a2164015-635a-58ad-b59e-f3580586d20d","questionId":"2bd37564-1fb0-54ed-9287-d2eda0b25287","sourceKey":"bank:ENT211:ENT211-W08-029","payload":{"prompt":"To avoid rejection because of name conflicts, a business owner should","options":["use a CAC-accredited agent for every business name","conduct a thorough name search and have backups","proceed to FIRS immediately after registration","double-check all addresses and NIN details"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The fix for name rejection is a thorough name search plus backup names. Option D is the fix for inaccurate information, option C is the fix for forgetting tax registration, and option A is advice meant for companies (Ltd)."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 342, $official_bank_source${"itemId":"05604193-db79-5e4a-9ee3-64a9baceb25c","questionId":"aa04d9f4-699e-5d39-b584-6ec69b1d9a6e","sourceKey":"bank:ENT211:ENT211-W08-030","payload":{"prompt":"To avoid delays caused by errors in registration documents, you should","options":["proceed to FIRS for a TIN immediately","double-check all names, addresses and NIN details","conduct a thorough name search and have backups","register as soon as you decide to start the business"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Delays come from document errors, so you should double-check all names, addresses and NIN details. Option D prevents the default fee, option C prevents name rejection and option A prevents tax penalties."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 343, $official_bank_source${"itemId":"179245db-dd32-53a8-bf28-8debc55237cb","questionId":"2df70128-b82a-5d7b-b43d-229b78038a60","sourceKey":"bank:ENT211:ENT211-W08-031","payload":{"prompt":"When should a business owner go to FIRS for a Tax Identification Number?","options":["Before reserving a business name","Only when bidding for a government contract","Only after the first year of trading","Immediately after CAC registration"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The advice is to go to FIRS for your TIN immediately after CAC registration to avoid penalties. Option A gets the order wrong, and options C and B delay tax registration, which leads to penalties."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 344, $official_bank_source${"itemId":"b778432c-3d69-53e0-824e-6978faef4511","questionId":"2e2e448a-fc35-581b-9bfc-d0f1d14455a2","sourceKey":"bank:ENT211:ENT211-W08-032","payload":{"prompt":"What is the recommended way to avoid paying a default fee for late registration?","options":["Register only after getting a TIN","Register just after the 28-day grace period ends","Wait until the business makes its first profit","Register as soon as you decide to start the business"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Registering as soon as you decide to start keeps you within the 28-day window and away from the default fee. Options C and B risk missing the deadline, and option A reverses the order, since the TIN comes after CAC registration."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 345, $official_bank_source${"itemId":"9cc99c83-a1f1-5c8d-9a2c-8c5d1966cb07","questionId":"3602fed3-0dea-5138-9eba-f99bd39ba62d","sourceKey":"bank:ENT211:ENT211-W08-033","payload":{"prompt":"For which type of business is using a CAC-accredited agent recommended to prevent costly mistakes?","options":["Informal networking groups","Strategic alliances","Companies (Ltd)","Business plans"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Professional help from a CAC-accredited agent is advised for companies (Ltd), where mistakes can be costly. Options B and A are forms of collaboration that do not create a registered entity, and option D is a document, not a business type."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 346, $official_bank_source${"itemId":"610d0618-b0df-525c-a89e-45d2f68350ed","questionId":"c48e69ed-c57c-5997-a771-441cc403c54f","sourceKey":"bank:ENT211:ENT211-W08-034","payload":{"prompt":"Which professional can help a company (Ltd) prevent costly registration mistakes?","options":["A CAC-accredited agent","A FIRS tax collector","A SMEDAN field officer","A LinkedIn group admin"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A CAC-accredited agent is approved to handle CAC registrations and can help companies avoid costly errors. Options B, C and D are not the professional recommended for this."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 347, $official_bank_source${"itemId":"d02726a8-4339-5924-a8ef-892129aef098","questionId":"e093f8c8-0329-5134-97a5-61666f3abbee","sourceKey":"bank:ENT211:ENT211-W08-035","payload":{"prompt":"Which of the following is NOT one of the common registration pitfalls to avoid?","options":["Failing to join a strategic alliance","Skipping the name search","Forgetting tax registration","Providing inaccurate information"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The registration pitfalls are skipping the name search, giving inaccurate information, forgetting tax registration and missing deadlines, so options B, D and C are real pitfalls. A strategic alliance is a form of business collaboration and has nothing to do with registration errors."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 348, $official_bank_source${"itemId":"181e5582-b7b2-5bf3-ab57-3525d3932f31","questionId":"e49bc6d6-454b-549e-903c-5a69618f826a","sourceKey":"bank:ENT211:ENT211-W08-036","payload":{"prompt":"Kunle's business registration has been held up for weeks because the address on his documents does not match his NIN record. Which pitfall did he fall into?","options":["Skipping the name search","Forgetting tax registration","Providing inaccurate information","Missing the deadline"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Mismatched details are errors in documents, which cause delays; this is the pitfall of providing inaccurate information. Option A leads to name rejection, option B to tax penalties and option D to a default fee."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 349, $official_bank_source${"itemId":"2fcd17b4-391d-53e1-bda4-6999b08fcea9","questionId":"9cfd55f0-0d4e-5198-aa0d-c216d0c9e9e7","sourceKey":"bank:ENT211:ENT211-W08-037","payload":{"prompt":"Bisi's application to register 'Bisi Foods' is rejected because an existing business already uses a very similar name. Which pitfall did she fall into?","options":["Missing the deadline","Forgetting tax registration","Providing inaccurate information","Skipping the name search"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Rejection because of a conflicting name is the result of skipping the name search. Option C causes delays rather than name rejection, option B causes tax penalties and option A causes a default fee."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 350, $official_bank_source${"itemId":"3c489a7b-f414-5d8e-a317-62626be41784","questionId":"7ee3ce22-dadc-5839-9b84-9662e660c444","sourceKey":"bank:ENT211:ENT211-W08-038","payload":{"prompt":"A formal business arrangement where two or more parties combine resources and share management responsibilities, profits and liabilities for an ongoing business is called a","options":["Joint venture","Strategic alliance","Partnership","Networking"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A partnership is a formal arrangement in which two or more parties pool what they have and share management, profits and liabilities for an ongoing business. Option B keeps the parties independent, option A creates a new separate entity for a shared objective, and option D is informal."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 351, $official_bank_source${"itemId":"6ce65453-695e-5ee4-a55d-94d12332b88b","questionId":"72ff7156-9a14-5eb3-b09d-83c716bed3d6","sourceKey":"bank:ENT211:ENT211-W08-039","payload":{"prompt":"A collaborative agreement between two or more independent organizations to pursue mutually beneficial goals while maintaining their autonomy is a","options":["Strategic alliance","Networking","Joint venture","Partnership"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A strategic alliance lets independent organizations work together on shared goals while keeping their autonomy. Option D involves sharing management and liabilities in one business, option C creates a new jointly owned entity, and option B has no formal agreement."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 352, $official_bank_source${"itemId":"3a67ae73-c719-5bc3-8d84-91c11861a627","questionId":"abc3e0e7-10d7-5d0c-b06b-5a05327e63ec","sourceKey":"bank:ENT211:ENT211-W08-040","payload":{"prompt":"A type of strategic alliance where the partnering firms create a new, jointly owned, separate legal entity to pursue a shared, often time-bound, objective is a","options":["Joint venture","Networking","Sole proprietorship","Partnership"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A joint venture is the form where partner firms set up a new, jointly owned, separate legal entity. Option D is a single entity for ongoing business, option B creates no entity at all, and option C is a one-owner business, not a collaboration."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 353, $official_bank_source${"itemId":"b8d4d5bb-b8be-53de-b649-5b6469c29e9d","questionId":"9b421277-907b-51c5-8f67-f05d99c85366","sourceKey":"bank:ENT211:ENT211-W08-041","payload":{"prompt":"The informal process of building relationships and connections with other professionals or businesses for potential future collaboration, information exchange and career development is called","options":["Joint venture","Networking","Partnership","Strategic alliance"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Networking is the informal building of relationships for future collaboration, information exchange and career development. Options D, C and A all involve formal agreements, which networking does not."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 354, $official_bank_source${"itemId":"4715d06b-5b59-55ca-847d-b5cdbc16a42f","questionId":"0a68e68e-9c3c-56a1-a43d-2fa8a6a677f1","sourceKey":"bank:ENT211:ENT211-W08-042","payload":{"prompt":"The Wintel alliance between Microsoft and Intel is a famous example of which form of business collaboration?","options":["Networking","Joint venture","Strategic alliance","Partnership"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Wintel is a famous tech-industry example of a strategic alliance, where two independent firms cooperate while keeping their autonomy. Option B would require a new jointly owned company, option D would mean sharing one ongoing business, and option A has no formal agreement."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 355, $official_bank_source${"itemId":"ac9f4329-00a1-5cf3-8212-e22eb27f5f08","questionId":"cb03274c-9e44-5937-86ec-2511b4e1ab56","sourceKey":"bank:ENT211:ENT211-W08-043","payload":{"prompt":"The Wintel alliance, a famous strategic alliance in the tech industry, is between which two companies?","options":["Microsoft and Intel","Wipro and Intel","Microsoft and IBM","Western Digital and Intel"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The name Wintel comes from Microsoft (maker of Windows) and Intel. Options C, B and D each pair the wrong companies."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 356, $official_bank_source${"itemId":"7843fe32-a388-5f68-97ec-2ce8525db55f","questionId":"743144a4-71a1-5258-b423-2f97bf2f0fb9","sourceKey":"bank:ENT211:ENT211-W08-044","payload":{"prompt":"A joint venture is described as a specific type of","options":["networking","strategic alliance","partnership","sole proprietorship"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A joint venture is a special kind of strategic alliance in which the partners go further and create a new jointly owned legal entity. Options C, A and D are not what a joint venture is classified under."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 357, $official_bank_source${"itemId":"cfe0aee4-0452-5e4d-8200-0707204a78c7","questionId":"b97b22a0-70f7-56e9-9455-a48c468c064f","sourceKey":"bank:ENT211:ENT211-W08-045","payload":{"prompt":"Which form of business collaboration does NOT involve formal agreements, shared capital or a common business goal at the outset?","options":["Partnership","Joint venture","Strategic alliance","Networking"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Networking is informal and, unlike the other forms, has no formal agreements, shared capital or common business goal at the start. Options A, C and B all rest on formal agreements."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 358, $official_bank_source${"itemId":"94886f35-84ab-5d98-a710-6c7feb9131c1","questionId":"d438f8a7-f4ff-5968-b4a7-5999be5661ea","sourceKey":"bank:ENT211:ENT211-W08-047","payload":{"prompt":"Strategic alliances often involve contractual agreements for specific activities. Which of the following is NOT one of those activities?","options":["Distribution","Joint marketing","Creating a new jointly owned company","Research"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Strategic alliances cover specific activities such as joint marketing, research or distribution, so options B, D and A are typical. They do this without creating a new company; forming a new jointly owned entity is what a joint venture does."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 359, $official_bank_source${"itemId":"d5f6609b-e2d9-5390-9e13-6f4f0306594e","questionId":"a0226df2-53f6-591d-a364-072486dab7eb","sourceKey":"bank:ENT211:ENT211-W08-048","payload":{"prompt":"Compared with joint ventures, strategic alliances are generally","options":["more formal and legally separate","more flexible and less integrated","identical in structure and commitment","less flexible and more integrated"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Alliances are generally more flexible and less integrated than joint ventures, because no new company is formed. Option D reverses this, option A actually describes a joint venture, and option C ignores the real differences."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 360, $official_bank_source${"itemId":"e805783c-d9f1-508a-b4de-d48406cfd477","questionId":"acff3ca6-ea89-5adc-bcd5-61136249a9dc","sourceKey":"bank:ENT211:ENT211-W08-049","payload":{"prompt":"The objective a joint venture is set up to pursue is described as shared and often","options":["unrelated to profit","informal","open-ended and permanent","time-bound"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A joint venture pursues a shared objective that is often time-bound, meaning it has a set period or end point. Option B describes networking, option C fits better with a long-term partnership, and option A is not stated."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 361, $official_bank_source${"itemId":"9aa03a65-a054-5b48-a802-5b428aa0bbfa","questionId":"98148e14-3f90-5aad-967a-696222a5290d","sourceKey":"bank:ENT211:ENT211-W08-050","payload":{"prompt":"Which of the following is NOT listed as an advantage of the joint venture structure?","options":["It gives access to new markets or technologies they couldn't reach alone","It allows companies to share risks and costs","It allows companies to pool significant resources","It avoids any legal or governance framework"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A joint venture lets firms pool their assets, share risks and costs, and reach new markets or technologies, so options C, B and A are real advantages. It actually comes with a clear legal and governance framework, so saying it avoids one is false."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 362, $official_bank_source${"itemId":"a6963dfc-bdac-5bfe-bdd7-9776b9b6c37d","questionId":"a503ca4f-8b9e-5095-ac5f-cf20d7c0d7e7","sourceKey":"bank:ENT211:ENT211-W08-051","payload":{"prompt":"Networking is done for potential future collaboration, information exchange and career development. Which of the following is NOT a feature of networking?","options":["Building relationships with other professionals","Exchanging information","Developing one's career","Shared capital invested in a common business"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Networking builds relationships for future collaboration, information exchange and career development, so options A, B and C fit it. It does not involve shared capital or a common business goal at the outset."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 363, $official_bank_source${"itemId":"3cdfd9e9-9042-5af3-b789-6d2ee97c2472","questionId":"d5138154-8d23-5c05-8483-f0a5a8e4bf3f","sourceKey":"bank:ENT211:ENT211-W08-052","payload":{"prompt":"An oil company and a Nigerian engineering firm form a brand-new company that they jointly own to build and run a refinery project for ten years. Which form of collaboration is this?","options":["Strategic alliance","Networking","Joint venture","Partnership"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Creating a new, jointly owned, separate company for a specific, time-bound project is a joint venture. Option A would not create a new company, option D is one ongoing business shared by the partners, and option B is informal."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 364, $official_bank_source${"itemId":"874a6ced-e579-59ba-bf37-9df947a3f92b","questionId":"26ee161a-d742-5940-890c-696d45215a65","sourceKey":"bank:ENT211:ENT211-W08-053","payload":{"prompt":"A Lagos fintech and a telecom company sign a contract to jointly market a mobile wallet, while each remains a fully independent company and no new company is formed. Which form of collaboration is this?","options":["Partnership","Joint venture","Strategic alliance","Networking"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A contract for a specific activity like joint marketing, with both firms staying independent and no new company formed, is a strategic alliance. Option B would need a new jointly owned entity, option A merges them into one shared business, and option D has no formal contract."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 365, $official_bank_source${"itemId":"3cc130a7-35fc-517b-b241-162e7a035180","questionId":"cdda0b9b-8ed6-5296-8b50-8d93061af039","sourceKey":"bank:ENT211:ENT211-W08-054","payload":{"prompt":"Ngozi and Ibrahim pool their savings to run a pharmacy in Ikeja together, sharing management responsibilities, profits and liabilities on an ongoing basis. Which form of collaboration is this?","options":["Strategic alliance","Joint venture","Networking","Partnership"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Two people combining what they have and sharing management, profits and liabilities in an ongoing business is a partnership. Option A keeps parties independent, option B creates a new entity for a specific objective, and option C is just relationship building."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 366, $official_bank_source${"itemId":"ca2d7254-2293-5e99-8d47-15ab48eaefaf","questionId":"07064602-e4eb-51d0-b297-5a6a59f36299","sourceKey":"bank:ENT211:ENT211-W08-055","payload":{"prompt":"A UNILAG student attends tech meetups to meet professionals and swap ideas, without signing any agreement or putting in money. Which form of collaboration is this?","options":["Strategic alliance","Joint venture","Partnership","Networking"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Building relationships informally, with no agreement or shared capital, is networking. Options A, C and B all involve formal agreements between the parties."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 367, $official_bank_source${"itemId":"c3f718fd-3464-592b-bf43-917766b61a98","questionId":"d7a56697-a64c-5df3-97f9-c5f4072b8314","sourceKey":"bank:ENT211:ENT211-W08-056","payload":{"prompt":"Partnerships, alliances, joint ventures and networking differ primarily in their","options":["size, location and number of employees","products, prices and promotion","formality, legal structure and objectives","age, industry and annual turnover"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The forms of collaboration differ mainly in how formal they are, their legal structure and their objectives. Options A, B and D are other business features, not the stated basis of comparison."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 368, $official_bank_source${"itemId":"b1cd0ed8-4780-5dab-9bf8-3ca8fb55e840","questionId":"bd9861a1-d335-5b62-baed-49e5ca423bb8","sourceKey":"bank:ENT211:ENT211-W08-057","payload":{"prompt":"The main distinction between the forms of business collaboration lies in","options":["whether a new legal entity is formed and the level of integration and commitment involved","how many employees each partner has","how much each partner spends on advertising","whether the partners are located in the same city"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The key difference is whether a new legal entity is created and how integrated and committed the parties are. Options B, D and C are not the stated main distinction."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 369, $official_bank_source${"itemId":"35bc1a3b-5002-5867-ad73-5a41fa2980cc","questionId":"28404ea7-8a27-54e5-b8c2-b52a293163a3","sourceKey":"bank:ENT211:ENT211-W08-058","payload":{"prompt":"Which form of business collaboration creates a new, separate legal entity that is jointly owned?","options":["Partnership","Joint venture","Networking","Strategic alliance"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Only a joint venture creates a new, separate, jointly owned legal entity. Option D creates no new entity as partners stay independent, option A is a single entity made up of the partners themselves, and option C creates no entity."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 370, $official_bank_source${"itemId":"be455e6b-9841-53bd-b0cd-f7201d963272","questionId":"6515117a-5fbb-53a1-a3cc-8132dfba82a3","sourceKey":"bank:ENT211:ENT211-W08-059","payload":{"prompt":"In terms of legal entity, a strategic alliance is described as","options":["a single entity of two or more persons or companies","a new, separate legal entity, jointly owned","a government-registered cooperative","no new entity created; partners remain independent"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"In a strategic alliance no new entity is formed and the partners stay independent. Option A describes a partnership, option B describes a joint venture, and option C is not part of the comparison."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 371, $official_bank_source${"itemId":"4feba73b-7175-56d2-b0a6-91189eb67fcd","questionId":"4faa917d-ec1e-5442-8da8-94d5f23b0ab1","sourceKey":"bank:ENT211:ENT211-W08-060","payload":{"prompt":"In terms of legal entity, a partnership is described as","options":["a single entity (two or more persons/companies)","no new entity; partners remain independent","a new, separate legal entity, jointly owned","no entity, only informal relationships"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A partnership is a single entity made up of two or more persons or companies. Option B describes a strategic alliance, option C a joint venture, and option D networking."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 372, $official_bank_source${"itemId":"fa92746f-e2b1-5d60-b91a-6f85d5ef3d09","questionId":"9e33b212-f8b2-520a-868a-5fb4ee8ff55f","sourceKey":"bank:ENT211:ENT211-W08-061","payload":{"prompt":"In terms of formality, a joint venture is described as","options":["highly formal, contractual agreement","formal, typically long-term","informal relationship building","formal agreement, but looser than a JV"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A joint venture is the most formal arrangement, based on a highly formal contractual agreement. Option D describes a strategic alliance, option B a partnership, and option C networking."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 373, $official_bank_source${"itemId":"02f9f299-d49f-5117-a8ff-eadaea612b20","questionId":"1e0fa2ce-5aa8-5834-8285-785bb79db23a","sourceKey":"bank:ENT211:ENT211-W08-062","payload":{"prompt":"In terms of formality, a strategic alliance is described as","options":["formal agreement, but looser than a JV","informal relationship building","no agreement of any kind","highly formal, contractual agreement"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A strategic alliance rests on a formal agreement, but it is looser than a joint venture. Option D describes a joint venture, and option B describes networking. Option C cannot be right because an alliance is, by definition, built on an agreement between the partners."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 374, $official_bank_source${"itemId":"8f6a2f3d-13c6-5878-8d35-a410c99a9ae7","questionId":"42c844eb-ab14-5637-913a-f53aed0c5171","sourceKey":"bank:ENT211:ENT211-W08-063","payload":{"prompt":"Which form of business collaboration is described as 'formal, typically long-term'?","options":["Networking","Strategic alliance","Joint venture","Partnership"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A partnership is formal and typically long-term, as it runs an ongoing business. Option C is highly formal but usually for a single, often time-bound objective, option A is informal, and option B is formal but looser than a joint venture."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 375, $official_bank_source${"itemId":"d5a0d8b4-23fb-56c4-bba3-db43d58f2425","questionId":"708948ab-821b-5644-9289-6309baef7f20","sourceKey":"bank:ENT211:ENT211-W08-064","payload":{"prompt":"The objective of a partnership is best described as","options":["a single, specific project or objective","ongoing general business for profit","information exchange and relationship building","specific goals such as R&D or marketing"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A partnership exists to carry on ongoing general business for profit. Option A is the objective of a joint venture, option C of networking, and option D of a strategic alliance."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 376, $official_bank_source${"itemId":"0e809f16-d9bd-593d-bee4-46b85765c3d9","questionId":"26cb51b4-293d-501c-b42d-81f554830e94","sourceKey":"bank:ENT211:ENT211-W08-065","payload":{"prompt":"Which form of business collaboration has the objective of a single, specific project or objective?","options":["Networking","Partnership","Joint venture","Strategic alliance"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A joint venture is set up for a single, specific project or objective. Option B is for ongoing general business, option A is for information exchange and future opportunities, and option D targets specific mutually beneficial goals without a new entity."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 377, $official_bank_source${"itemId":"29a2c120-50f9-57f3-b227-8b5d8f89d2a5","questionId":"87b95ef3-52ed-5cf6-94fa-0580cd4595e3","sourceKey":"bank:ENT211:ENT211-W08-066","payload":{"prompt":"The objective of a strategic alliance is described as specific, mutually beneficial goals such as","options":["ongoing general business for profit","R&D and marketing","creating a new jointly owned company","career development only"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Strategic alliances pursue specific, mutually beneficial goals, with R&D and marketing given as examples. Option A is the partnership objective, option C is what a joint venture does, and option D is linked with networking."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 378, $official_bank_source${"itemId":"342e22db-47a7-5a4c-9b64-30641701fe48","questionId":"d8a571e6-7de3-5f44-8072-aa4dc73d1378","sourceKey":"bank:ENT211:ENT211-W08-067","payload":{"prompt":"Which form of collaboration has the objective of 'information exchange, relationship building, future opportunities'?","options":["Strategic alliance","Networking","Joint venture","Partnership"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Networking aims at exchanging information, building relationships and opening future opportunities. Option A pursues specific goals like R&D, option D runs ongoing business for profit, and option C targets a single project."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 379, $official_bank_source${"itemId":"7b493c0f-a505-5862-b320-d50caec16c75","questionId":"6b0156fd-be06-5139-af00-522d4f00f747","sourceKey":"bank:ENT211:ENT211-W08-068","payload":{"prompt":"Which form of business collaboration carries minimal financial risk?","options":["Joint venture","Networking","Strategic alliance","Partnership"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Networking involves minimal financial risk because no capital is shared and no entity is created. Option A involves pooled money and shared risks, option D shares management and liability, and option C still involves a formal commitment."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 380, $official_bank_source${"itemId":"320ecff3-4e9c-58fd-8377-4da5dae2fb8f","questionId":"c479c7a6-4d08-5a9f-a7ca-b9b51295feb4","sourceKey":"bank:ENT211:ENT211-W08-069","payload":{"prompt":"In terms of risk and control, a partnership is characterised by","options":["shared management and liability","no shared control at all","minimal financial risk","greater flexibility, less control than a JV"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Partners share both the management of the business and its liability. Option C describes networking, option D describes a strategic alliance, and option B contradicts the shared management of a partnership."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 381, $official_bank_source${"itemId":"b5f8425d-24fa-56e4-8a36-44ad7f342ee3","questionId":"f52cfcbf-98ad-543f-8664-45677dd493a7","sourceKey":"bank:ENT211:ENT211-W08-070","payload":{"prompt":"Which form of collaboration is described as having greater flexibility, but less control and commitment, than a joint venture?","options":["Partnership","Sole proprietorship","Strategic alliance","Networking"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"A strategic alliance offers greater flexibility with less control and commitment than a joint venture. Option A is defined by shared management and liability, option D by minimal financial risk, and option B is not a form of collaboration."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 382, $official_bank_source${"itemId":"64cb98f2-fa68-5fb4-839f-0a2e6127e9c8","questionId":"886cb783-d958-5c37-9785-85fc1cca519d","sourceKey":"bank:ENT211:ENT211-W08-071","payload":{"prompt":"In terms of risk and control, a joint venture involves","options":["no shared control because partners stay independent","pooled resources and shared risks/costs, with shared control","minimal financial risk","greater flexibility and less commitment"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"In a joint venture, partners pool their assets and share risks, costs and control. Option C describes networking, option D describes a strategic alliance, and option A wrongly removes the shared control."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 383, $official_bank_source${"itemId":"a3a8666a-ab24-5202-aa84-f65ffd17789c","questionId":"470e70cd-2a56-5375-b059-ca84abb917d6","sourceKey":"bank:ENT211:ENT211-W08-072","payload":{"prompt":"Which of the following is NOT one of the steps in the simple 4-step networking plan?","options":["Identify venues","Maintain","Goal","Choose and reserve a name"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The 4-step networking plan is Goal, Identify Venues, Engage and Maintain, so options C, A and B are genuine steps. Choosing and reserving a name is the first step of CAC business registration."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 384, $official_bank_source${"itemId":"ed0d715e-c8af-5b6e-92f9-12fe2fe5ed74","questionId":"073ecd13-cd9e-5d2e-9843-fda071dab7e0","sourceKey":"bank:ENT211:ENT211-W08-073","payload":{"prompt":"In the 4-step networking plan, the 'Goal' step asks which question?","options":["What do you need?","How will you follow up?","How will you keep in touch?","Where will you meet people?"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The Goal step asks 'What do you need?', such as a technical co-founder or product feedback. Option D matches Identify Venues, option B matches Engage, and option C matches Maintain."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 385, $official_bank_source${"itemId":"bcb287ec-d769-5f58-ac13-e130627fb938","questionId":"7ead976b-83d6-593d-8f5b-3998402b9f67","sourceKey":"bank:ENT211:ENT211-W08-074","payload":{"prompt":"Looking for a technical co-founder for an app idea, or feedback on a product from 10 potential customers, are examples given for which step of the networking plan?","options":["Maintain","Identify venues","Engage","Goal"],"correctOption":3,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"These are examples of a networking Goal, which is about knowing exactly what you need. Option B is about where to network, option C is about how you interact, and option A is about nurturing the relationship later."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 386, $official_bank_source${"itemId":"49a0b7e2-5532-510e-929a-0410afa26b6a","questionId":"8e8a37ea-9c7e-595e-81ef-6a510c32389f","sourceKey":"bank:ENT211:ENT211-W08-075","payload":{"prompt":"In the networking plan's Goal example, product feedback is sought from how many potential customers?","options":["20","48","10","5"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The example goal is to get feedback on a product from 10 potential customers. Option B comes from the 48-hour follow-up rule, and options D and A are not the stated number."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 387, $official_bank_source${"itemId":"98809626-e9df-58fd-9abe-474174f91284","questionId":"e4f24d7c-280d-59c3-b3cd-7276b8ee5bc6","sourceKey":"bank:ENT211:ENT211-W08-076","payload":{"prompt":"Which of the following is given as an ONLINE venue for networking?","options":["Attending Lagos Startup Week","Joining groups like 'Nigeria Tech Community'","Attending meetups at Hub One by FCMB","Attending Techpoint Build"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Online venues include optimizing your LinkedIn and joining groups like 'Nigeria Tech Community'. Options A, D and C are offline venues where you meet people in person."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 388, $official_bank_source${"itemId":"97975bab-82c6-5dce-978a-76e4940facb1","questionId":"001a418f-2296-5816-9543-bfb2099a0e52","sourceKey":"bank:ENT211:ENT211-W08-077","payload":{"prompt":"Which of the following is given as an OFFLINE venue for networking?","options":["Techpoint Build","The iCRP Portal","LinkedIn","Nigeria Tech Community group"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Techpoint Build is listed among offline events, along with Lagos Startup Week and meetups at Hub One by FCMB. Options C and D are online venues, and option B is the CAC registration portal."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 389, $official_bank_source${"itemId":"0d976c2e-a3c5-51bf-be79-08ac1a7e2667","questionId":"c7d7050f-a528-56fa-bb39-400873a51307","sourceKey":"bank:ENT211:ENT211-W08-078","payload":{"prompt":"Hub One by FCMB, mentioned as a place to attend networking meetups, is located in","options":["Lekki","Victoria Island","Yaba","Ikeja"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Hub One by FCMB is in Yaba, Lagos, and is given as an offline networking venue. Options D, B and A are other Lagos areas not linked to this hub."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 390, $official_bank_source${"itemId":"f8176b01-1ea7-5dac-92cb-a57961ed838d","questionId":"70de7928-6ea4-504f-b171-04b481253feb","sourceKey":"bank:ENT211:ENT211-W08-079","payload":{"prompt":"In the Engage step of the networking plan, you should follow up with a personalized message within","options":["48 hours","24 hours","28 days","7 days"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"The advice is to follow up within 48 hours with a personalized message. Option C is the business registration deadline, and options B and D are not the stated time."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 391, $official_bank_source${"itemId":"2c05c758-60c1-5ce8-a5bd-6de29b996a15","questionId":"865fc8ea-c34c-5ca0-8a8f-85e5869dbfb7","sourceKey":"bank:ENT211:ENT211-W08-080","payload":{"prompt":"Which advice belongs to the 'Engage' step of the networking plan?","options":["Don't just collect cards; offer value, ask insightful questions and follow up","Decide what you need, such as a technical co-founder","Optimize your LinkedIn and join online groups","Share useful information and check in periodically"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Engage is about real interaction: offering value, asking insightful questions and following up, not just collecting cards. Option C is Identify Venues, option B is Goal, and option D is Maintain."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 392, $official_bank_source${"itemId":"22743ae2-b3df-5238-b72c-244cca0aa4a4","questionId":"2370d868-3b91-5ee4-a190-011cef525218","sourceKey":"bank:ENT211:ENT211-W08-081","payload":{"prompt":"Months after meeting a mentor at a startup event, Seyi still shares useful articles with her, introduces her to other founders and checks in now and then. Which step of the networking plan is Seyi practising?","options":["Maintain","Identify venues","Engage","Goal"],"correctOption":0,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Maintain means nurturing relationships by sharing useful information, making introductions and checking in periodically. Option C is the first interaction and 48-hour follow-up, option B is choosing where to network, and option D is deciding what you need."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 393, $official_bank_source${"itemId":"a6a44e4d-24d0-5e78-a6ab-ea8c20bdf894","questionId":"ba4ddc68-493d-5d67-8796-d1f4c19d5b05","sourceKey":"bank:ENT211:ENT211-W08-082","payload":{"prompt":"At Lagos Startup Week, Dayo asks a speaker thoughtful questions, offers to help with her project, and the next day sends her a personalized message. Which step of the networking plan is this?","options":["Identify venues","Engage","Goal","Maintain"],"correctOption":1,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Engage is about offering value, asking insightful questions and following up within 48 hours with a personalized message. Option D is the long-term nurturing that comes later, option C is deciding what you need, and option A is picking events like Lagos Startup Week in the first place."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 394, $official_bank_source${"itemId":"6e0310cd-e676-5b81-9aa9-3f40c9431f7f","questionId":"0cae62ad-0092-5e23-84db-b2799de56dae","sourceKey":"bank:ENT211:ENT211-W08-083","payload":{"prompt":"In the 'Maintain' step of the networking plan, which activities help nurture relationships?","options":["Signing a contract to create a jointly owned company","Collecting as many business cards as possible","Sharing useful information, making introductions and checking in periodically","Reserving a business name and paying filing fees"],"correctOption":2,"section":"Weeks 8-9: Business Registration and Collaboration","explanation":"Maintaining a network means sharing useful information, making introductions and checking in periodically. Option B is exactly what the Engage step warns against, option D belongs to business registration, and option A describes a joint venture."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 395, $official_bank_source${"itemId":"8c7baa5f-9424-5bf6-98ab-85da40c33b62","questionId":"d0d23689-f37d-58cc-83da-9ee374c75f07","sourceKey":"bank:ENT211:ENT211-W10-001","payload":{"prompt":"A very small business operation that employs a minimal number of people, operates with low capital investment, and is often owner-managed and may be informal in nature is called a","options":["Small enterprise","Large enterprise","Micro enterprise","Medium enterprise"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"This is the general definition of a micro enterprise: very few workers, low capital, usually run by the owner and often informal. Option A, a small enterprise, is bigger (10-49 employees) and mostly formal, while options D and B are larger still."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 396, $official_bank_source${"itemId":"f8a11e9c-87d2-53ae-8795-5494c3cfa3dc","questionId":"ad7fbbcb-4db0-522a-89fd-9b15f6e07b3c","sourceKey":"bank:ENT211:ENT211-W10-002","payload":{"prompt":"Which of the following best describes a micro enterprise?","options":["A formally registered firm with structured management systems and 10-49 employees","A registered business serving regional and national markets with skilled labour","A firm employing fewer than 50 people that operates with limited resources compared to large firms","A very small, often owner-managed business with minimal staff and low capital that may be informal"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"A micro enterprise is a very small operation with minimal staff and low capital, usually managed by the owner and sometimes informal. Option A describes a small enterprise, option C is the OECD description of a small enterprise, and option B lists features of small enterprises such as wider market coverage and skilled labour."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 397, $official_bank_source${"itemId":"49d42ea9-ad2a-5f34-b569-b9c47302f1be","questionId":"e7444bde-9274-5d3c-8e5f-bc812ba89a59","sourceKey":"bank:ENT211:ENT211-W10-003","payload":{"prompt":"World Bank (2020) defines micro enterprises as firms with","options":["Fewer than 5 employees","Fewer than 50 employees","Fewer than 10 employees","10-49 employees"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"World Bank (2020) uses a simple headcount rule: a micro enterprise has fewer than 10 employees. Option D (10-49) is the World Bank range for a small enterprise, and option B (fewer than 50) is how the OECD describes small enterprises."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 398, $official_bank_source${"itemId":"4cd8cddb-ea30-54ef-b70a-4b39bf5b51de","questionId":"ad54bf10-2d92-563a-860f-0c75471d2f9d","sourceKey":"bank:ENT211:ENT211-W10-004","payload":{"prompt":"Under SMEDAN (2017), the total assets (excluding land and building) of a micro enterprise must not exceed","options":["N50 million","N5 million","N49 million","N10 million"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"SMEDAN (2017) caps a micro enterprise's total assets, excluding land and building, at N5 million. Option C, N49 million, is the top of the asset range for a small enterprise, so it is far above the micro limit. Options D and A are also well above the N5 million micro ceiling."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 399, $official_bank_source${"itemId":"a8f179a5-106e-54cb-b088-9f70e556ae83","questionId":"557b0ef1-1da1-5eb0-9853-a360c06d0981","sourceKey":"bank:ENT211:ENT211-W10-005","payload":{"prompt":"When SMEDAN (2017) measures the total assets of a micro enterprise, which items are excluded?","options":["Land and building","Vehicles and furniture","Machinery and equipment","Cash and inventory"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"SMEDAN counts total assets excluding land and building, so a business that owns its shop building is not pushed into a higher class because of property. Options C, D and B are all counted as part of total assets; only land and building are left out."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 400, $official_bank_source${"itemId":"8c623b4a-e858-5dc1-a215-ec82c07cb645","questionId":"956e4ce7-a183-5803-967c-ad5bf34f0d58","sourceKey":"bank:ENT211:ENT211-W10-006","payload":{"prompt":"Which body defines a micro enterprise in Nigeria as a business with less than 10 employees and total assets (excluding land and building) not exceeding N5 million?","options":["OECD","World Bank (2020)","SMEDAN (2017)","McKinsey (2022)"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"SMEDAN (2017) is the Nigerian definition, and it uses two tests: fewer than 10 employees and assets not above N5 million. Option B, World Bank (2020), also uses fewer than 10 employees but gives no naira asset limit, and option A, the OECD, describes small enterprises rather than micro ones. Option D is associated with a definition of innovation, not enterprise size."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 401, $official_bank_source${"itemId":"052c2b36-92cd-5043-afed-fb88a4681837","questionId":"b7219d24-c4e3-5dde-8725-87f46fee9058","sourceKey":"bank:ENT211:ENT211-W10-007","payload":{"prompt":"Tunde runs a barbing salon in Yaba with 4 employees and total assets (excluding land and building) of N3 million. Under SMEDAN (2017), his business is a","options":["Medium enterprise","Small enterprise","Micro enterprise","Large enterprise"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"With fewer than 10 employees and assets below N5 million, Tunde's salon meets both SMEDAN tests for a micro enterprise. Option B would need 10-49 employees and assets between N5 million and N49 million, and options A and D are even bigger categories."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 402, $official_bank_source${"itemId":"8da4b584-e021-5057-a703-fd85fd54624a","questionId":"c5ed2f69-c97b-5ed5-812d-5256ec96b6fb","sourceKey":"bank:ENT211:ENT211-W10-008","payload":{"prompt":"A bakery in Surulere has 25 employees and total assets (excluding land and buildings) of N20 million. Under SMEDAN (2017), it is classified as a","options":["Medium enterprise","Micro enterprise","Large enterprise","Small enterprise"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"SMEDAN defines a small enterprise as one with 10-49 employees and assets between N5 million and N49 million, and the bakery fits both ranges. Option B would require fewer than 10 employees and assets not above N5 million, so the bakery is too big to be micro."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 403, $official_bank_source${"itemId":"567fe0db-241e-58a2-acb9-1aae109742e6","questionId":"3bbf7e36-4dd6-5a8d-ba0c-86ac3459e307","sourceKey":"bank:ENT211:ENT211-W10-009","payload":{"prompt":"According to SMEDAN (2017), a small enterprise has how many employees?","options":["10-49","50-199","Fewer than 10","Fewer than 50"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"SMEDAN places small enterprises in the 10-49 employee band. Option C is the micro enterprise rule, and option D reflects the OECD description of small firms (fewer than 50 people)."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 404, $official_bank_source${"itemId":"97631f27-4ff2-5251-b14f-05c8e60e36f2","questionId":"2a5db5d3-27a9-5dda-9c60-3f8b745ac683","sourceKey":"bank:ENT211:ENT211-W10-010","payload":{"prompt":"Under SMEDAN (2017), the total assets of a small enterprise (excluding land and buildings) are","options":["Between N10 million and N50 million","Between N5 million and N49 million","Not exceeding N5 million","Above N49 million"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"A small enterprise holds between N5 million and N49 million in total assets, not counting land and buildings. Option C is the asset limit for a micro enterprise, while options A and D are not ranges used in the SMEDAN definition."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 405, $official_bank_source${"itemId":"19ba2e40-e839-5b7e-9ab5-b8c4a056e6b4","questionId":"a3dbb1d6-5d5d-586b-8d9b-4540452e81f7","sourceKey":"bank:ENT211:ENT211-W10-011","payload":{"prompt":"The World Bank (2020) defines a small enterprise as a firm that","options":["Employs fewer than 10 people","Employs fewer than 50 people and operates with limited resources","Has total assets between N5 million and N49 million","Employs 10-49 people"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"World Bank (2020) uses headcount only: a small enterprise employs 10-49 people. Option A is its micro enterprise definition, option B is the OECD description, and option C is part of SMEDAN's Nigerian definition, which adds an asset test."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 406, $official_bank_source${"itemId":"e615cbea-97c0-519a-9303-8eca41be8b87","questionId":"208ba075-6926-5344-b98f-eb7c8fbef2ec","sourceKey":"bank:ENT211:ENT211-W10-012","payload":{"prompt":"Which organisation describes small enterprises as firms that employ fewer than 50 people and operate with limited resources compared to large firms?","options":["OECD","McKinsey (2022)","SMEDAN (2017)","World Bank (2020)"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"The OECD describes small enterprises by headcount (fewer than 50 people) and by having limited resources compared to large firms. Option C, SMEDAN, uses 10-49 employees plus an asset range, and option D, the World Bank, uses 10-49 people. Option B is linked to a definition of innovation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 407, $official_bank_source${"itemId":"fe5a6890-533b-5464-a988-d0b3901e588d","questionId":"c5a24f99-b9b7-55e6-9054-902b6a04ff53","sourceKey":"bank:ENT211:ENT211-W10-013","payload":{"prompt":"How does the OECD describe small enterprises?","options":["Firms with fewer than 10 employees","Firms that employ fewer than 50 people and operate with limited resources compared to large firms","Businesses with less than 10 employees and assets not exceeding N5 million","Enterprises with 10-49 employees and total assets between N5 million and N49 million"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"The OECD view focuses on size and resources: fewer than 50 people and limited resources compared to large firms. Option D is SMEDAN's definition of a small enterprise, option A is the World Bank definition of a micro enterprise, and option C is SMEDAN's micro enterprise definition."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 408, $official_bank_source${"itemId":"eaa54439-317f-5c4d-99b5-358978d9d55f","questionId":"62dc652f-40a7-593f-966f-b1fb5d04be4a","sourceKey":"bank:ENT211:ENT211-W10-014","payload":{"prompt":"In the definitions of enterprise size, SMEDAN stands for","options":["Small and Micro Enterprises Development Authority of Nigeria","Small Manufacturing Enterprises Development Association of Nigeria","Small and Medium Enterprises Directorate Agency of Nigeria","Small and Medium Enterprise Development Agency of Nigeria"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"SMEDAN is the Small and Medium Enterprise Development Agency of Nigeria, the Nigerian body whose 2017 definitions classify micro and small enterprises. Options A, C and B swap in words like Authority, Directorate or Association that are not part of the agency's name."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 409, $official_bank_source${"itemId":"cd877f0e-8952-5528-8505-802dac730c29","questionId":"9043bc89-a629-5cef-b614-a117d87a285e","sourceKey":"bank:ENT211:ENT211-W10-015","payload":{"prompt":"Which characteristic of micro enterprises means they require minimal financial investment to start and operate?","options":["Owner-Dependent Operations","Moderate Capital Base","Low Start-Up Capital","Limited Access to Credit"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Low Start-Up Capital means a micro business needs only a little money to begin and keep running. Option B, Moderate Capital Base, is a feature of small enterprises, and option D is about difficulty getting bank loans, not how much money is needed to start."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 410, $official_bank_source${"itemId":"3b449b65-5efc-5261-8202-51ee21a6066d","questionId":"20208b9e-0d28-5612-97ba-0dccceeeeefe","sourceKey":"bank:ENT211:ENT211-W10-016","payload":{"prompt":"A micro enterprise that relies on basic tools and manual processes rather than advanced technology shows which characteristic?","options":["Low Start-Up Capital","Informal Business Structure","Restricted Market Coverage","Limited Use of Technology"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Limited Use of Technology describes micro businesses that work with basic tools and manual methods instead of advanced technology. Option B is about operating without full registration, and option C is about serving only local markets."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 411, $official_bank_source${"itemId":"14962d0e-b668-5030-801c-d086b639fb88","questionId":"5c34ff87-e4f1-57e0-99c2-41427d570660","sourceKey":"bank:ENT211:ENT211-W10-017","payload":{"prompt":"When the success of a micro enterprise depends largely on the owner's skills, effort and decisions, this characteristic is called","options":["Owner-Dependent Operations","Structured Management Systems","High Business Mortality Rate","Informal Business Structure"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Owner-Dependent Operations means the business rises or falls with the owner's own skills, effort and decisions. Option B, Structured Management Systems, is a small enterprise feature where roles are shared, and option D is about lack of registration rather than who drives the business."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 412, $official_bank_source${"itemId":"7fb646e1-099c-5b01-9835-1998833c5ba8","questionId":"803979b0-c820-54cb-84b0-821164946076","sourceKey":"bank:ENT211:ENT211-W10-018","payload":{"prompt":"Micro enterprises that serve local or community-based markets rather than national or international markets display","options":["Restricted Market Coverage","Limited Use of Technology","Owner-Dependent Operations","Wider Market Coverage"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Restricted Market Coverage means the business sells mainly to its local area or community. Option D, Wider Market Coverage, is the opposite and belongs to small enterprises, while option B is about tools and processes, not where customers are."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 413, $official_bank_source${"itemId":"ac5e47ec-acb3-5243-b09f-b76d75d80685","questionId":"4e946611-5805-5e31-a666-76ce188ec4e6","sourceKey":"bank:ENT211:ENT211-W10-019","payload":{"prompt":"The characteristic of micro enterprises that describes operating without full registration or formal documentation is","options":["Restricted Market Coverage","Informal Business Structure","Limited Access to Credit","Formal Business Registration"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Informal Business Structure means many micro businesses run without full registration or formal papers. Option D, Formal Business Registration, is a feature of small enterprises, and option C is a consequence related to lack of collateral and records rather than registration itself."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 414, $official_bank_source${"itemId":"126de601-6444-5190-bd21-27f3a5b7695f","questionId":"1f67f5df-5d25-5c8c-a5e7-a439e5161d33","sourceKey":"bank:ENT211:ENT211-W10-020","payload":{"prompt":"Micro enterprises face challenges accessing bank loans mainly because of","options":["Strict compliance with labour and tax laws","Heavy reliance on advanced technology","Having too many skilled employees","Lack of collaterals and financial records"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Limited Access to Credit arises because micro businesses usually lack collateral and proper financial records, which banks look for before lending. Option A, compliance with labour and tax laws, is a small enterprise feature, and options B and C are the opposite of what micro businesses look like, since they rely on basic tools and are not known for large skilled workforces."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 415, $official_bank_source${"itemId":"399e80a9-aa34-53d9-9ff8-bdc608ead630","questionId":"4fc3d2d6-6d99-5bde-b65a-2d5605ba1d1e","sourceKey":"bank:ENT211:ENT211-W10-021","payload":{"prompt":"Being more vulnerable to economic shocks, inflation and policy changes gives micro enterprises a","options":["Restricted Market Coverage","High Business Mortality Rate","Growth and Expansion Orientation","Lower Business Mortality Rate"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"High Business Mortality Rate means many micro businesses fail or close because shocks like inflation and policy changes hit them hard. Option D, Lower Business Mortality Rate, is a small enterprise feature, and option C also belongs to small enterprises."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 416, $official_bank_source${"itemId":"166a094f-06bc-57e0-b61b-16067387474e","questionId":"5a91e13e-f785-53d4-a7c2-a6a2c7c75b98","sourceKey":"bank:ENT211:ENT211-W10-022","payload":{"prompt":"Which of the following is NOT a characteristic of micro enterprises?","options":["Low Start-Up Capital","High Business Mortality Rate","Formal Business Registration","Owner-Dependent Operations"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Formal Business Registration is a characteristic of small enterprises; micro enterprises instead have an Informal Business Structure. Options A, D and B are all genuine characteristics of micro enterprises."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 417, $official_bank_source${"itemId":"ff3ad0ca-e0f1-5ccb-a771-4a8484d471e6","questionId":"007ad0b7-85de-54de-87f9-0a819a1d3fd4","sourceKey":"bank:ENT211:ENT211-W10-023","payload":{"prompt":"Which of the following is NOT a characteristic of micro enterprises?","options":["Employment of Skilled Labour","Informal Business Structure","Restricted Market Coverage","Limited Access to Credit"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Employment of Skilled Labour is listed among the characteristics of small enterprises, not micro ones. Options C, D and B are all true of micro enterprises, which serve local markets, struggle to get loans and often operate informally."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 418, $official_bank_source${"itemId":"5b2a4dde-3b0e-5b46-bfa1-1c09bc2e575e","questionId":"76d08462-80d2-56ba-bb56-0d8e7387c594","sourceKey":"bank:ENT211:ENT211-W10-024","payload":{"prompt":"Which of the following is a characteristic of micro enterprises?","options":["Wider Market Coverage","Improved Record-Keeping","Owner-Dependent Operations","Structured Management Systems"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Owner-Dependent Operations is a micro enterprise trait because success rests mostly on the owner. Options D, B and A are all characteristics of small enterprises, which have structured management, better records and wider markets."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 419, $official_bank_source${"itemId":"ab4065ce-00e1-5cbf-b233-f5f3eeb03066","questionId":"695dc74c-f7d0-5ad2-9929-55d38316bc80","sourceKey":"bank:ENT211:ENT211-W10-025","payload":{"prompt":"Mama Nkechi's provision store in Mushin had to close after sudden inflation and a new government policy raised her costs. This illustrates which characteristic of micro enterprises?","options":["Restricted Market Coverage","High Business Mortality Rate","Limited Use of Technology","Low Start-Up Capital"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Micro businesses are more vulnerable to economic shocks, inflation and policy changes, which is why they have a High Business Mortality Rate. Option A is about serving local customers, and option C is about basic tools; neither explains a shop closing due to inflation and policy."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 420, $official_bank_source${"itemId":"e227f38e-8d5b-5e31-9c10-68eb631df1ad","questionId":"dad85ae0-308c-514a-af2e-55c614c92c4f","sourceKey":"bank:ENT211:ENT211-W10-026","payload":{"prompt":"Emeka, a shoemaker in Aba, is refused a bank loan because he has no collateral and keeps no financial records. Which characteristic of micro enterprises does this show?","options":["Owner-Dependent Operations","High Business Mortality Rate","Restricted Market Coverage","Limited Access to Credit"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Limited Access to Credit describes micro enterprises struggling to get bank loans because they lack collateral and financial records, which is exactly Emeka's problem. Option C, Restricted Market Coverage, is about serving local or community markets rather than national ones. Option A is about success depending on the owner's skills and effort, and B is about vulnerability to economic shocks."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 421, $official_bank_source${"itemId":"655ee10d-9b2f-5709-8527-f8ab714b7e7e","questionId":"2ca27334-c0d7-5311-b5b8-3750e8e49eec","sourceKey":"bank:ENT211:ENT211-W10-027","payload":{"prompt":"Aisha runs a one-woman tailoring shop. When she fell ill for two weeks, production stopped completely because every decision and task depended on her. This illustrates","options":["Owner-Dependent Operations","Informal Business Structure","Restricted Market Coverage","Limited Use of Technology"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Owner-Dependent Operations means the business's success depends largely on the owner's skills, effort and decisions, so when the owner is absent the business stalls. Option D is about basic tools, and option C is about serving only local customers."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 422, $official_bank_source${"itemId":"1e512757-9bdb-5289-a86b-23bb18a6d988","questionId":"a0eabf22-f332-5042-8363-8fef65e7a604","sourceKey":"bank:ENT211:ENT211-W10-028","payload":{"prompt":"Which of the following is a characteristic of small enterprises?","options":["High Business Mortality Rate","Informal Business Structure","Restricted Market Coverage","Compliance with Labour and Tax Laws"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Small enterprises are usually registered and comply with labour and tax laws. Options B, C and A are all characteristics of micro enterprises, which are often informal, serve local markets and fail more easily."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 423, $official_bank_source${"itemId":"4ff9308c-0a25-526b-9428-f2557130c8e7","questionId":"cbcb1d78-da1b-5e2b-9c98-1a2b54abd236","sourceKey":"bank:ENT211:ENT211-W10-029","payload":{"prompt":"Which of the following is NOT a characteristic of small enterprises?","options":["Use of Technology","Limited Use of Technology","Improved Record-Keeping","Higher Productivity Levels"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Limited Use of Technology is a micro enterprise trait, where businesses rely on basic tools and manual processes. Options A, C and D are all listed characteristics of small enterprises."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 424, $official_bank_source${"itemId":"d683276f-7978-5a67-9472-3e98fd41817e","questionId":"3bb89731-84e7-5d42-9597-5ee18a8cc9a3","sourceKey":"bank:ENT211:ENT211-W10-030","payload":{"prompt":"Which of the following is NOT a characteristic of small enterprises?","options":["Better Access to Finance","Owner-Dependent Operations","Growth and Expansion Orientation","Structured Management Systems"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Owner-Dependent Operations describes micro enterprises, whose success rests largely on the owner alone. Small enterprises have Structured Management Systems, a Growth and Expansion Orientation and Better Access to Finance, so options D, C and A are genuine small enterprise characteristics."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 425, $official_bank_source${"itemId":"aec0d9fa-8a72-55cf-9900-2d0800e83b47","questionId":"8b6ef788-1b69-5c02-ba06-37b0e18a9037","sourceKey":"bank:ENT211:ENT211-W10-031","payload":{"prompt":"Micro enterprises have a High Business Mortality Rate. The matching characteristic of small enterprises is","options":["Moderate Capital Base","Lower Business Mortality Rate","Higher Productivity Levels","Restricted Market Coverage"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Small enterprises have a Lower Business Mortality Rate, meaning they are less likely to fail than micro businesses. Options C and A are real small enterprise characteristics but they are about output and capital, not survival, and option D is a micro enterprise trait."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 426, $official_bank_source${"itemId":"95fc2d9c-0959-58fd-b831-9b55fc43eb12","questionId":"651a0be4-5ad8-5757-b338-1b81858847c0","sourceKey":"bank:ENT211:ENT211-W10-033","payload":{"prompt":"Micro enterprises often have an Informal Business Structure. In contrast, small enterprises are characterised by","options":["Owner-Dependent Operations","Restricted Market Coverage","Formal Business Registration","Limited Access to Credit"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Small enterprises usually have Formal Business Registration, unlike micro businesses that often operate without full registration. Options B, A and D are all characteristics of micro enterprises."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 427, $official_bank_source${"itemId":"ee0d9336-cafc-5f02-a57e-96fb65d75ea8","questionId":"97d7ff4b-1310-5522-8366-d178265d3e64","sourceKey":"bank:ENT211:ENT211-W10-034","payload":{"prompt":"A logistics company in Ikeja registers its staff for pension, deducts PAYE tax and files its company returns on time. This reflects which characteristic of small enterprises?","options":["Structured Management Systems","Compliance with Labour and Tax Laws","Improved Record-Keeping","Higher Productivity Levels"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Meeting obligations such as staff pension, PAYE and tax filings shows Compliance with Labour and Tax Laws. Option C is about keeping better books, and option A is about organised management roles; both are small enterprise traits but not what the scenario stresses."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 428, $official_bank_source${"itemId":"4f2c0a89-81dd-58be-9897-50604146aa14","questionId":"cc09289b-ae41-53bc-b8e1-0690e7e2f6f0","sourceKey":"bank:ENT211:ENT211-W10-035","payload":{"prompt":"An engineering services firm in Port Harcourt deliberately recruits qualified accountants and certified technicians. This reflects which characteristic of small enterprises?","options":["Better Access to Finance","Employment of Skilled Labour","Wider Market Coverage","Formal Business Registration"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Hiring trained and qualified workers is Employment of Skilled Labour, a feature of small enterprises. Options A, C and D are also small enterprise characteristics, but they relate to loans, market reach and registration rather than the type of workers hired."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 429, $official_bank_source${"itemId":"a231151e-0451-57da-9d66-515bd2c0b804","questionId":"e811324d-b279-5e4a-a766-0d28edcd820e","sourceKey":"bank:ENT211:ENT211-W10-036","payload":{"prompt":"A supermarket in Abeokuta opens a second branch in Ibadan and has a plan to open more branches. This reflects which characteristic of small enterprises?","options":["Lower Business Mortality Rate","Restricted Market Coverage","Moderate Capital Base","Growth and Expansion Orientation"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Planning and pursuing new branches shows a Growth and Expansion Orientation. Options A and C are small enterprise traits about survival and capital, not expansion, and option B is a micro enterprise trait."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 430, $official_bank_source${"itemId":"00f2aac7-9994-554c-9bf6-27f18e694bb1","questionId":"d8cbb2d6-419c-58b6-93f5-c5456b229511","sourceKey":"bank:ENT211:ENT211-W10-037","payload":{"prompt":"A private school in Lekki has a principal, an administrator and heads of department, each with clear responsibilities. Which characteristic of small enterprises does this show?","options":["Employment of Skilled Labour","Use of Technology","Owner-Dependent Operations","Structured Management Systems"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Clear management positions with defined responsibilities reflect Structured Management Systems. Option C is the micro enterprise opposite, where everything depends on the owner, and option A is about the workers' skills rather than how management is organised."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 431, $official_bank_source${"itemId":"badba866-bb21-5b23-91b4-6d81dd3d75b0","questionId":"9b075649-75b5-50f0-bc2a-8137940ec6d3","sourceKey":"bank:ENT211:ENT211-W10-038","payload":{"prompt":"POS (point of sale) agency businesses are an example of which category of micro enterprises?","options":["Retail and Trading","Food and Beverages","Service-Based","ICT and Creative"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"POS agency businesses are grouped with provision stores and phone accessories outlets under Retail and Trading micro enterprises. Option C covers salons, tailoring and laundry, and option D covers graphic design and social media services."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 432, $official_bank_source${"itemId":"9431a346-1ccc-581c-aaec-c9e359aac8f9","questionId":"e2308b46-e2bb-5974-8cdd-6f1f3e73bdfe","sourceKey":"bank:ENT211:ENT211-W10-039","payload":{"prompt":"Small-scale online vendors selling on Instagram, WhatsApp and Facebook are classified under which category of micro enterprises?","options":["Retail and Trading","Food and Beverages","Service-Based","ICT and Creative"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"These vendors are selling goods, so they fall under Retail and Trading micro enterprises even though they sell online. Option D is tempting because social media is involved, but ICT and Creative covers services like graphic design and social media management, not online selling of goods."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 433, $official_bank_source${"itemId":"8f63ee5f-be59-5cfd-b5b7-19dd7e9f28d3","questionId":"1bf09641-343a-5165-8a51-482797b465e6","sourceKey":"bank:ENT211:ENT211-W10-040","payload":{"prompt":"Pure water (sachet water) production units are an example of which category of micro enterprises?","options":["Retail and Trading","Agriculture-Based","Food and Beverages","Manufacturing and Craft"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Sachet water production is listed with local food vendors and small bakeries under Food and Beverages micro enterprises. Option D is tempting because it involves production, but Manufacturing and Craft covers items like soap, cosmetics, furniture and welding."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 434, $official_bank_source${"itemId":"097c2a89-f076-5d2c-ad3d-e220804bee16","questionId":"823c3cc0-c609-5b90-8ee1-46b2499e18cb","sourceKey":"bank:ENT211:ENT211-W10-041","payload":{"prompt":"Photography and videography businesses are an example of which category of micro enterprises?","options":["Manufacturing and Craft","Service-Based","Agriculture-Based","Retail and Trading"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Photography and videography are personal services, grouped with salons, tailoring and laundry under Service-Based micro enterprises. Option C, Agriculture-Based, covers poultry, fish and crop farming and agro-input sellers. Option A is for producers like soap makers and carpenters, and D is for shops, POS agents and online vendors."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 435, $official_bank_source${"itemId":"fab6c460-a4ac-5446-b4b3-8692d64ad421","questionId":"6c7c0899-49fa-5df6-9756-07630855b05d","sourceKey":"bank:ENT211:ENT211-W10-042","payload":{"prompt":"Local soap and detergent producers are an example of which category of micro enterprises?","options":["Retail and Trading","Manufacturing and Craft","Service-Based","Agriculture-Based"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Making soap and detergent is production, so it is listed under Manufacturing and Craft micro enterprises with cosmetics, furniture and welding shops. Option A would apply only to selling goods, not making them, and options D and C cover farming and services."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 436, $official_bank_source${"itemId":"5b9b3962-74d0-5ee3-b637-7b0447e274a1","questionId":"0c84b20c-4fb0-562f-9854-c2c17e341478","sourceKey":"bank:ENT211:ENT211-W10-043","payload":{"prompt":"A freelance graphic design business is an example of which category of micro enterprises?","options":["Agriculture-Based","Retail and Trading","Manufacturing and Craft","ICT and Creative"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Freelance graphic design is digital creative work, listed under ICT and Creative micro enterprises along with social media management and content creation. Option A, Agriculture-Based, covers farming and agro-input sellers, option B covers shops and vendors, and option C covers producers such as soap makers and furniture workshops."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 437, $official_bank_source${"itemId":"c4f3cfd5-fca9-5687-aac6-1058b87936a2","questionId":"64318c51-5fa8-5fb8-bce8-9e819f613893","sourceKey":"bank:ENT211:ENT211-W10-044","payload":{"prompt":"Fish farming in catfish and tilapia ponds is an example of which category of micro enterprises?","options":["Agriculture-Based","Food and Beverages","Manufacturing and Craft","Retail and Trading"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Catfish and tilapia ponds are listed under Agriculture-Based micro enterprises, alongside small poultry farms and crop farming. Option B is about preparing and selling food and drinks, such as bukaterias and bakeries, not raising fish."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 438, $official_bank_source${"itemId":"08298ee3-81c8-544e-8a63-b6e75cbc1fb4","questionId":"b41bd002-df00-5f31-b1a9-dd45f54fd17c","sourceKey":"bank:ENT211:ENT211-W10-045","payload":{"prompt":"Agro-input retail sellers are listed under which category of micro enterprises?","options":["Manufacturing and Craft","Service-Based","Agriculture-Based","Food and Beverages"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Agro-input retail sellers serve the farming sector, so they are grouped with poultry, fish and crop farming under Agriculture-Based micro enterprises. Option D, Food and Beverages, covers food vendors, small bakeries, sachet water units and home catering. Option B is for personal services like salons, and A is for producers like soap makers and carpenters."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 439, $official_bank_source${"itemId":"8cfa2de9-affa-52dc-b690-fbe6f9919023","questionId":"547a15da-3ad9-58e4-b2c4-9e27144ff3f4","sourceKey":"bank:ENT211:ENT211-W10-046","payload":{"prompt":"Which of the following is an example of an ICT and Creative micro enterprise?","options":["Content creation and digital marketing freelancers","Phone accessories and gadget sales outlets","Hairdressing salons and barbing shops","Furniture and carpentry workshops"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Content creation and digital marketing freelancers belong to ICT and Creative micro enterprises. Option B is Retail and Trading even though it involves gadgets, option C is Service-Based, and option D is Manufacturing and Craft."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 440, $official_bank_source${"itemId":"c8f6d8f1-6f63-54ae-b153-894ef810a598","questionId":"918ba265-82a6-522d-8f37-00d340439158","sourceKey":"bank:ENT211:ENT211-W10-047","payload":{"prompt":"Which of the following is an example of an Agriculture-Based micro enterprise?","options":["Small bakeries producing bread and pastries","Small printing and business centre operators","Laundry and dry-cleaning outlets","Poultry farms with small stock size"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Poultry farms with small stock size are an Agriculture-Based micro enterprise. Option A is Food and Beverages, option C is Service-Based, and option B is ICT and Creative."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 441, $official_bank_source${"itemId":"0f387a56-dd4d-51b8-aaa5-23554d62f08e","questionId":"692f05d0-bd3b-5958-9915-8aeea7d90fe3","sourceKey":"bank:ENT211:ENT211-W10-048","payload":{"prompt":"Which of the following is NOT an example of a micro enterprise?","options":["Import and export trading companies","Provision stores and neighborhood mini-shops","Mobile phone repairs","Recharge card and SIM card vending"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Import and export trading companies are listed as Trade and Commerce small enterprises, because they operate on a larger scale. Options B, D and C are all examples of micro enterprises in retail, trading and services."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 442, $official_bank_source${"itemId":"783e6320-d44f-5b91-88e7-b157619eb45a","questionId":"69e6db5b-c0f1-5813-b04d-b2f1fb641136","sourceKey":"bank:ENT211:ENT211-W10-049","payload":{"prompt":"Among the types of micro enterprises, mobile phone repairs fall under","options":["Service-oriented micro enterprises","Agriculture-based enterprises","Retail and Trading micro enterprises","Production and Craft enterprises"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Repairing phones is a service, so it is listed with salons, laundry and car wash under Service-oriented micro enterprises. Option C is tempting because phone accessories are sold in retail shops, but the repair business itself is a service."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 443, $official_bank_source${"itemId":"0269c06b-9cf6-5815-bf6f-d3b939391672","questionId":"abd99ceb-f121-5b9e-9e80-9a70583e0953","sourceKey":"bank:ENT211:ENT211-W10-050","payload":{"prompt":"Among the types of micro enterprises, a keke or okada small transport business is listed under","options":["Hospitality and Tourism enterprises","Agriculture-based enterprises","Retail and Trading micro enterprises","Production and Craft enterprises"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Keke and okada small transport businesses are listed under Retail and Trading micro enterprises, alongside provision stores, roadside fruit sellers and recharge card vending. Option B, agriculture-based enterprises, deals with farming and agro-processing, not transport. Option A is a category of small enterprises, and D covers making things like shoes, furniture and soap."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 444, $official_bank_source${"itemId":"6529a685-1bdf-5e8a-84aa-b47b1cb16a4e","questionId":"189042c0-14d0-5caf-b1e8-686b534b3e61","sourceKey":"bank:ENT211:ENT211-W10-051","payload":{"prompt":"Recharge card and SIM card vending is which type of micro enterprise?","options":["Production and Craft","Service-oriented","ICT and Digital","Retail and Trading"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Selling recharge cards and SIM cards is trading in goods, so it is a Retail and Trading micro enterprise. Option C, ICT and Digital, is a type of small enterprise covering software and IT firms, and option B covers businesses like salons and car washes."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 445, $official_bank_source${"itemId":"beee9e2f-8a3e-5c4b-820a-08dc2b1ea08d","questionId":"3586cab1-4d1a-5170-b72c-655c10f4b867","sourceKey":"bank:ENT211:ENT211-W10-052","payload":{"prompt":"Which of the following is listed under the Production and Craft type of micro enterprises?","options":["Roadside fruit and vegetable sellers","Bead making and jewelry","Cosmetic and beauty products retail","Car wash businesses"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Bead making and jewelry involves making items by hand, so it is under Production and Craft, along with shoe making and soap production. Option D is Service-oriented, while options A and C are Retail and Trading micro enterprises."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 446, $official_bank_source${"itemId":"567cc576-b44d-5725-aa56-7c69b87ebfb1","questionId":"27d1dc25-d21c-5199-9ac4-74c91c44bc34","sourceKey":"bank:ENT211:ENT211-W10-053","payload":{"prompt":"Chioma owns a small shop in Oshodi that only sells cosmetic and beauty products made by other companies. Her business is which type of micro enterprise?","options":["Production and Craft","Service-oriented","Retail and Trading","Manufacturing-Based"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Because Chioma only sells and does not make the products, her shop is Cosmetic and beauty products retail, a Retail and Trading micro enterprise. Option A would apply if she produced the items herself, and option D is a category of small enterprises."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 447, $official_bank_source${"itemId":"e007e61e-a6d4-528a-841e-0dc4bed9d69c","questionId":"e24db3f8-b9bb-56de-beea-96f90b5c7ef9","sourceKey":"bank:ENT211:ENT211-W10-054","payload":{"prompt":"Which of the following is NOT one of the types of micro enterprises?","options":["Retail and Trading","Production and Craft","Hospitality and Tourism","Service-oriented"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Hospitality and Tourism, covering hotels, travel agencies and event management, is a type of small enterprise, not a micro enterprise. The three types of micro enterprises are Production and Craft, Service-oriented, and Retail and Trading, so options A, B and D all belong to the micro list."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 448, $official_bank_source${"itemId":"c1668095-02fd-5511-979e-c9e7b2ed3132","questionId":"afcd1bfc-68d8-5ce4-b6fd-1a20994b177b","sourceKey":"bank:ENT211:ENT211-W10-055","payload":{"prompt":"Private schools and tutorial centres are which type of small enterprise?","options":["Trade and commerce enterprises","Service-oriented small enterprises","ICT and digital small enterprises","Hospitality and Tourism enterprises"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Private schools and tutorial centres provide a service (education), so they are Service-oriented small enterprises, alongside clinics and consulting firms. Option C covers software and IT firms, and option D covers hotels, travel and events."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 449, $official_bank_source${"itemId":"79ad1147-1324-5303-817f-722e72c8d929","questionId":"8ad0562a-5d8b-5207-906c-26790563cb61","sourceKey":"bank:ENT211:ENT211-W10-056","payload":{"prompt":"Accounting, auditing and consulting firms are which type of small enterprise?","options":["Manufacturing-based small enterprises","Service-oriented small enterprises","Trade and commerce enterprises","ICT and digital small enterprises"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Accounting, auditing and consulting firms sell professional services, so they are Service-oriented small enterprises. Option C is about distributing and trading goods, and option A is about producing goods."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 450, $official_bank_source${"itemId":"36189f4a-2c92-5601-9834-45b29bf7723f","questionId":"873090e9-3c88-5270-b606-20e069cdae07","sourceKey":"bank:ENT211:ENT211-W10-057","payload":{"prompt":"Wholesale distribution businesses are which type of small enterprise?","options":["Service-oriented small enterprises","Agriculture-based small enterprises","Manufacturing-based small enterprises","Trade and commerce enterprises"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Wholesale distribution is buying and reselling goods in bulk, so it falls under Trade and commerce, alongside supermarkets and import and export firms. Option A covers schools, clinics and consulting, and option C covers producers of food, soap and garments."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 451, $official_bank_source${"itemId":"d3c0fd55-9809-59ad-9de6-43cfba340864","questionId":"f90b7aa2-38b7-5022-9408-c94e9da3e30f","sourceKey":"bank:ENT211:ENT211-W10-058","payload":{"prompt":"Small-scale food processing companies producing packaged snacks, bread and fruit juice are which type of small enterprise?","options":["Manufacturing-based small enterprises","Trade and commerce enterprises","Agriculture-based small enterprises","Hospitality and Tourism enterprises"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Turning ingredients into packaged snacks, bread and juice is manufacturing, so these are Manufacturing-based small enterprises. Option C is tempting because food is involved, but it covers commercial farms, rice milling, cassava processing and input supply, and option D covers restaurants and hotels."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 452, $official_bank_source${"itemId":"f9793dce-5862-5569-85be-680bead541f5","questionId":"848f1a00-18ab-5593-b804-0d33f3d8faaf","sourceKey":"bank:ENT211:ENT211-W10-059","payload":{"prompt":"Fintech startups operating on a small scale are which type of small enterprise?","options":["Trade and commerce enterprises","Manufacturing-based small enterprises","ICT and digital small enterprises","Service-oriented small enterprises"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Small-scale fintech startups are listed under ICT and digital small enterprises, with software developers and web design firms. Option D is tempting since fintechs offer financial services, but Service-oriented covers schools, clinics, consulting and logistics."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 453, $official_bank_source${"itemId":"217dc713-dfd9-51a9-8896-a2f06e23086f","questionId":"a52d431c-24c5-5287-a8d0-4d3503e49ff2","sourceKey":"bank:ENT211:ENT211-W10-060","payload":{"prompt":"Hotels and guest houses are which type of small enterprise?","options":["Hospitality and Tourism enterprises","Service-oriented small enterprises","Agriculture-based small enterprises","Trade and commerce enterprises"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Hotels and guest houses belong to Hospitality and Tourism enterprises, together with restaurants, travel agencies and event management. Option B might seem close since hotels serve guests, but that category covers schools, clinics, consulting and logistics."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 454, $official_bank_source${"itemId":"aa903cfd-084f-5659-8bd9-743a045d3151","questionId":"38cc5617-bb04-5211-8aac-089886b3185b","sourceKey":"bank:ENT211:ENT211-W10-061","payload":{"prompt":"Event management companies are which type of small enterprise?","options":["Hospitality and Tourism enterprises","Agriculture-based small enterprises","Trade and commerce enterprises","ICT and digital small enterprises"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Event management companies are grouped with hotels, restaurants and travel agencies under Hospitality and Tourism enterprises. Option B, agriculture-based small enterprises, covers commercial farms, agro-processing and input suppliers. Option C covers wholesale and supermarkets, and D covers software, digital marketing and fintech firms."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 455, $official_bank_source${"itemId":"25c7c4c4-2db1-5bd3-9b8b-6b2a236ae585","questionId":"513c97c4-e2d7-5f1e-8906-7f7c405af1fd","sourceKey":"bank:ENT211:ENT211-W10-062","payload":{"prompt":"Agro-processing firms such as rice milling and cassava processing are which type of small enterprise?","options":["Trade and commerce enterprises","ICT and digital small enterprises","Agriculture-based small enterprises","Hospitality and Tourism enterprises"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Rice milling and cassava processing are agro-processing, which is listed under Agriculture-based small enterprises together with commercial farms and input suppliers. Option B, ICT and digital small enterprises, covers software, web design and fintech firms. Option A covers wholesale and supermarkets, and D covers hotels, restaurants and events."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 456, $official_bank_source${"itemId":"a6456fc3-b5db-5cbf-88ec-08683eedba77","questionId":"55f75c5e-32c8-5f07-b169-bd72ab153346","sourceKey":"bank:ENT211:ENT211-W10-063","payload":{"prompt":"Which of the following is NOT one of the types of small enterprises?","options":["Hospitality and Tourism enterprises","ICT and digital small enterprises","Trade and commerce enterprises","Food and Beverages enterprises"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Food and Beverages is a category of micro enterprises, covering bukaterias, small bakeries and sachet water units. Options A, C and B are all among the six types of small enterprises."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 457, $official_bank_source${"itemId":"a5a501df-2cc5-57b5-b5b9-be0087702397","questionId":"1a61bf24-cdac-5be3-85e0-5840ffd7cd74","sourceKey":"bank:ENT211:ENT211-W10-064","payload":{"prompt":"Which of the following is an example of a small enterprise rather than a micro enterprise?","options":["Small hospitals, clinics and diagnostic centres","Recharge card and SIM card vending","Local food vendors (bukaterias)","Roadside fruit and vegetable sellers"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Small hospitals, clinics and diagnostic centres are Service-oriented small enterprises, which need more staff, capital and formal structure. Options B and D are Retail and Trading micro enterprises, and option C is a Food and Beverages micro enterprise."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 458, $official_bank_source${"itemId":"99d1c558-c567-5b58-8e30-6c8a73984c8e","questionId":"66e15f81-3ee1-55c9-9e7e-a37ce60eb3d0","sourceKey":"bank:ENT211:ENT211-W10-065","payload":{"prompt":"In distinguishing micro from small enterprises, the ownership of a small enterprise is described as","options":["Owner-managed with no formal structure","Sole proprietorship, often family-owned","Sole proprietorship or partnership","Mostly informal, limited registration"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Small enterprises may be sole proprietorships or partnerships. Option B describes micro enterprise ownership, and options A and D describe micro enterprise management and registration."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 459, $official_bank_source${"itemId":"0abc01b8-e33a-5d68-9b9d-818f19295521","questionId":"5e1a99db-6d52-5201-886f-5a83aaec9787","sourceKey":"bank:ENT211:ENT211-W10-066","payload":{"prompt":"How is the management of a small enterprise described when compared with a micro enterprise?","options":["Owner-managed with no formal structure","Semi-formal management with defined roles","Sole proprietorship, often family-owned","Minimal or manual processes"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Small enterprises have semi-formal management where people have defined roles. Option A is the micro enterprise description, option D is about micro enterprise processes, and option C is about micro enterprise ownership."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 460, $official_bank_source${"itemId":"0390f668-80e5-5a77-9c50-56d91c6f1aa2","questionId":"325b08c3-06bc-50b8-96c1-e81da3a35cb9","sourceKey":"bank:ENT211:ENT211-W10-067","payload":{"prompt":"Compared with micro enterprises, which have very limited access to bank credit, small enterprises have","options":["No need for any external finance","Even more limited access to bank credit","Better access to loans and government support","Access only to informal family loans"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Small enterprises enjoy better access to loans and government support, helped by their formal registration and records. Option B reverses the comparison, and options A and D are not how small enterprises are described."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 461, $official_bank_source${"itemId":"0640fa70-5c22-5f2f-86f2-17da2e7ba10f","questionId":"67beeccf-c686-5c35-aee5-559ea03bc516","sourceKey":"bank:ENT211:ENT211-W10-068","payload":{"prompt":"In comparing micro and small enterprises, 'moderate use of technology' describes","options":["Both micro and small enterprises equally","Neither micro nor small enterprises","Micro enterprises","Small enterprises"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Moderate use of technology is the small enterprise side of the comparison. Micro enterprises are described as using minimal or manual processes, so options C and A are wrong."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 462, $official_bank_source${"itemId":"5492446a-983c-5343-9001-4cecdced439e","questionId":"d78153c4-2566-5f68-b7c0-917b85919155","sourceKey":"bank:ENT211:ENT211-W10-069","payload":{"prompt":"Small enterprises typically serve which markets?","options":["Only government contracts","Mainly international markets","Local, regional and sometimes national markets","Local or neighborhood markets only"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Small enterprises reach local, regional and sometimes national markets. Option D describes micro enterprises, which serve local or neighborhood markets, and options B and A are not used to describe either type."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 463, $official_bank_source${"itemId":"0954757f-4f30-5e47-8169-3d6c1ba66938","questionId":"950131f2-d6fd-5596-ad52-6cebc8a954f4","sourceKey":"bank:ENT211:ENT211-W10-070","payload":{"prompt":"Which pairing correctly compares micro and small enterprises on stability?","options":["Micro and Small: both highly vulnerable to shocks","Micro: more stable and sustainable; Small: high vulnerability to shocks","Micro and Small: both equally stable and sustainable","Micro: high vulnerability to shocks; Small: more stable and sustainable"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Micro enterprises are highly vulnerable to shocks, while small enterprises are more stable and sustainable. Option B reverses the two, and options A and C ignore the difference between them."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 464, $official_bank_source${"itemId":"aaef2cab-4194-5bcf-ac0c-e91d7d8796f5","questionId":"253793ac-2e38-53d8-b213-0446c124fa1b","sourceKey":"bank:ENT211:ENT211-W10-071","payload":{"prompt":"A business that keeps only poor or informal records is typical of","options":["A micro enterprise","A small enterprise","Neither micro nor small enterprises","Both micro and small enterprises equally"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Poor or informal records are a mark of micro enterprises. Small enterprises keep basic structured accounting records, so option B is wrong, and options D and C ignore the difference."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 465, $official_bank_source${"itemId":"cdefb40e-d656-5938-a8d6-83cf3a39e8e3","questionId":"0aad5e5b-ca43-5df4-b4f4-0d4ecd844d19","sourceKey":"bank:ENT211:ENT211-W10-072","payload":{"prompt":"Enabling individuals to generate income through ownership of productive assets is a contribution of micro and small businesses to","options":["Employment generation","Poverty reduction","Wealth creation","Financial independence"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Owning productive assets that generate income is how micro and small businesses contribute to wealth creation. Option D is close, but financial independence is about self-employment, income autonomy and less dependence on salaries."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 466, $official_bank_source${"itemId":"7080f0c2-2d53-544a-b2c0-9ff541057d8a","questionId":"d0ef9a8d-e3f5-5479-acec-32ad14d337a6","sourceKey":"bank:ENT211:ENT211-W10-073","payload":{"prompt":"Supporting capital accumulation and reinvestment at the household and community levels is a contribution to","options":["Wealth creation","Employment generation","Poverty reduction","Financial independence"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Building up capital and reinvesting it in households and communities is part of wealth creation. Option C is tempting, but poverty reduction is about livelihoods, household income, less inequality and better living standards."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 467, $official_bank_source${"itemId":"97bf2f32-bd4b-5ef3-ada4-a83270265d3c","questionId":"e07f0a5d-665a-5ed2-8a62-03f60bc6c292","sourceKey":"bank:ENT211:ENT211-W10-074","payload":{"prompt":"Micro and small businesses promote inclusive economic growth by distributing wealth broadly. This falls under","options":["Financial independence","Wealth creation","Poverty reduction","Employment generation"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Distributing wealth broadly to achieve inclusive growth is listed under wealth creation. Option C is the tempting choice, but under poverty reduction the related point is reducing income inequality through inclusive participation in economic activities."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 468, $official_bank_source${"itemId":"de982085-57fc-5b96-b0c0-8d9530d5ad90","questionId":"3b89c361-73d0-5574-826e-c4cf79d693be","sourceKey":"bank:ENT211:ENT211-W10-075","payload":{"prompt":"Which of the following is listed under the wealth creation role of micro and small businesses?","options":["Increasing household income and purchasing power","Providing self-employment and income autonomy","Absorbing unskilled, semi-skilled and skilled labour","Encouraging entrepreneurship and venture creation across various sectors of the economy"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Encouraging entrepreneurship and venture creation across sectors is part of wealth creation. Option C belongs to employment generation, option A to poverty reduction, and option B to financial independence."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 469, $official_bank_source${"itemId":"5d1724bc-63bc-5121-b16d-bfd59035dd8e","questionId":"d55b7ed1-1cea-5c11-89d4-27ab3cba4691","sourceKey":"bank:ENT211:ENT211-W10-076","payload":{"prompt":"Absorbing unskilled, semi-skilled and skilled labour is a contribution of micro and small businesses to","options":["Poverty reduction","Wealth creation","Financial independence","Employment generation"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Taking in workers at all skill levels is part of employment generation. Option C, financial independence, is about the owner's self-employment and income autonomy rather than hiring other workers."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 470, $official_bank_source${"itemId":"396b5957-6a08-54e8-a327-fc71d2e6aaf1","questionId":"1831d180-0f53-5570-9d14-2ce7f835b849","sourceKey":"bank:ENT211:ENT211-W10-077","payload":{"prompt":"By creating jobs, micro and small businesses reduce pressure on the public sector and large firms. This is part of their role in","options":["Wealth creation","Financial independence","Employment generation","Poverty reduction"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Reducing the pressure on government and big companies to create jobs is listed under employment generation. Option B is tempting, but financial independence speaks of reducing dependence on salaried employment and government support for the individual."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 471, $official_bank_source${"itemId":"67f6714d-1865-5a09-81b4-a4a20830acb0","questionId":"f80d453a-a916-5048-af2a-7234aa5b2b6e","sourceKey":"bank:ENT211:ENT211-W10-078","payload":{"prompt":"Providing employment opportunities for youth, women and vulnerable groups is a contribution to","options":["Financial independence","Employment generation","Poverty reduction","Wealth creation"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Opening jobs to youth, women and vulnerable groups is part of employment generation. Option C may seem close because it helps the poor, but poverty reduction is about livelihoods, household income, inequality and living standards."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 472, $official_bank_source${"itemId":"3777750b-39f1-5ed4-b96a-44543af51bde","questionId":"57d84c88-5e01-5296-bcd0-79b05f9c1911","sourceKey":"bank:ENT211:ENT211-W10-079","payload":{"prompt":"Micro and small businesses are described as a major source of job creation, especially in","options":["Developing economies","The public sector","Developed economies only","Economies dominated by large firms"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Micro and small businesses are major creators of jobs, especially in developing economies. Option B is wrong because these businesses actually reduce pressure on the public sector to create jobs."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 473, $official_bank_source${"itemId":"4877e057-d4a3-56c5-8dea-064321d42fb0","questionId":"54792e2c-2489-5e60-a188-059586dcb2a8","sourceKey":"bank:ENT211:ENT211-W10-080","payload":{"prompt":"Providing self-employment and income autonomy is a contribution of micro and small businesses to","options":["Wealth creation","Financial independence","Poverty reduction","Employment generation"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Self-employment and income autonomy mean a person earns on their own terms, which is financial independence. Option D is tempting because it mentions employment, but employment generation is about creating jobs for others such as youth, women and vulnerable groups."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 474, $official_bank_source${"itemId":"0e64ba80-7bd8-5849-bc09-d2165bfeebab","questionId":"17728c95-7caa-5088-bf6e-6c64d1c021f0","sourceKey":"bank:ENT211:ENT211-W10-081","payload":{"prompt":"Reducing dependence on salaried employment and government support is part of the role of micro and small businesses in","options":["Employment generation","Poverty reduction","Wealth creation","Financial independence"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"When people run their own businesses they rely less on salaries and government help, which is financial independence. Option A is close, but under employment generation the related point is reducing pressure on the public sector and large firms to create jobs."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 475, $official_bank_source${"itemId":"76215248-3bb3-5fb2-ab24-09f7a47bf65a","questionId":"53646b58-3451-55d5-a5ce-485851f0baa0","sourceKey":"bank:ENT211:ENT211-W10-082","payload":{"prompt":"Fostering a culture of savings, investment and financial responsibility falls under","options":["Financial independence","Employment generation","Wealth creation","Poverty reduction"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"A culture of savings, investment and financial responsibility is listed under financial independence, together with managing personal and household finances independently. Option C is tempting because it involves investment, but wealth creation focuses on productive assets, capital accumulation and venture creation."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 476, $official_bank_source${"itemId":"359fb233-3b68-51bb-9a90-c04df7163032","questionId":"4bedf048-e540-5ab3-9c8e-8791c1711446","sourceKey":"bank:ENT211:ENT211-W10-083","payload":{"prompt":"After graduating from UNILAG, Funmi starts her own catering business so she no longer has to rely on a salaried job or government support, and she now manages her household finances herself. This best illustrates","options":["Wealth creation","Poverty reduction","Financial independence","Employment generation"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Funmi's story matches financial independence: self-employment, less dependence on salaried jobs and government support, and managing household finances independently. Option D would apply if the focus were on creating jobs for others, and option A focuses on productive assets and capital accumulation."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 477, $official_bank_source${"itemId":"0dd140ff-3be3-5c5b-b639-f6f2f1269bb7","questionId":"708c0375-6800-5c5b-8e51-4d9d2b3d5947","sourceKey":"bank:ENT211:ENT211-W10-084","payload":{"prompt":"Increasing household income and purchasing power is a contribution of micro and small businesses to","options":["Employment generation","Poverty reduction","Financial independence","Wealth creation"],"correctOption":1,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Raising household income and purchasing power is listed under poverty reduction. Option C is tempting, but financial independence is about self-employment, less dependence on salaries and a savings culture."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 478, $official_bank_source${"itemId":"e38815d6-65ed-5617-838a-40b0ccd77332","questionId":"4c06f510-e2d8-53c2-9564-2156b792cc9b","sourceKey":"bank:ENT211:ENT211-W10-085","payload":{"prompt":"Reducing income inequality through inclusive participation in economic activities is part of the role of micro and small businesses in","options":["Financial independence","Wealth creation","Employment generation","Poverty reduction"],"correctOption":3,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Reducing income inequality through inclusive participation is listed under poverty reduction. Option B is the tempting answer because wealth creation mentions inclusive growth, but its point is distributing wealth broadly, not reducing income inequality."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 479, $official_bank_source${"itemId":"e3cad862-659b-5c7c-8847-ee8b5d300ec0","questionId":"69962698-5c61-5d3a-b92c-a362920d5eb7","sourceKey":"bank:ENT211:ENT211-W10-086","payload":{"prompt":"Creating livelihood opportunities in rural and urban areas is a contribution to","options":["Poverty reduction","Market visibility","Wealth creation","Financial independence"],"correctOption":0,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Creating livelihood opportunities in rural and urban areas is a way micro and small businesses reduce poverty, alongside raising household income. Option B, market visibility, is about promoting a venture and building brand awareness, not about livelihoods. Option C is about income from owning productive assets and reinvestment, and D is about self-employment and income autonomy."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 480, $official_bank_source${"itemId":"b4eb128a-a1f3-55b3-a233-87a014a1d98f","questionId":"0af35973-fa7f-5954-96f7-92b9dbb7eaf6","sourceKey":"bank:ENT211:ENT211-W10-087","payload":{"prompt":"In a village in Ogun State, several small cassava-processing businesses help families earn more, support community projects and improve living standards. These effects best illustrate which role of micro and small businesses?","options":["Financial independence","Employment generation","Poverty reduction","Wealth creation"],"correctOption":2,"section":"Weeks 10-11: Micro and Small Enterprises","explanation":"Supporting community development, raising household income and improving living standards are all listed under poverty reduction. Option A focuses on individual self-employment and savings, and option B focuses on creating jobs rather than on community living standards."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 481, $official_bank_source${"itemId":"686fbe9d-be12-5e4f-bfe7-eeb66f48e8e1","questionId":"493d894d-4957-54aa-a836-df280153cc3b","sourceKey":"bank:ENT211:ENT211-W12-001","payload":{"prompt":"In entrepreneurship, the information, understanding and expertise that entrepreneurs acquire through education, training and experience, which enable them to identify opportunities, make informed decisions and manage business activities effectively, is called","options":["Online networking","Entrepreneurial skills","Digital entrepreneurship","Knowledge"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Knowledge is the information, understanding and expertise an entrepreneur picks up through education, training and experience. Option B is close, but skills are the practical abilities used to apply that knowledge, not the knowledge itself. Options C and A are about using digital technologies and digital relationships."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 482, $official_bank_source${"itemId":"da183b6a-bbe4-549e-826f-2668356e33e2","questionId":"f03d2f1d-5918-596e-b4df-071155278e38","sourceKey":"bank:ENT211:ENT211-W12-002","payload":{"prompt":"Knowledge in entrepreneurship is acquired through","options":["Capital, labour and time","Planning, organizing and controlling","Collection, storage and processing","Education, training and experience"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Entrepreneurs gain knowledge through education, training and experience. Option A lists resources that skills help to manage, option B describes managerial skills, and option C describes what digital technologies do with information."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 483, $official_bank_source${"itemId":"38e9c720-eb17-5e0e-8274-b4f023e3cc0e","questionId":"0d908a4f-7d31-5a79-a4db-9161a2d4ce10","sourceKey":"bank:ENT211:ENT211-W12-003","payload":{"prompt":"Knowledge in entrepreneurship enables entrepreneurs to","options":["Sell goods directly to individual consumers online","Register a business address, handle mail and answer calls remotely","Codify, document and easily share every business process","Identify opportunities, make informed decisions and manage business activities effectively"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Entrepreneurial knowledge helps an entrepreneur identify opportunities, make informed decisions and manage the business well. Option C describes explicit knowledge only, option B describes virtual office features, and option A describes B2C e-commerce."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 484, $official_bank_source${"itemId":"4c2731b9-a507-503b-a2d4-46dc38978e1c","questionId":"2692abd0-ecd9-5e45-8c0b-d295a327e2c4","sourceKey":"bank:ENT211:ENT211-W12-004","payload":{"prompt":"Knowledge embedded in experience, skills and intuition is known as","options":["Technical knowledge","Explicit knowledge","Market knowledge","Tacit knowledge"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Tacit knowledge lives inside a person's experience, skills and intuition, so it is hard to write down. Option B is the opposite: knowledge that can be codified, documented and easily shared. Options C and A are types of entrepreneurial knowledge defined by their subject, not by how the knowledge is held."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 485, $official_bank_source${"itemId":"0f7e7728-00c7-560a-ae4f-e2aee74d32b1","questionId":"1d40502f-c730-5450-aafc-0f7540571a74","sourceKey":"bank:ENT211:ENT211-W12-005","payload":{"prompt":"Knowledge that can be codified, documented and easily shared is called","options":["Tacit knowledge","Explicit knowledge","Financial knowledge","Legal knowledge"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Explicit knowledge can be written down, documented and passed to others easily, like a manual or a price list. Option A is knowledge embedded in experience and intuition, which is hard to share. Options D and C are types of entrepreneurial knowledge about laws and about budgeting."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 486, $official_bank_source${"itemId":"e1bd2d77-fbb8-5ea2-b7e7-089354cc35f8","questionId":"237ee15b-3f64-532a-8f6a-9041b16e6823","sourceKey":"bank:ENT211:ENT211-W12-006","payload":{"prompt":"Mama Bisi, a caterer in Ibadan, can tell exactly when her jollof rice is ready just by its smell, a judgement built over 20 years that she cannot easily put into words. This is an example of","options":["Legal knowledge","Tacit knowledge","Explicit knowledge","Market knowledge"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Her judgement comes from long experience and intuition, which is exactly what tacit knowledge is. Option C would apply if the know-how were written in a recipe that anyone could follow. Options D and A are about customers and competitors, and about laws."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 487, $official_bank_source${"itemId":"45606724-2afb-572e-960b-7f27c52de543","questionId":"88368a99-216b-5cc9-86d0-2e1f542ffaf7","sourceKey":"bank:ENT211:ENT211-W12-007","payload":{"prompt":"A bakery in Surulere writes all its recipes and production steps into a manual that every new staff member reads. The knowledge in the manual is","options":["Explicit knowledge","Tacit knowledge","Technical skills","Market knowledge"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Once know-how is written in a manual, it has been codified and documented so it can be shared easily, which makes it explicit knowledge. Option B is knowledge still locked in experience and intuition. Option C is an ability, not stored knowledge, and option D is about customers and competitors."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 488, $official_bank_source${"itemId":"c58872fe-8724-54b2-bedf-5d87dec37d28","questionId":"67ca562c-9577-5629-a1ba-11c9c862bed0","sourceKey":"bank:ENT211:ENT211-W12-008","payload":{"prompt":"The two major types of knowledge are","options":["Tacit and explicit knowledge","Managerial and strategic knowledge","Market and financial knowledge","Technical and legal knowledge"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Knowledge is broadly divided into tacit (held in experience) and explicit (codified and shareable). Options C and D are the four types of entrepreneurial knowledge, a separate classification by subject area. Option B borrows names of skill types."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 489, $official_bank_source${"itemId":"feac7a11-1a96-5ecc-8001-aa434d60abb3","questionId":"c56465d1-cea0-535f-a473-9dd98d5aec33","sourceKey":"bank:ENT211:ENT211-W12-009","payload":{"prompt":"The type of entrepreneurial knowledge concerned with understanding customer needs and competitors is","options":["Market knowledge","Legal knowledge","Technical knowledge","Financial knowledge"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Market knowledge is about knowing what customers need and what competitors are doing. Option D covers budgeting, costing and pricing, option C covers product or service development, and option B covers business laws and regulations."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 490, $official_bank_source${"itemId":"5329c9de-53b3-553d-ba10-82276bb09419","questionId":"06789f9e-1afe-581d-a6c4-f9ced2da1e63","sourceKey":"bank:ENT211:ENT211-W12-010","payload":{"prompt":"Financial knowledge, as a type of entrepreneurial knowledge, covers","options":["Understanding customer needs and competitors","Business laws and regulations","Product or service development","Budgeting, costing and pricing"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Financial knowledge deals with money matters: budgeting, costing and pricing. Option A is market knowledge, option C is technical knowledge and option B is legal knowledge."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 491, $official_bank_source${"itemId":"4504381e-2518-5d2f-a1c8-edc1ec06ef49","questionId":"64d003c0-cc9a-5820-ae6c-68d0ed7efc34","sourceKey":"bank:ENT211:ENT211-W12-011","payload":{"prompt":"Tunde, who runs a small electronics repair shop, studies the regulations that govern his trade so that his business stays within the law. He is building","options":["Technical knowledge","Explicit skills","Market knowledge","Legal knowledge"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Legal knowledge is knowledge of business laws and regulations, which is what Tunde is studying. Option C would be about customers and competitors and option A about developing the product or service itself. Option B is not a type of knowledge at all."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 492, $official_bank_source${"itemId":"755b5ecf-3855-5a73-8349-5560156b7166","questionId":"089515e3-2265-5338-bd8c-7968e7df0ba9","sourceKey":"bank:ENT211:ENT211-W12-012","payload":{"prompt":"A young entrepreneur in Enugu learns how to design and build a better solar-powered phone charger for her customers. Which type of entrepreneurial knowledge is she developing?","options":["Technical knowledge","Financial knowledge","Market knowledge","Legal knowledge"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Technical knowledge is about product or service development, which is what designing and building the charger involves. Option B is budgeting, costing and pricing, option D is business laws and regulations, and option C is understanding customer needs and competitors."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 493, $official_bank_source${"itemId":"eb4db6b5-f8dd-5ffd-a973-b17a8a673800","questionId":"22c247b0-2d6d-5912-a206-8adf6cc5319c","sourceKey":"bank:ENT211:ENT211-W12-013","payload":{"prompt":"Which of the following is NOT one of the types of entrepreneurial knowledge?","options":["Managerial knowledge","Legal knowledge","Market knowledge","Financial knowledge"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"The four types of entrepreneurial knowledge are market, financial, technical and legal knowledge. 'Managerial' appears as a type of skill (planning, organizing, controlling), not as a type of entrepreneurial knowledge, so A is the odd one out."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 494, $official_bank_source${"itemId":"71ca7992-2fe2-515f-a846-1bb8d4982438","questionId":"e656a34e-25a6-5098-a1f5-fcb4422b1583","sourceKey":"bank:ENT211:ENT211-W12-014","payload":{"prompt":"The practical abilities and competencies that enable entrepreneurs to apply knowledge effectively in planning, organizing, managing resources and solving problems in order to create and sustain business ventures are called","options":["Digital technologies","Entrepreneurial skills","Entrepreneurial knowledge","Tacit knowledge"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Entrepreneurial skills are the practical abilities that let an entrepreneur put knowledge to work. Option C is the information and understanding itself, not the ability to apply it, and option D is knowledge held in experience and intuition. Option A refers to computing tools and systems."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 495, $official_bank_source${"itemId":"cf2bd64a-5997-50e8-9ba5-e83e23c9d7d2","questionId":"69b7f09e-ec29-50f8-a51f-463d5cc5bc9f","sourceKey":"bank:ENT211:ENT211-W12-015","payload":{"prompt":"Entrepreneurial skills enable entrepreneurs to apply ______ effectively in planning, organizing, managing resources and solving problems.","options":["technology","intuition","capital","knowledge"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Skills are what turn knowledge into action, so entrepreneurs use skills to apply knowledge effectively. Options C and A are resources a business may use, and option B is part of tacit knowledge, but none of them is the word in the definition."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 496, $official_bank_source${"itemId":"88e860d2-d10c-53f8-aaf4-1435b30a831c","questionId":"c5045265-d1a8-55b9-b2b5-6592d1aca1af","sourceKey":"bank:ENT211:ENT211-W12-016","payload":{"prompt":"Entrepreneurial skills are also described as the capability to perform entrepreneurial tasks effectively, such as","options":["Opportunity recognition, relationship building and strategic decision-making","Budgeting, costing and pricing","Collection, storage, processing and exchange of information","Mail handling, call answering and document collaboration"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"The second definition of entrepreneurial skills gives opportunity recognition, relationship building and strategic decision-making as examples of entrepreneurial tasks. Option B describes financial knowledge, option D lists virtual office services, and option C describes what digital technologies do."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 497, $official_bank_source${"itemId":"841a34eb-61e0-5f20-95e5-dac88e50676c","questionId":"0956fbec-63e5-549a-a617-0be0ee385d57","sourceKey":"bank:ENT211:ENT211-W12-017","payload":{"prompt":"Managerial skills involve","options":["Planning, organizing and controlling","Budgeting, costing and pricing","Negotiating with customers and suppliers","Product or service development"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Managerial skills are about planning, organizing and controlling the business. Option B belongs to financial knowledge, option D is technical knowledge, and option C is closer to communication and negotiation skills."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 498, $official_bank_source${"itemId":"0ecb00a7-2ed7-5d9f-aff1-e2c0d670a1e7","questionId":"7156a1d3-8390-5df3-9f2d-771223fb1e07","sourceKey":"bank:ENT211:ENT211-W12-018","payload":{"prompt":"Which of the following is NOT listed among the types of entrepreneurial skills?","options":["Strategic skills","Marketing skills","Legal skills","Personal and creative skills"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Marketing, strategic, and personal and creative skills are all among the types of skills. 'Legal' appears as a type of entrepreneurial knowledge (business laws and regulations), not as a skill type, so C is the answer."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 499, $official_bank_source${"itemId":"0f02a6f8-298e-5c9e-80be-03a8ffc8396b","questionId":"812dc489-a234-56fc-904d-90f1117e0f9d","sourceKey":"bank:ENT211:ENT211-W12-019","payload":{"prompt":"Which of the following is one of the types of entrepreneurial skills?","options":["Cloud computing","Digital and technological skills","Explicit knowledge","Market knowledge"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Digital and technological skills are one of the listed types of entrepreneurial skills. Options C and D are types of knowledge, not skills, and option A is an example of a digital technology."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 500, $official_bank_source${"itemId":"27b6de1e-8855-5a1a-8886-b2fbfffd2bb7","questionId":"eb079b5a-ff04-516c-87d8-8d4ccb72c39b","sourceKey":"bank:ENT211:ENT211-W12-020","payload":{"prompt":"Chiamaka persuades a supplier in Onitsha to give her a lower price and a longer payment period for her fabric orders. Which type of skill is she mainly using?","options":["Technical skills","Digital and technological skills","Managerial skills","Communication and negotiation"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Getting a supplier to agree to better terms is a matter of communication and negotiation. Option A would be about making the product, option C covers planning, organizing and controlling, and option B is about using digital tools."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 501, $official_bank_source${"itemId":"551a3c0d-4eee-55c3-9aff-befeb7bca148","questionId":"c7235be6-c867-529d-8378-ae947834f42d","sourceKey":"bank:ENT211:ENT211-W12-021","payload":{"prompt":"Before opening his barbing salon, Emeka prepares a detailed budget and tracks every naira he spends against it. This mainly shows","options":["Financial and budgeting skills","Communication and negotiation","Marketing skills","Personal and creative skills"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Preparing a budget and controlling spending are financial and budgeting skills. Option C is about promoting and selling, option D relates to personal qualities and creativity, and option B is about persuading and dealing with people."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 502, $official_bank_source${"itemId":"bca022e8-2f55-57b3-82f5-5c267f82c06c","questionId":"c18625c8-b809-5811-b782-ab0ff833f231","sourceKey":"bank:ENT211:ENT211-W12-022","payload":{"prompt":"Which statement best distinguishes knowledge from skills in entrepreneurship?","options":["Knowledge is about money; skills are about people","Knowledge is always written down; skills are always unwritten","Knowledge comes only from school; skills come only from experience","Knowledge is information and understanding; skills are the practical abilities to apply that knowledge"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Knowledge is the information, understanding and expertise an entrepreneur has, while skills are the practical abilities and competencies used to apply that knowledge. Option B confuses this with explicit versus tacit knowledge, and options A and C are too narrow, since knowledge comes from education, training and experience."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 503, $official_bank_source${"itemId":"a2cd61ff-2d49-537e-b9f7-3e1a2536fb0f","questionId":"77ee50c2-a51e-5efd-a9b6-52c63d945293","sourceKey":"bank:ENT211:ENT211-W12-023","payload":{"prompt":"Knowledge helps entrepreneurs understand market trends and customer needs, while skills enable them to analyse information and recognise viable business opportunities. This role of knowledge and skills is","options":["Innovation and creativity","Opportunity recognition","Risk-management and decision making","Business growth and competitiveness"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Understanding market trends and analysing information to spot viable business opportunities is the role called opportunity recognition. Option A is about idea generation and turning ideas into products, option D is about competitive strategy and scaling, and option C is about assessing risks and making decisions."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 504, $official_bank_source${"itemId":"e1279d0c-7f83-58e9-8fe6-71ebc513a2df","questionId":"e976e195-ad00-5404-b287-811fab86cdda","sourceKey":"bank:ENT211:ENT211-W12-024","payload":{"prompt":"Knowledge supports research, idea generation and technological adoption, while skills allow entrepreneurs to transform ideas into innovative products and services. Which role of knowledge and skills is this?","options":["Adoption of digital technology","Innovation and creativity","Continuous learning and adaptability","Opportunity recognition"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Generating ideas and turning them into innovative products and services is the innovation and creativity role. Option D is about spotting opportunities from market trends, option A is about understanding and using digital tools, and option C is about lifelong learning and adapting to change."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 505, $official_bank_source${"itemId":"b2eb1184-a6db-51b3-8fe7-6513611cc71d","questionId":"2f2248ff-f27e-5623-8237-9228a6ff7f43","sourceKey":"bank:ENT211:ENT211-W12-025","payload":{"prompt":"Under the role 'Efficient Resource Management', financial and operational knowledge guide optimal resource allocation, while skills help entrepreneurs manage","options":["Laws and ethics","Customer reviews and ratings","Capital, labour and time effectively","Online advertisements and SEO"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Efficient resource management means skills help entrepreneurs manage capital, labour and time well. Option A links to ethical and sustainable entrepreneurship, while options B and D belong to e-commerce strategies on trust and digital marketing."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 506, $official_bank_source${"itemId":"f029dff3-adcf-5717-b2b6-ff7747879fba","questionId":"e204d2d9-c85e-5920-a0c3-ddb140f240eb","sourceKey":"bank:ENT211:ENT211-W12-026","payload":{"prompt":"Ngozi, who runs a laundry business in Yaba, carefully decides how to share her limited capital, staff hours and machine time so nothing is wasted. Which role of knowledge and skills does this show?","options":["Adoption of digital technology","Ethical and sustainable entrepreneurship","Opportunity recognition","Efficient resource management"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Allocating capital, labour and time wisely is efficient resource management. Option C is about spotting new business openings, option B is about responsible conduct guided by laws and ethics, and option A is about using digital tools."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 507, $official_bank_source${"itemId":"4ef385cb-4a41-5dff-9b9a-8d714031d81d","questionId":"88b5d235-000f-5259-8530-3c22bad72b8f","sourceKey":"bank:ENT211:ENT211-W12-027","payload":{"prompt":"Knowledge enables understanding of digital tools and platforms, while digital skills support e-commerce, online marketing and virtual operations. This describes which role of knowledge and skills?","options":["Adoption of digital technology","Innovation and creativity","Business growth and competitiveness","Efficient resource management"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Understanding digital tools and using digital skills for e-commerce, online marketing and virtual operations is the adoption of digital technology role. Option B focuses on ideas and new products, option C on competitive strategy and market expansion, and option D on managing capital, labour and time."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 508, $official_bank_source${"itemId":"992f217f-bf9c-50b7-9310-b4d2d4b637b9","questionId":"d81c4087-b113-55d8-b620-3687abd87fc0","sourceKey":"bank:ENT211:ENT211-W12-028","payload":{"prompt":"In the role 'Adoption of Digital Technology', digital skills support","options":["Scaling, customer retention and market expansion","Assessment of business risks and uncertainties","Responsible business conduct","E-commerce, online marketing and virtual operations"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Digital skills are what make e-commerce, online marketing and virtual operations possible. Option B belongs to risk-management and decision making, option C to ethical and sustainable entrepreneurship, and option A to business growth and competitiveness."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 509, $official_bank_source${"itemId":"29e822b5-7430-5aea-8d3b-3dfd8687df0d","questionId":"75e8e1d5-a827-57bf-ae57-40c97ebfa038","sourceKey":"bank:ENT211:ENT211-W12-029","payload":{"prompt":"Knowledge improves the assessment of business risks and uncertainties, while skills enhance problem-solving and informed decision-making. This role is","options":["Opportunity recognition","Efficient resource management","Continuous learning and adaptability","Risk-management and decision making"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Assessing risks and uncertainties and making informed decisions is the risk-management and decision making role. Option A is about recognising viable opportunities, option C is about adapting to change, and option B is about allocating capital, labour and time."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 510, $official_bank_source${"itemId":"cec46860-de51-5f48-a642-a14be64daf46","questionId":"a40efdd5-029d-56d0-9d89-aa8a938c99d5","sourceKey":"bank:ENT211:ENT211-W12-030","payload":{"prompt":"Knowledge helps entrepreneurs understand competitive strategies and market positioning, while skills enable scaling, customer retention and market expansion. Which role is this?","options":["Opportunity recognition","Adoption of digital technology","Business growth and competitiveness","Innovation and creativity"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Competitive strategy, market positioning, scaling and market expansion all point to business growth and competitiveness. Option A is about understanding trends to find opportunities, option D is about turning ideas into products, and option B is about using digital tools."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 511, $official_bank_source${"itemId":"10bc1d9c-113c-54ba-b25b-8ceab9842a69","questionId":"6489bea8-2cc8-58ef-862a-06a4149f2030","sourceKey":"bank:ENT211:ENT211-W12-031","payload":{"prompt":"A plastics recycling startup in Lagos refuses to dump waste illegally because its founders know the environmental laws and want to act responsibly. Which role of knowledge and skills does this illustrate?","options":["Risk-management and decision making","Ethical and sustainable entrepreneurship","Business growth and competitiveness","Efficient resource management"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Knowledge of laws and ethics that leads to responsible, sustainable business conduct is ethical and sustainable entrepreneurship. Option A is about assessing risks, option D is about managing capital, labour and time, and option C is about competing and expanding."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 512, $official_bank_source${"itemId":"77a45af3-9521-5d09-9dc0-6f5ba5169209","questionId":"3318eaf5-4ce4-5bf6-bfa5-1c73305011d5","sourceKey":"bank:ENT211:ENT211-W12-032","payload":{"prompt":"Under 'Ethical and Sustainable Entrepreneurship', knowledge of laws and ethics","options":["Guides optimal resource allocation","Promotes responsible business conduct","Improves assessment of business risks","Supports research and idea generation"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Knowing the laws and ethics of business encourages responsible business conduct. Option A belongs to efficient resource management, option D to innovation and creativity, and option C to risk-management and decision making."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 513, $official_bank_source${"itemId":"ae88c0af-0b4b-5792-882b-9ddb799aa59c","questionId":"73ac5143-f0cf-543f-b571-bc78cc1a568f","sourceKey":"bank:ENT211:ENT211-W12-033","payload":{"prompt":"Since 2015, Kunle has kept taking short courses and changing how his printing business works each time customers move to new technologies. This best reflects which role of knowledge and skills?","options":["Continuous learning and adaptability","Efficient resource management","Innovation and creativity","Opportunity recognition"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Ongoing learning and adjusting to a changing business environment and new technologies is continuous learning and adaptability. Option D is about spotting a viable opportunity, option C is about creating new products from ideas, and option B is about allocating resources."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 514, $official_bank_source${"itemId":"9999e103-447a-5c2a-b3b3-787de60a07f6","questionId":"7b2e9323-7c8b-592a-9637-3a77d526f1ed","sourceKey":"bank:ENT211:ENT211-W12-034","payload":{"prompt":"Which of the following is NOT one of the roles of knowledge and skills in entrepreneurship?","options":["Opportunity recognition","Ethical and sustainable entrepreneurship","Continuous learning and adaptability","Improved market access"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Opportunity recognition, ethical and sustainable entrepreneurship, and continuous learning and adaptability are all roles of knowledge and skills. Improved market access is one of the impacts of digital technology on entrepreneurial growth, so D does not belong."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 515, $official_bank_source${"itemId":"ef3971d0-52c8-5fa9-875c-3efb3ca72096","questionId":"b9ed7d13-fe3e-5e8a-8c7c-7ae7933a7976","sourceKey":"bank:ENT211:ENT211-W12-035","payload":{"prompt":"Which of the following is a role of knowledge and skills in entrepreneurship?","options":["Resource mobilization","Build trust and credibility","Risk-management and decision making","Cost efficiency"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Risk-management and decision making is one of the roles of knowledge and skills. Option D is an importance of a virtual office, option A is an importance of online networking, and option B is an e-commerce strategy."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 516, $official_bank_source${"itemId":"1629ff7b-e7a4-5254-ad53-740c90c449bb","questionId":"575494e1-b362-5917-a08d-d6a4e79acfbd","sourceKey":"bank:ENT211:ENT211-W12-036","payload":{"prompt":"All of the following are roles of knowledge and skills in entrepreneurship EXCEPT","options":["Business growth and competitiveness","Market visibility and brand building","Innovation and creativity","Efficient resource management"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Innovation and creativity, efficient resource management, and business growth and competitiveness are all roles of knowledge and skills. Market visibility and brand building is an importance of online networking, so B is the exception."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 517, $official_bank_source${"itemId":"feee29d4-cc27-53fd-ba2c-8a16723a82b3","questionId":"c4bbd9c7-e368-52e7-9d24-45216e7b05c7","sourceKey":"bank:ENT211:ENT211-W12-037","payload":{"prompt":"The creation, development and growth of business ventures through the use of digital technologies is called","options":["Online networking","Digital entrepreneurship","Virtual office","Electronic commerce"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Digital entrepreneurship is building and growing ventures by using digital technologies. Option D is narrower, covering buying and selling over electronic networks, option A is building relationships online, and option C is a way of operating remotely without physical office space."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 518, $official_bank_source${"itemId":"15e2bae1-fcc2-5264-accf-e2348feee67e","questionId":"0a23ec29-1aba-5a4f-b32c-28e801a2b308","sourceKey":"bank:ENT211:ENT211-W12-038","payload":{"prompt":"Digital entrepreneurship is defined as the creation of new ventures and the transformation of existing businesses through the development of","options":["Novel digital technologies and innovative business models","Tacit knowledge and intuition","Government procurement portals","Physical offices and large workforces"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"This definition says digital entrepreneurship creates new ventures and transforms existing ones through novel digital technologies and innovative business models. Option D is what digital technology reduces the need for, option C is an example of B2G e-commerce, and option B is a type of knowledge."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 519, $official_bank_source${"itemId":"398a2a54-446e-54d8-ae71-09a6e4d9c7e1","questionId":"c5bf883a-a438-5764-854c-9377feba1858","sourceKey":"bank:ENT211:ENT211-W12-039","payload":{"prompt":"Digital entrepreneurial activities rely on which of the following for value creation and delivery?","options":["Market, financial and legal knowledge","Digital artifacts, digital platforms and digital infrastructures","Registered addresses, mail handling and receptionists","Budgeting, costing and pricing"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Digital entrepreneurial activities create and deliver value through digital artifacts, digital platforms and digital infrastructures. Option C lists virtual office features, option A lists types of entrepreneurial knowledge, and option D describes financial knowledge."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 520, $official_bank_source${"itemId":"3e3abda1-e43d-589f-9b52-e441c19a5e37","questionId":"c17779f0-1425-56cd-813e-dba13073ed33","sourceKey":"bank:ENT211:ENT211-W12-040","payload":{"prompt":"Jumia, Konga, Amazon and Slot are examples of which kind of digital business?","options":["E-commerce businesses (online retail stores)","Digital service businesses","Digital finance businesses","Digital media services"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"These companies sell goods to customers online, so they are e-commerce businesses or online retail stores. Option B covers platforms like Coursera and Zoom, option D covers streaming and podcasting, and option C covers payments and banking like Paystack and Opay."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 521, $official_bank_source${"itemId":"accb762c-3884-554a-aa46-7ecd16f2a6b8","questionId":"e1d7f6a6-af7e-5cbf-a15a-39eb4179e65c","sourceKey":"bank:ENT211:ENT211-W12-041","payload":{"prompt":"Coursera and Udemy are examples of","options":["Online education platforms","Streaming services","Podcasting platforms","Online retail stores"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Coursera and Udemy offer courses online, so they are online education platforms, a kind of digital service business. Option B is Netflix and Disney, option C is Spotify and Apple Podcasts, and option D is Jumia and Konga."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 522, $official_bank_source${"itemId":"4ae33226-719b-5f16-82a2-08b6aa9815b7","questionId":"80d3a3e1-c961-5bde-a38a-aa2163fe32b1","sourceKey":"bank:ENT211:ENT211-W12-042","payload":{"prompt":"Zoom, Dropbox, Google and Slack are given as examples of","options":["Crypto currency exchanges","Online education platforms","Software as a service","Streaming services"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Zoom, Dropbox, Google and Slack deliver software to users over the internet, so they are software as a service, under digital service businesses. Option B is Coursera and Udemy, option D is Netflix and Disney, and option A is a digital finance business."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 523, $official_bank_source${"itemId":"255f09e0-203a-5dbb-b4d7-035d409ab449","questionId":"b6a94c6b-a0ff-57e9-9d48-6c8a62a38a6f","sourceKey":"bank:ENT211:ENT211-W12-043","payload":{"prompt":"Netflix and Disney are examples of which category of digital business?","options":["E-commerce businesses","Digital service businesses (software as a service)","Digital health businesses","Digital media services (streaming services)"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Netflix and Disney stream content to subscribers, so they are streaming services under digital media services. Option A is online retail like Jumia, option B is software such as Zoom and Dropbox, and option C covers telemedicine and online pharmacies."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 524, $official_bank_source${"itemId":"9e64ecfe-8a8b-56cb-9930-247af9e75db6","questionId":"656d7218-4359-529b-be1c-0b05f2b876c8","sourceKey":"bank:ENT211:ENT211-W12-044","payload":{"prompt":"Which of the following is listed as an example of a podcasting platform?","options":["Udemy","Dropbox","Spotify","Netflix"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Spotify, Apple Podcasts and YouTube channels are the podcasting platform examples. Option D is a streaming service, option A is an online education platform, and option B is software as a service."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 525, $official_bank_source${"itemId":"a2de862a-6277-535b-9f00-fafe4bd79fb5","questionId":"368d8db1-f019-5789-83bb-d3a316f872cf","sourceKey":"bank:ENT211:ENT211-W12-045","payload":{"prompt":"Digital media services such as streaming services and podcasting platforms are described as","options":["Dropshipping-based","Sharing-economy","Government-to-consumer","Subscription-based"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Digital media services are labelled subscription-based, because users usually pay regularly to access streaming or podcast content. Option C is a type of e-commerce, option B is a business model digital technology enables, and option A is an e-commerce opportunity."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 526, $official_bank_source${"itemId":"2bda8e86-08b4-5486-af35-a586de488b95","questionId":"fd1a5ed4-55a3-5e40-bbe4-11bfae6e3c7d","sourceKey":"bank:ENT211:ENT211-W12-046","payload":{"prompt":"Telemedicine platforms, wellness apps and online pharmacy services are examples of","options":["Digital health businesses","Digital media services","Digital service businesses","Digital finance businesses"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Telemedicine, wellness apps and online pharmacies use digital technology to provide health services, so they are digital health businesses. Option C covers education platforms and software as a service, option B covers streaming and podcasting, and option D covers online banking and payments."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 527, $official_bank_source${"itemId":"ee331d63-544c-5f93-8c26-0c03d37905df","questionId":"8f4787e2-1f3f-5ee2-a7d9-a9bb10fafd93","sourceKey":"bank:ENT211:ENT211-W12-047","payload":{"prompt":"PayPal, Flutterwave, Paystack and Opay are examples of which category of digital business?","options":["Digital finance businesses","E-commerce businesses","Digital media services","Digital health businesses"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"These companies handle online payments and banking, so they are digital finance businesses. Option B is online retail like Jumia and Konga, option C is streaming and podcasting, and option D is telemedicine and online pharmacies."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 528, $official_bank_source${"itemId":"3a0dbd69-a94f-5361-af8b-826207ff5205","questionId":"10e4e230-3d89-54c4-8a8a-6c803ad84070","sourceKey":"bank:ENT211:ENT211-W12-048","payload":{"prompt":"Crypto currency exchanges fall under which category of digital business?","options":["Digital service businesses","Digital finance businesses","Digital media services","E-commerce businesses"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Crypto currency exchanges sit alongside online banking and payments as digital finance businesses. Option A covers online education and software as a service, option C covers subscription media, and option D covers online retail stores."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 529, $official_bank_source${"itemId":"69002e37-324c-5df6-8a50-90b93c9d69b0","questionId":"bc62391f-383e-5867-b4c8-2caf10638871","sourceKey":"bank:ENT211:ENT211-W12-049","payload":{"prompt":"Which of the following is NOT given as an example of an e-commerce business (online retail store)?","options":["Slot","Netflix","Jumia","Konga"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Jumia, Konga and Slot are listed as online retail stores, along with Amazon. Netflix is a streaming service under digital media services, so B is the odd one out."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 530, $official_bank_source${"itemId":"ff063f4c-8ba5-51e2-8b5f-011af8d91cbc","questionId":"a0cbbbd8-2a6d-557f-a0a6-9d760433dddc","sourceKey":"bank:ENT211:ENT211-W12-050","payload":{"prompt":"A startup in Abuja lets patients consult licensed doctors through video calls on a mobile app. This is an example of a","options":["Digital media service","Digital finance business","Digital health business","Software as a service"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Remote doctor consultations are telemedicine, which is a digital health business. Option A is streaming or podcasting, option B is payments and banking, and option D is software tools like Zoom or Dropbox."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 531, $official_bank_source${"itemId":"f163619e-c3e3-5973-b666-55021b261334","questionId":"8980377e-f4a1-5d57-a972-4c6b282f1594","sourceKey":"bank:ENT211:ENT211-W12-051","payload":{"prompt":"Tools and systems based on digital computing that enable the collection, storage, processing and exchange of information are called","options":["Online networking","Digital technologies","Digital entrepreneurship","Electronic commerce"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Digital technologies are computing-based tools and systems for collecting, storing, processing and exchanging information. Option C is the creation of ventures using these technologies, option A is relationship-building online, and option D is buying and selling over electronic networks."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 532, $official_bank_source${"itemId":"44d3e517-c0a7-5841-a561-d75cfee8e2bd","questionId":"66ce4496-4c5c-5d89-90e6-5dd0169f5b85","sourceKey":"bank:ENT211:ENT211-W12-052","payload":{"prompt":"Digital technologies are also described as platforms and infrastructures that enable","options":["New forms of entrepreneurial activity, innovation and value creation","Registered business addresses and mail forwarding","Codified, documented and easily shared knowledge","The sale of goods directly to other businesses"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Digital technologies are platforms and infrastructures that open up new forms of entrepreneurial activity, innovation and value creation. Option B describes virtual office features, option C describes explicit knowledge, and option D describes B2B e-commerce."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 533, $official_bank_source${"itemId":"e6941437-7723-5632-bcfc-e055ce57f189","questionId":"a16869ad-110b-5367-8dc0-70207b6c4fe5","sourceKey":"bank:ENT211:ENT211-W12-053","payload":{"prompt":"Which of the following is listed as an example of digital technology?","options":["Tacit knowledge","Affiliate marketing","Mail handling and forwarding","Artificial Intelligence (AI) and data analytics"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"AI and data analytics is one of the examples of digital technologies. Option C is a virtual office feature, option B is an entrepreneurial opportunity in e-commerce, and option A is a type of knowledge."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 534, $official_bank_source${"itemId":"670e0652-2449-5217-bfe7-7c564aa4dfb4","questionId":"245c2535-2d4f-595e-af31-7f08780c557a","sourceKey":"bank:ENT211:ENT211-W12-054","payload":{"prompt":"Which of the following is NOT an example of digital technology?","options":["Internet and cloud computing","Financial technologies (FinTech)","Crowdfunding","Software applications and mobile apps"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Internet and cloud computing, FinTech, and software applications and mobile apps are all examples of digital technologies. Crowdfunding is a way of raising money that digital finance tools make easier, mentioned under the impact on access to capital, but it is not itself a digital technology."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 535, $official_bank_source${"itemId":"5c75a895-eaec-5feb-826c-49aaecf8ede2","questionId":"4db316c7-d0e5-5174-bec1-0cc69019848d","sourceKey":"bank:ENT211:ENT211-W12-055","payload":{"prompt":"Computers, smartphones and tablets are examples of","options":["Entrepreneurial opportunities in e-commerce","Digital technologies","Types of e-commerce","Virtual office tools"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Computers, smartphones and tablets are listed among the examples of digital technologies. Option D refers to tools like Google Workspace, Zoom, Slack and Regus, option C refers to B2C, B2B and the like, and option A refers to items such as dropshipping and affiliate marketing."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 536, $official_bank_source${"itemId":"4f7380b6-4977-5f09-a80b-0f5f90ad6e35","questionId":"bb4548a9-ab44-594b-9ef0-61f2bd4cf992","sourceKey":"bank:ENT211:ENT211-W12-056","payload":{"prompt":"Shopify, Jumia and Temu, which enable online selling and digital storefronts, are grouped as","options":["Productivity and project management tools","Communication and collaboration tools","Digital marketing tools","E-commerce platforms"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Shopify, Jumia and Temu let businesses sell online and run digital storefronts, so they are e-commerce platforms. Option C includes Instagram, Google Ads and Mailchimp, option A includes Trello, Asana and Notion, and option B includes Zoom and Microsoft Teams."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 537, $official_bank_source${"itemId":"bb7f0e0e-3f0a-5ba4-b284-57ac85c01278","questionId":"e12bef74-c8ff-5e8e-86a0-3f6b14bd3910","sourceKey":"bank:ENT211:ENT211-W12-057","payload":{"prompt":"Mailchimp is given as an example of","options":["An email marketing platform","A customer relationship management system","An accounting software","A project management tool"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Mailchimp is the email marketing platform listed under digital marketing tools. Option C refers to QuickBook and Wave, option B to HubSpot, and option D to Trello, Asana and Notion."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 538, $official_bank_source${"itemId":"0b4d6147-da53-5078-901c-745e6305ecfc","questionId":"7375ae96-373c-551d-a657-78b3a89e4a54","sourceKey":"bank:ENT211:ENT211-W12-058","payload":{"prompt":"Google Ads and Search Engine Optimization (SEO) tools belong to which group of digital tools for entrepreneurial growth?","options":["Financial and accounting tools","Productivity and project management tools","Digital marketing tools","Data analytics and customer management tools"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Google Ads and SEO tools help a business get seen and advertise online, so they are digital marketing tools, along with social media and email marketing. Option A covers payments and accounting, option D covers Google Analytics and CRM, and option B covers Trello, Asana and Notion."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 539, $official_bank_source${"itemId":"e8852ad2-aaf3-5f69-94d3-bac4521a7bd9","questionId":"f852956b-1620-5383-bc50-81cce00063c7","sourceKey":"bank:ENT211:ENT211-W12-059","payload":{"prompt":"QuickBook and Wave are examples of","options":["Email marketing platforms","Virtual meeting tools","Accounting software","Mobile payment systems"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"QuickBook and Wave are accounting software under financial and accounting tools. Option D refers to Paystack, Flutterwave and PayPal, option A to Mailchimp, and option B to Zoom and Microsoft Teams."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 540, $official_bank_source${"itemId":"2e7717a1-9a60-5833-895f-097213aaf5d5","questionId":"562e8049-9028-5b3a-9e1f-aa4af91618e0","sourceKey":"bank:ENT211:ENT211-W12-060","payload":{"prompt":"Among digital tools for entrepreneurial growth, mobile payment systems such as Paystack, Flutterwave and PayPal are classified under","options":["Financial and accounting tools","Data analytics and customer management tools","Communication and collaboration tools","Digital marketing tools"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Mobile payment systems sit with accounting software under financial and accounting tools. Option C covers Zoom, Teams, Slack and WhatsApp Business, option B covers Google Analytics and HubSpot, and option D covers social media, Google Ads and Mailchimp."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 541, $official_bank_source${"itemId":"31c47eb5-3da3-5694-a9a1-3d792fdbcfd1","questionId":"52deaddb-41e0-5b64-b2fe-67a8149ea8c3","sourceKey":"bank:ENT211:ENT211-W12-061","payload":{"prompt":"Zoom, Microsoft Teams and Google Meet are grouped as","options":["E-commerce platforms","Financial and accounting tools","Communication and collaboration tools","Productivity and project management tools"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Zoom, Microsoft Teams and Google Meet let people meet and work together online, so they are communication and collaboration tools. Option A is Shopify, Jumia and Temu, option B is payment systems and accounting software, and option D is Trello, Asana and Notion."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 542, $official_bank_source${"itemId":"6c3bd115-b09c-514b-b26e-19123c039bdd","questionId":"1cb714c9-9e50-5ac3-86e8-56d7ca8a1255","sourceKey":"bank:ENT211:ENT211-W12-062","payload":{"prompt":"As communication and collaboration tools, Slack and WhatsApp Business support","options":["Online selling and digital storefronts","Data-driven decision-making","Virtual offices and teamwork","Budgeting and accounting"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Slack and WhatsApp Business are said to support virtual offices and teamwork. Option A is what e-commerce platforms do, option B is what CRM systems support, and option D is the job of financial and accounting tools."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 543, $official_bank_source${"itemId":"7ab31706-1217-5308-97d0-7b3fe47d3c12","questionId":"eff6e222-0846-5070-a62c-4416bfaed73a","sourceKey":"bank:ENT211:ENT211-W12-063","payload":{"prompt":"Google Analytics and HubSpot are examples of","options":["Communication and collaboration tools","Data analytics and customer management tools","E-commerce platforms","Financial and accounting tools"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Google Analytics tracks data and HubSpot is a CRM system, so both are data analytics and customer management tools. Option A is Zoom, Teams and Slack, option C is Shopify, Jumia and Temu, and option D is payment systems and accounting software."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 544, $official_bank_source${"itemId":"ae25102a-a32c-5bb6-b1d5-a58b446de2b7","questionId":"68d415a9-be5e-5318-a838-b2e118348ac0","sourceKey":"bank:ENT211:ENT211-W12-064","payload":{"prompt":"Customer Relationship Management (CRM) systems such as HubSpot support","options":["Data-driven decision-making","Online selling and digital storefronts","Mail handling and forwarding","Virtual offices and teamwork"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"CRM systems like HubSpot help entrepreneurs make decisions based on customer data. Option D is what Slack and WhatsApp Business support, option B is what e-commerce platforms enable, and option C is a virtual office feature."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 545, $official_bank_source${"itemId":"3afe6d95-52b8-5c31-a192-9ab1f15f1074","questionId":"cbba2611-590a-581e-8d30-38a56c7ea44b","sourceKey":"bank:ENT211:ENT211-W12-065","payload":{"prompt":"Trello, Asana and Notion, which help manage tasks, time and resources effectively, are","options":["Productivity and project management tools","Digital marketing tools","Virtual office address services","Data analytics and customer management tools"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Trello, Asana and Notion help teams organise tasks, time and resources, so they are productivity and project management tools. Option B is social media, Google Ads and Mailchimp, option D is Google Analytics and HubSpot, and option C is Regus and WeWork."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 546, $official_bank_source${"itemId":"6c4fc6f6-5cba-567b-a69b-747cac190f36","questionId":"0174674c-6397-5f85-abaa-6fca66e38201","sourceKey":"bank:ENT211:ENT211-W12-066","payload":{"prompt":"Folake runs a small events company in Lekki and wants one tool to assign tasks to her team and track deadlines. Which of these tools fits best?","options":["Google Analytics","QuickBook","Trello","Mailchimp"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Trello is a productivity and project management tool for managing tasks, time and resources. Option D is for email marketing, option B is accounting software, and option A is a data analytics tool."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 547, $official_bank_source${"itemId":"13c3b7ac-7a87-5cc8-9500-9303f386bf11","questionId":"c84bd4bb-978b-54a7-a1cb-161b01dcd202","sourceKey":"bank:ENT211:ENT211-W12-067","payload":{"prompt":"Which of the following is listed as a social media platform among digital marketing tools?","options":["Asana","Instagram","Regus","Wave"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Instagram, Facebook and LinkedIn are the social media platforms under digital marketing tools. Option A is a project management tool, option D is accounting software, and option C provides virtual office addresses and admin services."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 548, $official_bank_source${"itemId":"fc05161b-c6c3-56a1-8a0a-fc43a23f786c","questionId":"08056dc4-6c81-5206-9aef-47dffacc993d","sourceKey":"bank:ENT211:ENT211-W12-068","payload":{"prompt":"Which impact of digital technology enables entrepreneurs to reach local, national and global markets and reduces geographical barriers through online platforms?","options":["Improved market access","Cost reduction and efficiency","Enhance customer engagement","Scalability and business growth"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Reaching wider markets and breaking geographical barriers is improved market access. Option B is about lowering costs, option C is about real-time communication with customers, and option D is about scaling without costs rising as fast."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 549, $official_bank_source${"itemId":"83ca325a-67a6-5eed-9698-b24094e7fe25","questionId":"bf352be2-20fd-5920-9fb0-18858a5eed41","sourceKey":"bank:ENT211:ENT211-W12-069","payload":{"prompt":"Lowering operational and transaction costs, reducing the need for physical offices and large workforces, and improving productivity through automation describe which impact of digital technology?","options":["Financial inclusion and access to capital","Cost reduction and efficiency","Innovation and new business models","Improved market access"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Lower costs, fewer physical offices and automation-driven productivity make up cost reduction and efficiency. Option D is about reaching more markets, option C is about new digital products and platform models, and option A is about payments, loans and investors."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 550, $official_bank_source${"itemId":"4deaceec-ac8d-5354-a35a-5a350faef1b0","questionId":"43d6998e-6d17-55e1-a573-0de57f023fa1","sourceKey":"bank:ENT211:ENT211-W12-070","payload":{"prompt":"Enabling platform-based and sharing economy models and supporting the development of digital products and services fall under which impact of digital technology?","options":["Enhance customer engagement","Cost reduction and efficiency","Innovation and new business models","Improved market access"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Platform-based and sharing economy models and new digital products are part of innovation and new business models. Option B is about cutting costs, option A is about communicating with and serving customers, and option D is about reaching wider markets."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 551, $official_bank_source${"itemId":"4b483c19-7294-5074-b789-db417944382d","questionId":"cdb66b66-a6ea-5f9f-afa3-925f1e9ec429","sourceKey":"bank:ENT211:ENT211-W12-071","payload":{"prompt":"Real-time communication with customers, improved customer feedback and relationship management, and personalized marketing strategies describe which impact of digital technology?","options":["Enhance customer engagement","Innovation and new business models","Scalability and business growth","Improved market access"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Real-time communication, feedback and personalized marketing are all about engaging customers better. Option D is about reaching new markets, option B is about new products and business models, and option C is about rapid scaling and global collaboration."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 552, $official_bank_source${"itemId":"0978f932-70c2-54a0-88be-f7c2a795784c","questionId":"cb61e2c7-c4f8-58d2-9ab8-ea352634d299","sourceKey":"bank:ENT211:ENT211-W12-072","payload":{"prompt":"Digital finance tools enabling online payments, improving access to loans, crowdfunding and investors, and supporting cash flow management describe which impact of digital technology?","options":["Scalability and business growth","Enhance customer engagement","Cost reduction and efficiency","Financial inclusion and access to capital"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Online payments, loans, crowdfunding, investors and cash flow management point to financial inclusion and access to capital. Option C is about lower costs and automation, option A is about scaling without costs rising as fast, and option B is about communicating with customers."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 553, $official_bank_source${"itemId":"6895c8c0-f21f-52bf-803f-6155f88f4502","questionId":"1bea0990-b5e9-5ef3-882f-7cdff12b6d4f","sourceKey":"bank:ENT211:ENT211-W12-073","payload":{"prompt":"As an impact of digital technology, 'Scalability and Business Growth' means that digital technology","options":["Reduces geographical barriers through online platforms","Reduces the need for physical offices and large workforce","Enables rapid scaling without a proportionate increase in costs","Enables platform-based and sharing economy models"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Scalability means a business can grow quickly without its costs rising in the same proportion, while also supporting remote work and global collaboration. Option B belongs to cost reduction and efficiency, option D to innovation and new business models, and option A to improved market access."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 554, $official_bank_source${"itemId":"e770b943-7ee9-5f26-9d69-e4cceacb13dc","questionId":"84c748f2-1628-5351-84b6-69154a83b2bb","sourceKey":"bank:ENT211:ENT211-W12-074","payload":{"prompt":"A leather shoemaker in Aba starts selling to buyers in Ghana and the UK through an online platform, without opening any shops abroad. Which impact of digital technology does this show?","options":["Enhance customer engagement","Improved market access","Innovation and new business models","Financial inclusion and access to capital"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Reaching national and global customers through online platforms, despite distance, is improved market access. Option D is about payments and funding, option C is about new digital products and platform models, and option A is about communicating with and serving customers."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 555, $official_bank_source${"itemId":"1888cb1e-5eee-5668-a9c1-1fc0d42e2cd1","questionId":"5ef27542-17f7-57f4-af59-5450a8dcfd2a","sourceKey":"bank:ENT211:ENT211-W12-075","payload":{"prompt":"A young agritech founder in Kaduna raises start-up money from hundreds of small backers through an online crowdfunding platform. Which impact of digital technology is illustrated?","options":["Cost reduction and efficiency","Scalability and business growth","Improved market access","Financial inclusion and access to capital"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Digital technology improves access to loans, crowdfunding and investors, which is financial inclusion and access to capital. Option C is about reaching more customers, option A is about lowering costs, and option B is about growing without costs rising as fast."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 556, $official_bank_source${"itemId":"fc01d29b-a7dd-51b1-9b1d-f6b49b666240","questionId":"ff156205-ebd4-5a00-870c-1a4cde8448df","sourceKey":"bank:ENT211:ENT211-W12-076","payload":{"prompt":"Which of the following is NOT one of the impacts of digital technology on entrepreneurial growth?","options":["Innovation and new business models","Cost reduction and efficiency","Professional business presence","Improved market access"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Improved market access, cost reduction and efficiency, and innovation and new business models are all impacts of digital technology. Professional business presence is an importance of a virtual office, so C does not fit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 557, $official_bank_source${"itemId":"bb640555-f0df-59fe-94c2-45ea7c1a3c78","questionId":"85351870-38ff-5338-bb39-8a4f18282904","sourceKey":"bank:ENT211:ENT211-W12-077","payload":{"prompt":"How many impacts of digital technology on entrepreneurial growth are identified?","options":["Five","Eight","Four","Six"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Six impacts are identified: improved market access, cost reduction and efficiency, innovation and new business models, enhanced customer engagement, financial inclusion and access to capital, and scalability and business growth. Option A matches the number of virtual office features, and option B matches the number of e-commerce strategies."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 558, $official_bank_source${"itemId":"de3f4c2a-7441-5255-9f4d-e9f1b25bbdbb","questionId":"e5b16630-6651-5d35-83bd-8728ac6578ef","sourceKey":"bank:ENT211:ENT211-W12-078","payload":{"prompt":"A business solution that allows organizations and entrepreneurs to operate remotely by providing digital services such as a business address, communication tools and administrative support, without the need for a physical office space, is called a","options":["Digital marketplace for services","Online networking platform","Virtual office","E-commerce platform"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"A virtual office lets a business run remotely with an address, communication tools and admin support, but no physical office. Option B is about building relationships online, option D is about online selling, and option A is an e-commerce opportunity."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 559, $official_bank_source${"itemId":"7faee651-fd5b-5186-8825-1dbea167b3b4","questionId":"c4692240-1b74-5997-8280-967c2b8de810","sourceKey":"bank:ENT211:ENT211-W12-079","payload":{"prompt":"A virtual office provides digital services such as","options":["Online tax payment and e-visa applications","A business address, communication tools and administrative support","Budgeting, costing and pricing","Streaming, podcasting and wellness apps"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"A virtual office supplies a business address, communication tools and administrative support so the business can work remotely. Option D mixes digital media and health businesses, option C is financial knowledge, and option A gives examples of G2C e-commerce."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 560, $official_bank_source${"itemId":"33a1d593-4716-5883-b179-99a19d6355fd","questionId":"f3edd951-e6b2-5f34-a3ef-978951a043ee","sourceKey":"bank:ENT211:ENT211-W12-080","payload":{"prompt":"Which of the following is NOT one of the key features of a virtual office?","options":["Registered business address","Order tracking and automated notification","Virtual receptionist / call answering services","Mail handling and forwarding"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"A registered business address, mail handling and forwarding, and virtual receptionist or call answering services are all key features of a virtual office. Order tracking and automated notification belongs to the e-commerce strategy of managing logistics and order fulfilment."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 561, $official_bank_source${"itemId":"3486c4d8-6950-5aa0-b388-fab7042462c8","questionId":"008b6460-5725-5904-95d4-12f9ade18534","sourceKey":"bank:ENT211:ENT211-W12-081","payload":{"prompt":"Google Workspace and Microsoft 365 are examples of which key feature of a virtual office?","options":["Registered business address","Virtual receptionist / call answering services","Cloud-based collaboration tools","Online meeting tools"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Google Workspace and Microsoft 365 are given as cloud-based collaboration tools. Option D is illustrated by Zoom and Microsoft Teams, while options A and B are address and call-answering services, not software suites."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 562, $official_bank_source${"itemId":"690e29a5-a109-5f35-aef3-98894ce2a2ae","questionId":"383349aa-b50a-5345-81e8-944f94286ce6","sourceKey":"bank:ENT211:ENT211-W12-082","payload":{"prompt":"Among the key features of a virtual office, Zoom and Microsoft Teams are examples of","options":["Registered business address","Online meeting tools","Cloud-based collaboration tools","Mail handling and forwarding"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Zoom and Microsoft Teams are the examples of online meeting tools. Option C is illustrated by Google Workspace and Microsoft 365, and options D and A are address and mail services rather than meeting software."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 563, $official_bank_source${"itemId":"d6322373-80c2-542c-9d63-92854a6499f6","questionId":"bfd9f50e-811f-5328-9455-20177c9ba7ea","sourceKey":"bank:ENT211:ENT211-W12-083","payload":{"prompt":"Regus and WeWork are listed as virtual office tools that provide","options":["Team communication","Email and document collaboration","Virtual office address and admin services","Virtual meetings"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Regus and WeWork provide a virtual office address and administrative services. Option B is what Google Workspace does, option D is Zoom or Microsoft Teams, and option A is Slack."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 564, $official_bank_source${"itemId":"867a4af5-9876-587b-be98-e64f019da204","questionId":"9178f95c-774c-577c-9566-fa10ba426157","sourceKey":"bank:ENT211:ENT211-W12-084","payload":{"prompt":"As a virtual office tool, Google Workspace is used for","options":["Virtual office address and admin services","Virtual meetings","Email and document collaboration","Team communication"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Google Workspace is listed for email and document collaboration. Option B is the role of Zoom and Microsoft Teams, option D is Slack, and option A is Regus and WeWork."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 565, $official_bank_source${"itemId":"0df1f41f-b900-51b0-b362-40d5a782cbda","questionId":"a5b65e5c-dca3-5aad-bd21-2f60cac5e014","sourceKey":"bank:ENT211:ENT211-W12-085","payload":{"prompt":"Which virtual office tool is listed for team communication?","options":["Regus","Google Workspace","Slack","Shopify"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Slack is the virtual office tool listed for team communication. Option A provides a virtual office address and admin services, option B handles email and document collaboration, and option D is an e-commerce platform."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 566, $official_bank_source${"itemId":"39e9017c-b6c4-5f79-b225-85c6f9711b76","questionId":"fe5232ca-2803-5c9f-992c-05ddd2ecc76c","sourceKey":"bank:ENT211:ENT211-W12-086","payload":{"prompt":"A two-person consulting firm in Port Harcourt has no physical office, but it pays a provider for a registered business address and someone to receive its mail and answer calls. The firm is using a","options":["Customer relationship management system","Business-to-government platform","Virtual office","Dropshipping business"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"A registered address, mail handling and call answering without a physical office are features of a virtual office. Option D is an e-commerce opportunity, option B is a type of e-commerce, and option A is a data and customer management tool like HubSpot."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 567, $official_bank_source${"itemId":"3bdbb227-6314-5a07-9172-f68144561791","questionId":"a6c838ed-ff40-5dc5-a2a5-4594fe1c9d63","sourceKey":"bank:ENT211:ENT211-W12-087","payload":{"prompt":"Which importance of a virtual office reduces start-up and operational costs by eliminating expenses related to rent, utilities and physical infrastructure?","options":["Professional business presence","Access to global talents","Cost efficiency","Flexible and work life balance"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Cutting rent, utilities and infrastructure costs is cost efficiency. Option B is about hiring skilled people remotely, option A is about having a credible address and professional services, and option D is about working from any location."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 568, $official_bank_source${"itemId":"291b3a94-efb7-55a4-a7b3-522ecba683a5","questionId":"c557e2f4-3b79-5b26-b5f8-b375611a45b9","sourceKey":"bank:ENT211:ENT211-W12-088","payload":{"prompt":"The ability of entrepreneurs to recruit skilled professionals remotely, increasing access to diverse and specialized people, is the virtual office importance called","options":["Resource mobilization","Scalability and business growth","Access to global talents","Cost efficiency"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Recruiting skilled professionals from anywhere is access to global talents. Option A is an importance of online networking about funding and alliances, option B is about expanding or downsizing easily, and option D is about lower costs."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 569, $official_bank_source${"itemId":"1f5378bd-7768-5b21-8515-2fe547b70721","questionId":"d61dd61c-7ee0-58df-b564-70f5dd532d2c","sourceKey":"bank:ENT211:ENT211-W12-089","payload":{"prompt":"A virtual office providing entrepreneurs with a credible business address, mail handling and professional communication services is the importance called","options":["Access to global talents","Professional business presence","Market visibility and brand building","Flexible and work life balance"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"A credible address, mail handling and professional communication services give a business a professional presence. Option C is an importance of online networking through social media promotion, option D is about working from anywhere, and option A is about remote recruitment."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 570, $official_bank_source${"itemId":"0e43bb02-4e07-5f67-8579-481707056326","questionId":"8a9a8d4a-7023-5641-9d2f-ec72fd8e4182","sourceKey":"bank:ENT211:ENT211-W12-090","payload":{"prompt":"Entrepreneurs being able to operate from any location, enabling flexible working arrangements and improved productivity, is the virtual office importance called","options":["Professional business presence","Cost efficiency","Scalability and business growth","Flexible and work life balance"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Working from any location with flexible arrangements is flexibility and work-life balance. Option B is about saving rent and utilities, option A is about a credible address, and option C is about expanding or downsizing easily."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 571, $official_bank_source${"itemId":"904367e2-8284-55c7-be46-653e4e7b76b2","questionId":"1f8376d2-046a-515e-8aa6-d1e2a5da9cfd","sourceKey":"bank:ENT211:ENT211-W12-091","payload":{"prompt":"As an importance of a virtual office, 'Scalability and Business Growth' means that businesses can","options":["Recruit skilled professionals remotely","Promote their ventures and build brand awareness","Expand or downsize operations easily without relocation or heavy capital investment","Eliminate expenses on rent and utilities"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Virtual office systems let a business grow or shrink without moving premises or spending heavily. Option A is access to global talents, option D is cost efficiency, and option B is an importance of online networking."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 572, $official_bank_source${"itemId":"f9fadf72-0e9b-5533-a7b5-6bdccc57d40c","questionId":"73e1a916-ca2b-550d-95b0-e7f6517d33c5","sourceKey":"bank:ENT211:ENT211-W12-092","payload":{"prompt":"Which of the following is NOT an importance of a virtual office to entrepreneurship?","options":["Access to global talents","Cost efficiency","Resource mobilization","Professional business presence"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Cost efficiency, access to global talents and professional business presence are all importances of a virtual office. Resource mobilization is an importance of online networking, so C is the odd one out."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 573, $official_bank_source${"itemId":"8b29a899-921d-5a5a-a70a-35d2b43b1a39","questionId":"2f1d7114-a7dd-52e6-ab76-2bc1e20212af","sourceKey":"bank:ENT211:ENT211-W12-093","payload":{"prompt":"A Lagos software startup hires a data analyst in Kano and a designer in Nairobi, all working remotely through its virtual office. Which importance of a virtual office does this show?","options":["Access to global talents","Knowledge sharing and learning","Cost efficiency","Professional business presence"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Hiring skilled people remotely from different places is access to global talents. Option D is about a credible address and services, option C is about saving on rent and utilities, and option B is an importance of online networking."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 574, $official_bank_source${"itemId":"8334c822-524c-52ce-a357-d00cec27e737","questionId":"26f39fca-981a-5b73-a7bf-ce554450ce9d","sourceKey":"bank:ENT211:ENT211-W12-094","payload":{"prompt":"The use of internet-based applications that enable the creation and exchange of user-generated content and facilitate interaction among individuals and organizations is","options":["Virtual office","Electronic commerce","Digital entrepreneurship","Online networking"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Online networking uses internet-based applications for sharing user-generated content and interacting with people and organizations. Option A is a remote business setup with address and admin support, option B is buying and selling online, and option C is building ventures with digital technologies."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 575, $official_bank_source${"itemId":"fbe9671b-f1a1-5b5c-a4a9-97d6062ab231","questionId":"08ea32af-c9b5-5896-b014-8389e4157b03","sourceKey":"bank:ENT211:ENT211-W12-095","payload":{"prompt":"Online networking involves social interaction and relationship building through digitally mediated networks that","options":["Require a registered business address","Depend on physical office space","Transcend time and space constraints","Are limited to government agencies"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Online networking builds relationships through digital networks that are not limited by time or distance. Option A is a virtual office feature, option B is the opposite of what digital networks need, and option D confuses it with B2G or G2C e-commerce."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 576, $official_bank_source${"itemId":"22275ee4-33a2-53ed-9496-49f6d212503e","questionId":"1458a857-890b-57f4-8f4f-a4d3115368a1","sourceKey":"bank:ENT211:ENT211-W12-096","payload":{"prompt":"Online networking is the use of digital platforms and internet tools to create and sustain relationships for","options":["Government procurement only","Buying and selling goods only","Professional, social and entrepreneurial purposes","Codifying and documenting knowledge"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"This definition stresses creating and sustaining relationships for professional, social and entrepreneurial purposes. Option B is closer to e-commerce, option A describes B2G platforms, and option D describes explicit knowledge."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 577, $official_bank_source${"itemId":"1986cd07-9f17-5ed0-8722-3096ca9a9a7c","questionId":"7771257a-8db6-5d61-8d84-7fd30628e85b","sourceKey":"bank:ENT211:ENT211-W12-097","payload":{"prompt":"Online networking platforms enabling entrepreneurs to identify customers, partners, investors and suppliers beyond local boundaries is the importance called","options":["Market visibility and brand building","Resource mobilization","Access to business opportunities","Access to global talents"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Finding customers, partners, investors and suppliers beyond local boundaries is access to business opportunities. Option B is about funding, collaborations and alliances, option A is about promotion and brand awareness, and option D is a virtual office importance about remote hiring."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 578, $official_bank_source${"itemId":"ed52cbd9-0735-5643-8c23-81ec5c05dbfe","questionId":"7f20c488-b59c-5aaa-ae54-8c247d6303e3","sourceKey":"bank:ENT211:ENT211-W12-098","payload":{"prompt":"Online networks facilitating access to funding opportunities, collaborations and strategic alliances is the importance called","options":["Knowledge sharing and learning","Innovation and collaboration","Cost efficiency","Resource mobilization"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Accessing funding, collaborations and strategic alliances through online networks is resource mobilization. Option A is about insights and mentorship, option B is about co-creation and idea exchange, and option C is a virtual office importance about saving costs."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 579, $official_bank_source${"itemId":"23eadfb9-9144-5dd5-919f-6049136548fa","questionId":"76813aa9-5f0e-5226-b17a-c7c8be8ff802","sourceKey":"bank:ENT211:ENT211-W12-099","payload":{"prompt":"Halima joins an online professional community of fashion entrepreneurs where she picks up industry insights, best practices and a mentor. Which importance of online networking does this show?","options":["Market visibility and brand building","Knowledge sharing and learning","Resource mobilization","Access to business opportunities"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Gaining industry insights, best practices and mentorship from online professional communities is knowledge sharing and learning. Option C is about funding and alliances, option A is about promoting the venture, and option D is about finding customers, partners and suppliers."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 580, $official_bank_source${"itemId":"1f7cdc3b-dd16-5cdd-a370-99e23fe2c2a6","questionId":"deae8db9-3efa-5983-9711-587a80d986e9","sourceKey":"bank:ENT211:ENT211-W12-100","payload":{"prompt":"Digital networks encouraging collaboration, co-creation and idea exchange among entrepreneurs and stakeholders is the online networking importance called","options":["Knowledge sharing and learning","Resource mobilization","Innovation and collaboration","Access to business opportunities"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Co-creation and idea exchange among entrepreneurs and stakeholders is innovation and collaboration. Option A is about learning from insights and mentors, option B is about funding and alliances, and option D is about finding customers and partners."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 581, $official_bank_source${"itemId":"9cec77cf-e037-5842-a2ec-c21d59762c25","questionId":"3a07a394-eec0-5847-b476-9b8bdb05bc39","sourceKey":"bank:ENT211:ENT211-W12-101","payload":{"prompt":"A skincare startup in Ibadan uses Instagram and LinkedIn posts to promote its products and make more people aware of its brand. Which importance of online networking is this?","options":["Professional business presence","Knowledge sharing and learning","Resource mobilization","Market visibility and brand building"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Using social media and professional platforms to promote a venture and build brand awareness is market visibility and brand building. Option A is a virtual office importance about a credible address, option C is about funding and alliances, and option B is about insights and mentorship."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 582, $official_bank_source${"itemId":"2cc594dc-7c7b-58bb-b440-a314f97e8807","questionId":"66332e2c-5352-5e72-91bd-ba2b0cadae33","sourceKey":"bank:ENT211:ENT211-W12-102","payload":{"prompt":"Which of the following is NOT an importance of online networking to entrepreneurship?","options":["Resource mobilization","Market visibility and brand building","Knowledge sharing and learning","Cost efficiency"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Resource mobilization, knowledge sharing and learning, and market visibility and brand building are all importances of online networking. Cost efficiency is an importance of a virtual office, so D is the odd one out."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 583, $official_bank_source${"itemId":"b71cadee-ce26-53b9-83a3-360874e92397","questionId":"613e6827-b802-5b9e-9431-fe6831e82144","sourceKey":"bank:ENT211:ENT211-W12-103","payload":{"prompt":"The buying and selling of goods and services, as well as the exchange of money and data, through electronic networks, primarily the internet, is","options":["Digital technology","Electronic commerce (e-commerce)","Virtual office","Online networking"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"E-commerce is buying and selling goods and services, and exchanging money and data, over electronic networks, mainly the internet. Option D is about relationships online, option A refers to the computing tools themselves, and option C is a remote business setup."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 584, $official_bank_source${"itemId":"2a5d4336-033f-55fd-9eb2-a027ce7b9c42","questionId":"74789c23-b81a-5e87-964b-f75b1aecac88","sourceKey":"bank:ENT211:ENT211-W12-104","payload":{"prompt":"E-commerce is conducted through electronic networks, primarily","options":["Physical shops","The internet","Government agencies","Telephone landlines"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"E-commerce takes place over electronic networks, mainly the internet. Option A is traditional commerce, and option C is a party in some types of e-commerce rather than the network itself. Option D is an older communication channel, not the network e-commerce mainly runs on."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 585, $official_bank_source${"itemId":"4c73a3d2-738c-56c6-ac5d-8f8e11313ab0","questionId":"6ce26b25-a38d-5ef1-a7d6-9680d917f31d","sourceKey":"bank:ENT211:ENT211-W12-105","payload":{"prompt":"E-commerce involves commercial transactions involving the exchange of value conducted over","options":["Digital networks","Physical marketplaces","Barter systems","Registered business addresses"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"E-commerce is commercial transactions that exchange value over digital networks. Option B describes traditional trade, option C is direct exchange of goods without digital networks, and option D is a virtual office feature."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 586, $official_bank_source${"itemId":"6c622c68-37a3-50c8-8bdd-b9fd3fce539c","questionId":"c95b9c90-de70-59b2-a06e-72435d080a7f","sourceKey":"bank:ENT211:ENT211-W12-106","payload":{"prompt":"E-commerce is the sale or purchase of goods or services conducted over computer network by methods specifically designed for","options":["Receiving or placing orders","Codifying tacit knowledge","Managing virtual receptionists","Recruiting global talents"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"In this definition, e-commerce uses computer networks with methods designed specifically for receiving or placing orders. Option B relates to explicit knowledge, option D is a virtual office importance, and option C is a virtual office feature."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 587, $official_bank_source${"itemId":"5fee5cf2-ff90-5254-ae2d-027145c7720f","questionId":"66545d72-392f-5947-8e9b-8cab50f00aec","sourceKey":"bank:ENT211:ENT211-W12-107","payload":{"prompt":"Businesses selling products or services directly to individual consumers online, as Jumia, Amazon and Konga do, is called","options":["Business-to-Consumer (B2C)","Consumer-to-Business (C2B)","Business-to-Business (B2B)","Consumer-to-Consumer (C2C)"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"When a business sells directly to individual consumers online, it is B2C, like Jumia, Amazon and Konga. Option C is business selling to other businesses, option D is individuals selling to individuals, and option B is individuals offering services to businesses."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 588, $official_bank_source${"itemId":"e533e6f9-e529-5c32-a73b-970edb4ae148","questionId":"3a0b062e-ed3a-5e43-89d9-a2af83d6d139","sourceKey":"bank:ENT211:ENT211-W12-108","payload":{"prompt":"Alibaba and software subscriptions sold to companies are examples of which type of e-commerce?","options":["Government-to-Consumer (G2C)","Consumer-to-Business (C2B)","Business-to-Consumer (B2C)","Business-to-Business (B2B)"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Alibaba and software subscriptions involve businesses selling to other businesses through digital platforms, which is B2B. Option C is selling to individual consumers, option B is individuals offering services to businesses, and option A is government serving citizens."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 589, $official_bank_source${"itemId":"82b1cdf9-4440-5706-93f7-f1ec749d8bff","questionId":"5ae33c6d-9722-588d-badc-f1be089fcd6b","sourceKey":"bank:ENT211:ENT211-W12-109","payload":{"prompt":"eBay, Facebook Marketplace and Jiji.ng are examples of","options":["Consumer-to-Consumer (C2C)","Business-to-Consumer (B2C)","Business-to-Business (B2B)","Consumer-to-Business (C2B)"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"On eBay, Facebook Marketplace and Jiji.ng, individuals sell directly to other individuals, which is C2C. Option B is a business selling to consumers like Jumia, option C is business to business like Alibaba, and option D is individuals serving businesses like Upwork freelancers."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 590, $official_bank_source${"itemId":"adb8251a-a9f0-5f16-83b7-07afe3d36254","questionId":"b0bf50d5-f70e-5539-9e01-4e82de47689d","sourceKey":"bank:ENT211:ENT211-W12-110","payload":{"prompt":"Individuals offering products or services to businesses, such as a freelancer offering services on Upwork, is","options":["Consumer-to-Consumer (C2C)","Business-to-Government (B2G)","Consumer-to-Business (C2B)","Business-to-Consumer (B2C)"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"When an individual provides products or services to a business, like a freelancer on Upwork, it is C2B. Option A is individuals selling to other individuals, option D is the reverse direction, business to individuals, and option B is businesses serving government agencies."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 591, $official_bank_source${"itemId":"f6dd9bb1-3084-58c6-9b4b-5a00923ef7b1","questionId":"1493b119-dd1d-5a81-82ee-fb74e2bc7bdf","sourceKey":"bank:ENT211:ENT211-W12-111","payload":{"prompt":"Influencers promoting brands are given as an example of which type of e-commerce?","options":["Business-to-Business (B2B)","Consumer-to-Business (C2B)","Consumer-to-Consumer (C2C)","Business-to-Consumer (B2C)"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"An influencer is an individual offering a promotional service to a business, which makes it C2B. Option D would be a business selling to individuals, option A is business to business, and option C is individual to individual."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 592, $official_bank_source${"itemId":"72df94b4-c25d-5305-87a6-83f333744152","questionId":"6e8128e3-3128-5e7a-8dcc-711f16d34015","sourceKey":"bank:ENT211:ENT211-W12-112","payload":{"prompt":"Online procurement portals and e-tendering systems are examples of","options":["Consumer-to-Business (C2B)","Business-to-Business (B2B)","Business-to-Government (B2G)","Government-to-Consumer (G2C)"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Procurement portals and e-tendering let businesses supply goods or services to government agencies, which is Business-to-Government. Option D is government delivering services to citizens, option B is businesses selling to other businesses, and option A is individuals offering services to businesses."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 593, $official_bank_source${"itemId":"db15587c-b355-5bce-a7e2-0177d61eb84e","questionId":"ab1f4dca-4097-5abc-91cd-de59eed8c894","sourceKey":"bank:ENT211:ENT211-W12-113","payload":{"prompt":"Government services delivered electronically to citizens, such as an online tax payment platform or an e-visa and passport application system, is","options":["Business-to-Government (B2G)","Consumer-to-Business (C2B)","Government-to-Consumer (G2C)","Business-to-Consumer (B2C)"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"When government delivers its services electronically to citizens, it is G2C. Option A is the reverse kind of link, with businesses supplying government, option B is individuals serving businesses, and option D is businesses selling to consumers."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 594, $official_bank_source${"itemId":"f89fc11f-065e-51f4-87d6-0459eef9c532","questionId":"283f6a15-9835-554c-b9f7-86acfb458629","sourceKey":"bank:ENT211:ENT211-W12-114","payload":{"prompt":"Tobi, a 200-level student, sells his used phone to another student through a listing on Jiji.ng. This transaction is","options":["Consumer-to-Consumer (C2C)","Consumer-to-Business (C2B)","Business-to-Consumer (B2C)","Business-to-Business (B2B)"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"One individual selling directly to another through an online marketplace like Jiji.ng is C2C. Option C would need a business as the seller, option B would need a business as the buyer, and option D needs businesses on both sides."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 595, $official_bank_source${"itemId":"e08cf060-09f9-554e-853e-f3aa8bd1dbb9","questionId":"d08d0828-26d9-5429-9720-ed8373d822d0","sourceKey":"bank:ENT211:ENT211-W12-115","payload":{"prompt":"A construction company in Abuja submits its bid for a road contract through a government e-tendering system. Which type of e-commerce is this?","options":["Business-to-Consumer (B2C)","Business-to-Business (B2B)","Government-to-Consumer (G2C)","Business-to-Government (B2G)"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"A business providing goods or services to a government agency through e-tendering is Business-to-Government. Option C is government serving individual citizens, option B is a business selling to another business, and option A is a business selling to individual consumers."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 596, $official_bank_source${"itemId":"200a7212-c9b7-5ef4-82f0-a570b148c954","questionId":"8e766a7b-6c78-5280-b857-8fb9549972ba","sourceKey":"bank:ENT211:ENT211-W12-116","payload":{"prompt":"Amaka, a Nigerian citizen, pays her personal income tax through an online government tax payment platform. This is an example of","options":["Business-to-Government (B2G)","Consumer-to-Consumer (C2C)","Consumer-to-Business (C2B)","Government-to-Consumer (G2C)"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"A government service delivered electronically to a citizen, such as online tax payment, is G2C. Option A involves businesses supplying government, option C involves individuals serving businesses, and option B involves individuals trading with each other."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 597, $official_bank_source${"itemId":"71ecfcd7-9caf-5524-b0f5-bbad4cdbfa62","questionId":"18901c52-7083-55c7-ad06-082f58639f01","sourceKey":"bank:ENT211:ENT211-W12-117","payload":{"prompt":"Seyi, a freelance graphic designer in Ilorin, offers logo design services to companies through Upwork. Which type of e-commerce is this?","options":["Consumer-to-Consumer (C2C)","Consumer-to-Business (C2B)","Business-to-Consumer (B2C)","Business-to-Business (B2B)"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"An individual freelancer offering services to businesses on Upwork is exactly the C2B example. Option D needs a business as the seller, option C is a business selling to individuals, and option A is individuals selling to individuals."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 598, $official_bank_source${"itemId":"28630722-8175-54a2-964e-5ee3bd8a0fc7","questionId":"fc94c274-0ad8-56c6-b557-9e8497e0dbbf","sourceKey":"bank:ENT211:ENT211-W12-118","payload":{"prompt":"How many types of e-commerce are identified?","options":["Five","Eight","Four","Six"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Six types are identified: B2C, B2B, C2C, C2B, Business-to-Government and G2C. Option A matches the number of virtual office features, and option B matches the number of e-commerce strategies."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 599, $official_bank_source${"itemId":"27aa6a58-c1ed-5bb8-986b-84d385103ebf","questionId":"e336b687-069e-566d-bf1a-d6a151298492","sourceKey":"bank:ENT211:ENT211-W12-119","payload":{"prompt":"Which of the following is NOT one of the types of e-commerce?","options":["Business-to-Consumer (B2C)","Dropshipping business","Consumer-to-Business (C2B)","Government-to-Consumer (G2C)"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"B2C, C2B and G2C are all types of e-commerce. Dropshipping business is one of the entrepreneurial opportunities in e-commerce, not a type of e-commerce, so B is the answer."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 600, $official_bank_source${"itemId":"93f5bd58-10f5-5bf8-88e1-5d893ee51e31","questionId":"9d5666a7-91ab-539c-953a-99f7a06f0bae","sourceKey":"bank:ENT211:ENT211-W12-120","payload":{"prompt":"Entrepreneurs creating a website, mobile app or social media store to showcase products and services, using platforms like Shopify, Temu, Facebook or Instagram, is the e-commerce strategy called","options":["Choose the right e-commerce model","Focus on digital marketing strategies","Develop an online presence","Build trust and credibility"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Setting up a website, app or social media store to show products is developing an online presence. Option B is about visibility through SEO, social media and ads, option A is about picking B2C, B2B, C2C or C2B, and option D is about reviews and secure checkout."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 601, $official_bank_source${"itemId":"d85b42b6-4b67-5e0b-99c6-e87509d812a7","questionId":"6d6b58ac-f6cd-54f4-8951-72492958a2f3","sourceKey":"bank:ENT211:ENT211-W12-121","payload":{"prompt":"Under the strategy 'Develop an Online presence', entrepreneurs should ensure","options":["Customer reviews and ratings","Live chat and prompt customer support","Order tracking and automated notification","Clear product descriptions, pricing and images"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Developing an online presence includes making sure products have clear descriptions, prices and images. Option B belongs to optimizing customer experience, option C to managing logistics and order fulfilment, and option A to building trust and credibility."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 602, $official_bank_source${"itemId":"144a0825-ebff-530b-adf1-0c10c3773e66","questionId":"f77aa4fe-3d2f-516c-bbbe-da854c73643e","sourceKey":"bank:ENT211:ENT211-W12-122","payload":{"prompt":"Under the strategy 'Choose the Right E-Commerce Model', which model is recommended for freelancing and digital services?","options":["C2C","B2C","B2B","C2B"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"C2B is recommended for freelancing and digital services. Option B is for retail products, option C is for wholesale or services, and option A is for marketplaces."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 603, $official_bank_source${"itemId":"13dcb2e6-08b1-5662-9710-a5af6e4a7d05","questionId":"9dbd0d4a-b922-5783-8ba6-77776a509732","sourceKey":"bank:ENT211:ENT211-W12-123","payload":{"prompt":"When choosing the right e-commerce model, an entrepreneur selling in wholesale to other businesses should adopt","options":["C2C","B2C","C2B","B2B"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"B2B is recommended for wholesale or services. Option B is for retail products, option A is for marketplaces, and option C is for freelancing and digital services."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 604, $official_bank_source${"itemId":"3d9bf321-91a0-5348-b732-906c75d5c84d","questionId":"ea537bda-5868-5548-815f-abf8c52f1894","sourceKey":"bank:ENT211:ENT211-W12-124","payload":{"prompt":"The e-commerce strategy 'Implement Secure Online Payment System' recommends that entrepreneurs","options":["Partner with logistic providers for timely delivery","Run targeted online advertisements","Ensure easy navigation and fast loading websites","Integrate Paystack, Flutterwave, PayPal or bank transfers and offer mobile money and card payment options"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"A secure online payment system means offering multiple secure options such as Paystack, Flutterwave, PayPal, bank transfers, mobile money and cards. Option A belongs to managing logistics and order fulfilment, option B to digital marketing, and option C to optimizing customer experience."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 605, $official_bank_source${"itemId":"472dc741-ecde-5630-ba0b-c5abcbaa4c51","questionId":"6f691458-05af-52cc-bf2e-6d32dcdf5fd1","sourceKey":"bank:ENT211:ENT211-W12-125","payload":{"prompt":"Under the strategy 'Focus on Digital Marketing Strategies', e-commerce success depends on","options":["Visibility and customer engagement","Government procurement","Physical office location","Large workforce"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Digital marketing matters because e-commerce success depends on visibility and customer engagement, achieved through social media marketing, SEO, email marketing and targeted ads. Options C and D are things digital technology reduces the need for, and option B relates to B2G e-commerce."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 606, $official_bank_source${"itemId":"945218bf-610d-5cc5-b77e-0561aabfb168","questionId":"f0efd959-b13c-556c-921e-9ed5f399ee13","sourceKey":"bank:ENT211:ENT211-W12-126","payload":{"prompt":"Bola, who sells handmade bags online, starts using SEO, email marketing and targeted Instagram adverts to get more people to see her store. Which e-commerce strategy is she applying?","options":["Develop an online presence","Focus on digital marketing strategies","Build trust and credibility","Use data analytics for decision-making"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Using social media marketing, SEO, email marketing and targeted online ads is the digital marketing strategy. Option A is setting up the website or store in the first place, option D is tracking customer behaviour and sales trends, and option C is reviews, secure checkout and return policies."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 607, $official_bank_source${"itemId":"9dec5aae-bb4a-57cc-aabe-d524f63a2281","questionId":"2cc0e147-1804-521d-8289-fc16f180b486","sourceKey":"bank:ENT211:ENT211-W12-127","payload":{"prompt":"Ensuring easy navigation and fast-loading websites and providing live chat and prompt customer support make up the e-commerce strategy","options":["Optimize customer experience","Develop an online presence","Build trust and credibility","Manage logistics and order fulfilment"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Easy navigation, fast pages, live chat and quick support are about optimizing customer experience, because user-friendly design improves satisfaction and retention. Option B is creating the website or store, option D is delivery and tracking, and option C is reviews and secure checkout."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 608, $official_bank_source${"itemId":"9fe2effc-fd18-55b1-a879-79ff5e017ce6","questionId":"85cb19f2-72f9-57a3-acd2-de9f40e8f186","sourceKey":"bank:ENT211:ENT211-W12-128","payload":{"prompt":"Under the strategy 'Optimize Customer Experience', user-friendly design improves","options":["Access to loans and investors","Customer satisfaction and retention","Market positioning against competitors","Government service delivery"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"User-friendly design is said to improve customer satisfaction and retention. Option A belongs to the financial inclusion impact, option C relates to the business growth and competitiveness role, and option D relates to G2C e-commerce."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 609, $official_bank_source${"itemId":"3dd7f0f1-4023-5684-a095-5980f0bf7753","questionId":"6de5faf2-a85c-57b4-bc48-37a456693b27","sourceKey":"bank:ENT211:ENT211-W12-129","payload":{"prompt":"Partnering with logistic providers for timely delivery and using order tracking and automated notification make up the e-commerce strategy","options":["Implement secure online payment system","Manage logistics and order fulfilment","Use data analytics for decision-making","Optimize customer experience"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Delivery partnerships, order tracking and automated notifications are part of managing logistics and order fulfilment, since efficient delivery builds customer trust. Option D is about website design and support, option A is about payment options, and option C is about tracking sales trends to adjust pricing."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 610, $official_bank_source${"itemId":"ca83ed62-354d-5e84-8e89-eec65bdebc34","questionId":"249e4387-6eb9-57e5-ba40-9aef939594db","sourceKey":"bank:ENT211:ENT211-W12-130","payload":{"prompt":"Under the strategy 'Manage Logistics and Order Fulfilment', efficient delivery systems","options":["Reduce geographical barriers","Build customer trust","Create new legal entities","Replace the need for payment systems"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Efficient delivery systems are said to build customer trust. Option A is part of the improved market access impact of digital technology, and options C and D are not claims made about delivery."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 611, $official_bank_source${"itemId":"537dcd94-00da-5a3c-96b5-ea9fbcb765ac","questionId":"2e62335e-39d7-5262-9949-e4a01b892e00","sourceKey":"bank:ENT211:ENT211-W12-131","payload":{"prompt":"Tracking customer behaviour, sales trends and conversion rates, then adjusting pricing, promotions and inventory accordingly, is the e-commerce strategy","options":["Focus on digital marketing strategies","Use data analytics for decision-making","Optimize customer experience","Choose the right e-commerce model"],"correctOption":1,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Tracking behaviour, sales trends and conversion rates to adjust pricing, promotions and inventory is using data analytics for decision-making. Option A is about visibility through SEO and ads, option D is about choosing B2C, B2B, C2C or C2B, and option C is about navigation, speed and live chat."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 612, $official_bank_source${"itemId":"060bd714-7065-5d12-87ed-79a55d9ab5b4","questionId":"5d19abbd-fb7b-57a2-89c4-c3fd2843ead0","sourceKey":"bank:ENT211:ENT211-W12-132","payload":{"prompt":"Displaying customer reviews and ratings and using secure checkout systems and transparent return policies make up the e-commerce strategy","options":["Build trust and credibility","Manage logistics and order fulfilment","Use data analytics for decision-making","Optimize customer experience"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Reviews, ratings, secure checkout and transparent return policies are all about building trust and credibility, which is essential in online transactions. Option C, using data analytics, is about tracking customer behaviour and sales trends to adjust pricing and stock. Option D focuses on easy navigation and customer support, and option B on delivery and order tracking."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 613, $official_bank_source${"itemId":"8448e58d-bd12-5749-b3c7-ad2030e7672b","questionId":"b7f517c7-c155-5644-8a44-b9313ba160ac","sourceKey":"bank:ENT211:ENT211-W12-133","payload":{"prompt":"Which of the following is NOT one of the basic e-commerce strategies for entrepreneurship?","options":["Access to global talents","Build trust and credibility","Use data analytics for decision-making","Develop an online presence"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Developing an online presence, using data analytics for decision-making, and building trust and credibility are all e-commerce strategies. Access to global talents is an importance of a virtual office, so A is the answer."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 614, $official_bank_source${"itemId":"62e45145-ad82-5eed-83ba-185ef3befa63","questionId":"e3a08df0-4b31-55ae-9573-da52f7a14f86","sourceKey":"bank:ENT211:ENT211-W12-134","payload":{"prompt":"How many basic e-commerce strategies are presented for entrepreneurship?","options":["Eight","Five","Ten","Six"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"There are eight strategies, from developing an online presence through to building trust and credibility. Option D matches the six types of e-commerce, and option C matches the ten entrepreneurial opportunities in e-commerce."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 615, $official_bank_source${"itemId":"0958f93b-9add-5c7f-9259-2feebb07f491","questionId":"552ab7d5-3dac-5109-9a24-c98899ee8d8f","sourceKey":"bank:ENT211:ENT211-W12-135","payload":{"prompt":"Which of the following is an entrepreneurial opportunity in e-commerce?","options":["Dropshipping business","Tacit knowledge","Registered business address","Virtual receptionist services"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Dropshipping business is one of the entrepreneurial opportunities in e-commerce. Options D and C are features of a virtual office, and option B is a type of knowledge."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 616, $official_bank_source${"itemId":"5fca5416-faa3-5e59-8dbe-cae2ee8bec7b","questionId":"20767efd-fe64-56da-be25-d7f51b21238b","sourceKey":"bank:ENT211:ENT211-W12-136","payload":{"prompt":"Which of the following is NOT listed among the entrepreneurial opportunities in e-commerce?","options":["Social commerce","Affiliate marketing","Mobile commerce (M-commerce)","Mail handling and forwarding"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Affiliate marketing, social commerce and mobile commerce are all entrepreneurial opportunities in e-commerce. Mail handling and forwarding is a key feature of a virtual office, so D is the odd one out."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 617, $official_bank_source${"itemId":"f55f2351-6507-57a7-ac15-fbad77fc7cf7","questionId":"babb2c31-62b3-5269-8918-99b84548fd6a","sourceKey":"bank:ENT211:ENT211-W12-137","payload":{"prompt":"Among entrepreneurial opportunities in e-commerce, 'M-Commerce' stands for","options":["Media commerce","Managerial commerce","Mobile commerce","Market commerce"],"correctOption":2,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"M-Commerce means mobile commerce, which is listed as an entrepreneurial opportunity in e-commerce. The other options are not terms used for this opportunity."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_ent211', 'add', 618, $official_bank_source${"itemId":"d8d7b028-3c26-5520-bb83-9046207330ed","questionId":"550208fd-89e8-593b-b503-5b8869090a6e","sourceKey":"bank:ENT211:ENT211-W12-138","payload":{"prompt":"Which of the following is listed as an entrepreneurial opportunity in e-commerce?","options":["Online meeting tools","Cost reduction and efficiency","Knowledge sharing and learning","Local-to-global export platforms"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Local-to-global export platforms are one of the entrepreneurial opportunities in e-commerce. Option A is a virtual office feature, option C is an importance of online networking, and option B is an impact of digital technology."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 619, $official_bank_source${"itemId":"3639bd39-1f59-58f9-8492-8ff8cc7137ca","questionId":"a253f831-8e16-56ed-b3e9-85bb4051cd1f","sourceKey":"bank:ENT211:ENT211-W12-139","payload":{"prompt":"An entrepreneur in Lagos is looking for an e-commerce opportunity to pursue. Which of these is recognised as an entrepreneurial opportunity in e-commerce?","options":["Subscription-based e-commerce","Sustainable and green e-commerce","AI-enabled e-commerce solutions","All of the above"],"correctOption":3,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"Subscription-based e-commerce, sustainable and green e-commerce, and AI-enabled e-commerce solutions are all on the list of entrepreneurial opportunities in e-commerce, so D is correct. Picking only one of them would leave out the other two."}}$official_bank_source$::jsonb),
  ('official_bank_ent211', 'add', 620, $official_bank_source${"itemId":"ae97ff5e-86e3-54a5-9dfd-abe30cfa3bd7","questionId":"30cc9042-475b-5fbf-aea4-a165976f731c","sourceKey":"bank:ENT211:ENT211-W12-140","payload":{"prompt":"Online retail marketplaces and niche stores, digital marketplaces for services, and affiliate marketing are all examples of","options":["Entrepreneurial opportunities in e-commerce","Types of e-commerce","Key features of a virtual office","Impacts of digital technology on entrepreneurial growth"],"correctOption":0,"section":"Weeks 12-13: Contemporary Issues in Entrepreneurship","explanation":"These three items appear on the list of entrepreneurial opportunities in e-commerce. Option B refers to B2C, B2B, C2C, C2B, B2G and G2C, option C refers to things like a registered address and mail handling, and option D refers to items like improved market access."}}$official_bank_source$::jsonb);
